// Generated by scripts/pack-games.mjs. Do not edit by hand.
export const GAME_HTML = "<!DOCTYPE html>\n<html lang=\"en\"><head>\n<meta charset=\"utf-8\">\n<meta http-equiv=\"Content-Security-Policy\" content=\"default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data:; media-src data: blob:; connect-src 'none'; form-action 'none'; base-uri 'none'\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no,viewport-fit=cover\">\n<style>\n*{box-sizing:border-box;-webkit-tap-highlight-color:transparent;user-select:none;-webkit-user-select:none}\nhtml,body{margin:0;height:100%;overflow:hidden;background:#1e1b4b;font-family:system-ui,-apple-system,Roboto,sans-serif;color:#1e1b4b;touch-action:none}\n#top{position:absolute;left:0;right:0;top:0;height:52px;display:flex;align-items:center;gap:8px;padding:8px 10px;padding-top:max(8px,env(safe-area-inset-top));color:#fff}\n#back{background:rgba(255,255,255,.18);color:#fff;border:0;border-radius:12px;font:700 16px system-ui,sans-serif;padding:9px 12px}\n#score{flex:1;text-align:right;font-weight:800;font-size:15px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n#wrap{position:absolute;left:0;right:0;top:52px;bottom:0;display:flex;align-items:center;justify-content:center;padding:6px 6px max(6px,env(safe-area-inset-bottom))}\n#cv{display:block;border-radius:18px;touch-action:none;background:#fff}\n#ov{position:absolute;inset:52px 0 0 0;display:flex;align-items:center;justify-content:center;padding:16px}\n#ov[hidden]{display:none}\n.card{background:rgba(255,255,255,.97);border-radius:22px;padding:20px;text-align:center;max-width:320px;box-shadow:0 10px 30px rgba(0,0,0,.3)}\n.card h3{margin:4px 0 8px;font-size:24px}\n.card p{margin:6px 0;font-size:16px;line-height:1.35}\n.btn{display:block;width:100%;margin-top:10px;border:0;border-radius:14px;padding:13px;font:800 17px system-ui,sans-serif;color:#fff;background:#7c3aed}\n.btn.green{background:#15803d}.btn.ghost{background:#ede9fe;color:#5b21b6}\n.muted{color:#4c4f6b}.nb{color:#b45309;font-weight:800}\n.tix{margin:10px 0 4px;padding:10px 12px;border-radius:16px;background:#fff1f3;border:2px solid #fda4af;color:#9f1239}\n.tix .big{display:flex;align-items:center;justify-content:center;gap:8px;font:800 30px system-ui,sans-serif;color:#be123c}\n.tix .big small{font-size:16px;color:#9f1239}\n.tix .row{display:flex;justify-content:space-between;font-size:14px;color:#4c4f6b;padding:2px 2px}\n.tix .row b{color:#1e1b4b}.tix .jp{color:#b45309;font-weight:800;text-align:center;font-size:15px;margin-top:2px}\n.tix .note{font-size:13px;color:#4c4f6b;margin-top:4px}\n.strip{display:flex;justify-content:center;gap:3px;margin:-4px 0 6px}\n.strip i{display:block;width:26px;height:16px;background:#fb7185;border-radius:2px;border-left:2px dashed #ffe4e6;border-right:2px dashed #ffe4e6;animation:drop .35s ease-out both}\n@keyframes drop{from{transform:translateY(-14px);opacity:0}to{transform:none;opacity:1}}\n.coin{width:1.05em;height:1.05em;vertical-align:-.18em;display:inline-block}\n</style></head>\n<body>\n<div id=\"top\"><button id=\"back\" aria-label=\"Back to Arcade\">← Arcade</button><div id=\"score\"></div></div>\n<div id=\"wrap\"><canvas id=\"cv\"></canvas></div>\n<div id=\"ov\" hidden></div>\n<script>\n/* ---------- bridge to the app ---------- */\nconst INIT=window.__SS_INIT||{id:'derby',set:{diff:'normal',calm:false,sfx:true,voice:true,twice:false,grade:'23',cost:1,maxGames:0,maxMin:0},words:['cat','dog','sun'],sent:{},tokens:5,best:{},day:{games:0,ms:0},title:'Game',em:'🎮'};\nconst S={set:INIT.set,tokens:INIT.tokens,best:INIT.best};\nconst DAY={games:INIT.day.games,ms:INIT.day.ms};\n/* prizes from the Prize Counter that change how games look, e.g. {hoops:true} */\nconst LOOKS=INIT.looks||{};\nconst SOCCERBALL=LOOKS.soccer?'🌍':'⚽';\nfunction post(m){try{window.ReactNativeWebView.postMessage(JSON.stringify(m));}catch(e){}}\nlet msBuf=0;\nfunction flushMs(){if(msBuf>0){post({t:'ms',ms:Math.round(msBuf)});msBuf=0;}}\nsetInterval(flushMs,5000);\ndocument.addEventListener('visibilitychange',()=>{if(document.hidden)flushMs();});\n\n/* ---------- small helpers the games use ---------- */\nconst $=s=>document.querySelector(s);\nconst shuffle=a=>{for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};\nconst rnd=(a,b)=>a+Math.random()*(b-a);\nconst pick=a=>a[Math.floor(Math.random()*a.length)];\nconst plural=(n,w)=>n+' '+w+(n===1?'':'s');\nconst norm=w=>String(w||'').trim().toLowerCase().replace(/[’‘]/g,\"'\");\nconst escRe=s=>s.replace(/[.*+?^${}()|[\\]\\\\]/g,'\\\\$&');\nconst STARTERS={easy:['cat','dog','sun','hat','run','big','red','fish','jump','play']};\nconst allWords=()=>INIT.words.slice();\nfunction builtinSent(w){return INIT.sent[norm(w)]||'';}\nconst DF=()=>({easy:.78,normal:1,hard:1.22}[S.set.diff]||1);\nconst TOL=()=>({easy:1.35,normal:1,hard:.8}[S.set.diff]||1);\n/* speech goes to the app, which uses the phone's voices */\nfunction speak(text,onFail,opt){if(!S.set.voice){if(onFail)onFail('muted');return false;}post({t:'speak',text:String(text),raw:!!(opt&&opt.raw)});return true;}\n\n/* ---------- sound effects (Web Audio, same as the web version) ---------- */\nlet AC=null;\nfunction ac(){\n  if(!S.set.sfx)return null;\n  if(!AC){try{AC=new(window.AudioContext||window.webkitAudioContext)();}catch(e){return null;}}\n  if(AC.state==='suspended'){try{AC.resume();}catch(e){}}\n  return AC;\n}\nfunction tone(f,d,type,vol,when,slide){\n  const a=ac();if(!a)return;\n  const t=a.currentTime+(when||0);\n  const o=a.createOscillator(),g=a.createGain();\n  o.type=type||'sine';o.frequency.setValueAtTime(f,t);\n  if(slide)o.frequency.exponentialRampToValueAtTime(slide,t+d);\n  g.gain.setValueAtTime(vol||.12,t);g.gain.exponentialRampToValueAtTime(.0008,t+d);\n  o.connect(g);g.connect(a.destination);o.start(t);o.stop(t+d+.03);\n}\nfunction noise(d,vol,when){\n  const a=ac();if(!a)return;\n  const t=a.currentTime+(when||0);\n  const len=Math.floor(a.sampleRate*d),buf=a.createBuffer(1,len,a.sampleRate),ch=buf.getChannelData(0);\n  for(let i=0;i<len;i++)ch[i]=(Math.random()*2-1)*(1-i/len);\n  const s=a.createBufferSource(),g=a.createGain();s.buffer=buf;g.gain.value=vol||.15;\n  s.connect(g);g.connect(a.destination);s.start(t);\n}\nconst SFX={\n  correct:()=>{tone(523,.13,'triangle',.14);tone(659,.13,'triangle',.14,.1);tone(784,.25,'triangle',.14,.2);},\n  coin:()=>{tone(988,.08,'square',.06);tone(1319,.3,'square',.06,.08);},\n  tick:()=>tone(1500,.03,'square',.03),\n  wrong:()=>tone(240,.3,'sawtooth',.06,0,150),\n  swoosh:()=>noise(.14,.07),\n  hit:()=>{tone(170,.08,'square',.16);noise(.12,.25);},\n  hr:()=>{tone(170,.08,'square',.16);noise(.12,.3);[523,659,784,1047,1319].forEach((f,i)=>tone(f,.2,'triangle',.12,.15+i*.09));noise(1.2,.05,.2);},\n  miss:()=>tone(160,.25,'sawtooth',.05,0,110),\n  tick:()=>tone(420,.06,'square',.07),\n  jump:()=>tone(380,.16,'sine',.12,0,820),\n  bonk:()=>tone(130,.3,'square',.1,0,60),\n  star:()=>tone(1150,.12,'sine',.1,0,1900),\n  pop:()=>{noise(.07,.3);tone(620,.07,'sine',.1,0,180);},\n  nope:()=>tone(210,.15,'triangle',.1),\n  flip:()=>tone(720,.04,'sine',.06),\n  win:()=>[523,659,784,1047].forEach((f,i)=>tone(f,.2,'triangle',.12,i*.09))\n};\nfunction sfx(n){try{SFX[n]&&SFX[n]();}catch(e){}}\n\n/* ---------- engine ---------- */\nconst W=360,H=540;\nconst cv=$('#cv'),ctx=cv.getContext('2d');\nlet G=null,raf=0,last=0;\nfunction fitCanvas(){\n  const wrap=$('#wrap'),r=wrap.getBoundingClientRect();\n  const w=Math.max(200,Math.min(r.width-12,(r.height-12)*W/H));\n  cv.style.width=w+'px';cv.style.height=(w*H/W)+'px';\n  const dpr=Math.min(2.5,window.devicePixelRatio||1);\n  cv.width=Math.round(w*dpr);cv.height=Math.round(w*H/W*dpr);\n}\nwindow.addEventListener('resize',fitCanvas);\nfunction limitReason(){\n  if(S.set.maxGames&&DAY.games>=S.set.maxGames)return `That's all ${S.set.maxGames} games for today. Come back tomorrow! 🌙`;\n  if(S.set.maxMin&&DAY.ms>=S.set.maxMin*60000)return `Play time is up for today (${S.set.maxMin} min). Come back tomorrow! 🌙`;\n  return '';\n}\n/* a bug in one game should never freeze the screen: log it and keep the loop running */\nlet errCount=0;\nfunction reportErr(e){if(++errCount<=3)console.error('game error',G&&G.id,e&&e.message);if(errCount>300&&G&&!G.over){G.over=true;}}\n/* score bar: only touch the page when the text changes, and shrink the font to fit narrow phones */\nlet hudText='';\nfunction setHud(t){if(t===hudText)return;hudText=t;const el=$('#score');el.textContent=t;let f=15;el.style.fontSize=f+'px';while(el.scrollWidth>el.clientWidth&&f>10){f--;el.style.fontSize=f+'px';}}\nfunction loop(t){\n  const dt=Math.min(.05,Math.max(0,(t-last)/1000));last=t;\n  if(G){\n    if(G.started&&!G.over){\n      try{G.update(dt);}catch(e){reportErr(e);}\n      DAY.ms+=dt*1000;msBuf+=dt*1000;\n      if(S.set.maxMin&&DAY.ms>=S.set.maxMin*60000&&!G.over){G.over=true;G.timeUp=true;}\n    }\n    ctx.setTransform(cv.width/W,0,0,cv.height/H,0,0);\n    try{G.draw(ctx);}catch(e){reportErr(e);}\n    setHud(G.hud());\n    if(G.over&&!G.ended){G.ended=true;endGame();}\n  }\n  raf=requestAnimationFrame(loop);\n}\nfunction makeGame(id){const g=GAMES[id]();g.id=id;g.started=false;g.ended=false;return g;}\n// Token coin: our own picture (iPhone draws the coin emoji as a gray, moon-like coin).\nconst COIN_URI='data:image/svg+xml;base64,';\nconst COIN_IMG=new Image();COIN_IMG.src=COIN_URI;\nconst COIN_HTML='<img class=\"coin\" alt=\"tokens\" src=\"'+COIN_URI+'\">';\nfunction coinify(html){return String(html).split('\\u{1FA99}').join(COIN_HTML);}\nfunction overlay(html){const o=$('#ov');o.innerHTML=coinify(html);o.hidden=false;}\nfunction openGame(id){\n  fitCanvas();G=makeGame(id);\n  const lim=limitReason();\n  overlay(`<div class=\"card\"><h3>${INIT.em} ${INIT.title}</h3><p>${G.intro}</p>${lim?`<p class=\"nb\">${lim}</p>`:S.tokens>=S.set.cost?`<button class=\"btn green\" id=\"ovStart\">Start! · ${S.set.cost} 🪙</button>`:`<p class=\"muted\">You need ${plural(S.set.cost,'token')}. Spell words to earn more!</p>`}<button class=\"btn ghost\" id=\"ovBack\">Back to Arcade</button></div>`);\n  const s=$('#ovStart');if(s)s.addEventListener('click',()=>beginGame(id));\n  $('#ovBack').addEventListener('click',exit);\n  last=performance.now();cancelAnimationFrame(raf);raf=requestAnimationFrame(loop);\n}\nfunction beginGame(id){\n  if(limitReason()||S.tokens<S.set.cost){openGame(id);return;}\n  S.tokens-=S.set.cost;DAY.games++;post({t:'spend',cost:S.set.cost});ac();\n  G=makeGame(id);G.started=true;if(G.begin)G.begin();\n  $('#ov').hidden=true;\n}\nfunction endGame(){\n  flushMs();\n  const id=G.id,score=Math.floor(G.score);\n  const prev=S.best[id];const nb=prev==null||score>prev;\n  if(nb)S.best[id]=score;\n  post({t:'end',id,score});\n  sfx('win');\n  const lim=limitReason(),cost=S.set.cost;\n  const again=lim?`<p class=\"nb\">${lim}</p>`:S.tokens>=cost?`<button class=\"btn green\" id=\"ovAgain\">Play again · ${cost} 🪙</button>`:`<p class=\"muted\">Out of tokens. Spell more words to earn more!</p>`;\n  overlay(`<div class=\"card\"><div style=\"font-size:52px\">${G.timeUp?'⏰':nb&&prev!=null?'🏆':'🎉'}</div><h3>${G.timeUp?'Time for a break!':(G.endTitle||'Great game!')}</h3><p>Score: <b style=\"font-size:22px\">${score}</b></p><p class=\"${nb&&prev!=null?'nb':'muted'}\">${nb&&prev!=null?'New best score!':'Best: '+S.best[id]}</p><div id=\"tix\"></div>${again}<button class=\"btn ghost\" id=\"ovArcade\">Back to Arcade</button></div>`);\n  const a=$('#ovAgain');if(a)a.addEventListener('click',()=>beginGame(id));\n  $('#ovArcade').addEventListener('click',exit);\n}\nfunction exit(){flushMs();post({t:'exit'});}\n/* The app works out the tickets and sends them here to show. Built with DOM text only. */\nwindow.__tickets=function(r){\n  const box=$('#tix');if(!box||!r)return;\n  const total=Math.max(0,Math.min(99,Math.floor(+r.total)||0));\n  box.className='tix';box.textContent='';\n  const el=(tag,cls,txt)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(txt!=null)e.textContent=String(txt);return e;};\n  const strip=el('div','strip');for(let i=0;i<Math.min(6,Math.max(1,Math.ceil(total/3)));i++){const t=el('i');t.style.animationDelay=(i*.12)+'s';strip.appendChild(t);}\n  const big=el('div','big');const num=el('span',null,'+0');big.appendChild(num);big.appendChild(el('small',null,total===1?'ticket':'tickets'));\n  box.appendChild(strip);box.appendChild(big);\n  (Array.isArray(r.rows)?r.rows:[]).slice(0,4).forEach(x=>{if(!Array.isArray(x))return;const row=el('div','row');row.appendChild(el('span',null,String(x[0]).slice(0,40)));row.appendChild(el('b',null,'+'+(Math.floor(+x[1])||0)));box.appendChild(row);});\n  if(r.jackpot)box.appendChild(el('div','jp','🌟 LUCKY BONUS! +'+(Math.floor(+r.jackpot)||0)));\n  if(r.note)box.appendChild(el('div','note',String(r.note).slice(0,90)));\n  let n=0;const iv=setInterval(()=>{n++;num.textContent='+'+Math.min(n,total);sfx('tick');if(n>=total){clearInterval(iv);sfx(r.jackpot?'win':'coin');}},Math.max(40,600/Math.max(1,total)));\n  if(!total)clearInterval(iv);\n};\n$('#back').addEventListener('click',exit);\nfunction cvPt(e){const r=cv.getBoundingClientRect();return [(e.clientX-r.left)*W/r.width,(e.clientY-r.top)*H/r.height];}\ncv.addEventListener('pointerdown',e=>{\n  e.preventDefault();\n  if(!G||!G.started||G.over)return;\n  try{cv.setPointerCapture(e.pointerId);}catch(err){}\n  const [x,y]=cvPt(e);G.tap(x,y);\n});\ncv.addEventListener('pointerup',()=>{if(G&&G.release)G.release();});\ncv.addEventListener('pointercancel',()=>{if(G&&G.release)G.release();});\ncv.addEventListener('pointermove',e=>{if(!G||!G.started||G.over||!G.move)return;e.preventDefault();const [x,y]=cvPt(e);G.move(x,y);});\nwindow.addEventListener('keydown',e=>{if(G&&G.started&&!G.over&&G.key)G.key(e.key);});\n</script>\n<script>\n/* drawing helpers */\nconst EMOJI_FONT='\"Apple Color Emoji\",\"Segoe UI Emoji\",\"Noto Color Emoji\",sans-serif';\nfunction emo(c,ch,x,y,size,flip){if(ch==='\\u{1FA99}'&&typeof COIN_IMG!=='undefined'&&COIN_IMG.complete&&COIN_IMG.naturalWidth){c.drawImage(COIN_IMG,x-size/2,y-size/2,size,size);return;}c.save();c.fillStyle='#000';c.font=size+'px '+EMOJI_FONT;c.textAlign='center';c.textBaseline='middle';c.translate(x,y);if(flip)c.scale(-1,1);c.fillText(ch,0,0);c.restore();}\nfunction rr(c,x,y,w,h,r){r=Math.max(0,Math.min(r,w/2,h/2));c.beginPath();c.moveTo(x+r,y);c.arcTo(x+w,y,x+w,y+h,r);c.arcTo(x+w,y+h,x,y+h,r);c.arcTo(x,y+h,x,y,r);c.arcTo(x,y,x+w,y,r);c.closePath();}\nfunction burst(arr,x,y,colors,n,spd){for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,s=spd*(.35+Math.random()*.8);arr.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.7+Math.random()*.5,c:colors[i%colors.length],r:2+Math.random()*3});}}\nfunction stepParts(arr,dt,grav){for(let i=arr.length-1;i>=0;i--){const p=arr[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=grav*dt;p.life-=dt;if(p.life<=0)arr.splice(i,1);}}\nfunction drawParts(c,arr){for(const p of arr){c.globalAlpha=Math.max(0,Math.min(1,p.life*1.6));c.fillStyle=p.c;c.beginPath();c.arc(p.x,p.y,p.r,0,7);c.fill();}c.globalAlpha=1;}\nfunction addPop(arr,text,x,y,color,size){const half=Math.min(170,String(text).length*(size||26)*.3+10);x=Math.max(half,Math.min(W-half,x));arr.push({text,x,y,color:color||'#fff',size:size||26,life:1.2});}\nfunction stepPops(arr,dt){for(let i=arr.length-1;i>=0;i--){arr[i].y-=38*dt;arr[i].life-=dt;if(arr[i].life<=0)arr.splice(i,1);}}\nfunction drawPops(c,arr){for(const p of arr){c.globalAlpha=Math.max(0,Math.min(1,p.life*2));c.font=`700 ${p.size}px Fredoka, sans-serif`;c.textAlign='center';c.textBaseline='middle';c.lineJoin='round';c.lineWidth=6;c.strokeStyle='rgba(30,27,75,.8)';c.strokeText(p.text,p.x,p.y);c.fillStyle=p.color;c.fillText(p.text,p.x,p.y);}c.globalAlpha=1;}\nfunction drawCloud(c,x,y,s){c.fillStyle='rgba(255,255,255,.9)';c.beginPath();c.arc(x,y,18*s,0,7);c.arc(x+20*s,y-10*s,22*s,0,7);c.arc(x+42*s,y,18*s,0,7);c.arc(x+20*s,y+6*s,18*s,0,7);c.fill();}\nfunction label(c,text,x,y,size,color){c.font=`700 ${size}px Fredoka, sans-serif`;c.textAlign='center';c.textBaseline='middle';c.lineJoin='round';c.lineWidth=5;c.strokeStyle='rgba(30,27,75,.75)';c.strokeText(text,x,y);c.fillStyle=color||'#fff';c.fillText(text,x,y);}\n\n/* bonus seconds for a finished word; a game can earn at most its starting time in bonuses,\n   so one token never buys an endless game (short word lists made that possible) */\nfunction addTime(g,s){g.bonus=g.bonus||0;const add=Math.max(0,Math.min(s,g.tmax-g.bonus));g.bonus+=add;g.time=Math.min(g.tmax+30,g.time+add);}\n\n/* ===== GAME 1: Home Run Derby (baseball) ===== */\nfunction createDerby(){\n  const PLATE_Y=478,SWEET=462,MX=180,MY=318,START_Y=MY-12;\n  const g={over:false,score:0,pitch:0,total:10,hr:0,hits:0,state:'wait',timer:1.4,ball:null,swing:0,swinging:false,recover:0,swung:false,parts:[],pops:[],fly:null,fw:0,t:0,crowd:[]};\n  const cc=['#f87171','#60a5fa','#fbbf24','#34d399','#a78bfa','#f472b6','#ffffff','#fb923c'];\n  for(let i=0;i<90;i++)g.crowd.push({x:4+Math.random()*(W-8),y:44+Math.random()*54,c:cc[i%cc.length],ph:Math.random()*6});\n  g.intro='Watch the pitcher throw. <b>Tap anywhere to swing</b> when the ball reaches the glowing yellow ring!<br><br>10 pitches. Home run = 3 points, base hit = 1.';\n  g.hud=()=>`⚾ ${g.pitch}/${g.total} · 💥 ${g.hr} HR · ⭐ ${g.score}`;\n  g.endTitle='Game over, slugger!';\n  function pitch(){\n    g.pitch++;\n    const base=(1.25-Math.min(.35,g.pitch*.03))/DF(),slow=Math.random()<.2;\n    g.ball={t:0,dur:base*(slow?1.35:1)*rnd(.9,1.1),curve:rnd(-25,25),x:MX,y:START_Y,r:4};\n    g.state='pitch';g.swung=false;\n  }\n  function contact(kind,off){\n    const b=g.ball,side=off<0?-1:1;g.state='fly';\n    if(kind==='hr'){g.hr++;g.score+=3;g.fly={x:b.x,y:b.y,vx:rnd(-80,80),vy:-640,g:300,r:12,t:0,life:1.6};addPop(g.pops,'HOME RUN!',180,240,'#fde047',42);g.fw=1.8;sfx('hr');burst(g.parts,b.x,b.y,['#fff','#fde047'],18,220);}\n    else if(kind==='hit'){g.hits++;g.score+=1;g.fly={x:b.x,y:b.y,vx:side*rnd(140,230),vy:-420,g:520,r:11,t:0,life:1.2};addPop(g.pops,'Base hit!',180,300,'#86efac',34);sfx('hit');burst(g.parts,b.x,b.y,['#fff','#86efac'],12,160);}\n    else{g.fly={x:b.x,y:b.y,vx:side*330,vy:-260,g:400,r:10,t:0,life:.9};addPop(g.pops,'Foul ball!',180,320,'#e2e8f0',28);sfx('tick');}\n  }\n  g.tap=()=>{\n    if(g.swinging||g.swing>0)return;\n    g.swinging=true;g.swing=0;sfx('swoosh');\n    if(g.state!=='pitch'||g.swung)return;\n    g.swung=true;\n    const b=g.ball,vy=(PLATE_Y-START_Y)/b.dur,off=(b.y+vy*.06)-SWEET,d=Math.abs(off);\n    const T=TOL();if(d<14*T)contact('hr',off);else if(d<30*T)contact('hit',off);else if(d<44*T)contact('foul',off);\n  };\n  g.update=dt=>{\n    g.t+=dt;stepParts(g.parts,dt,250);stepPops(g.pops,dt);\n    if(g.swinging){g.swing=Math.min(1,g.swing+dt/.17);if(g.swing>=1){g.swinging=false;g.recover=.4;}}\n    else if(g.recover>0){g.recover-=dt;if(g.recover<=0)g.swing=0;}\n    if(g.fw>0){g.fw-=dt;if(Math.random()<dt*7)burst(g.parts,rnd(40,320),rnd(30,120),['#fde047','#f472b6','#60a5fa','#34d399','#fff'],26,170);}\n    if(g.state==='wait'){g.timer-=dt;if(g.timer<=0){if(g.pitch>=g.total){g.over=true;return;}pitch();}}\n    else if(g.state==='pitch'){\n      const b=g.ball;b.t+=dt;const p=b.t/b.dur;\n      b.y=START_Y+(PLATE_Y-START_Y)*p;b.x=MX+Math.sin(Math.min(p,1)*Math.PI)*b.curve;b.r=4+9*Math.min(p,1.2);\n      if(b.y>H+20){g.state='wait';g.timer=1.2;addPop(g.pops,g.swung?'Swing and a miss!':'Strike!',180,390,'#fca5a5',30);sfx('miss');}\n    }else if(g.state==='fly'){\n      const f=g.fly;f.t+=dt;f.x+=f.vx*dt;f.y+=f.vy*dt;f.vy+=f.g*dt;f.r=Math.max(2,f.r-dt*7);\n      if(f.t>=f.life){g.state='wait';g.timer=1.1;g.fly=null;}\n    }\n  };\n  function ball(c,x,y,r){\n    c.fillStyle='#fff';c.beginPath();c.arc(x,y,r,0,7);c.fill();\n    c.strokeStyle='#dc2626';c.lineWidth=Math.max(1,r*.16);\n    c.beginPath();c.arc(x-r*1.15,y,r*.85,-.75,.75);c.stroke();\n    c.beginPath();c.arc(x+r*1.15,y,r*.85,Math.PI-.75,Math.PI+.75);c.stroke();\n  }\n  function pitcher(c){\n    const x=MX,y=MY,wind=(g.state==='wait'&&g.timer<.6&&g.pitch<g.total);\n    const thrown=g.state==='pitch'&&g.ball&&g.ball.t<.25;\n    c.fillStyle='#1e3a8a';c.fillRect(x-6,y-8,5,14);c.fillRect(x+1,y-8,5,14);\n    c.fillStyle='#ef4444';c.beginPath();c.ellipse(x,y-17,9,11,0,0,7);c.fill();\n    c.fillStyle='#8b5a2b';c.beginPath();c.arc(x-11,y-18,4,0,7);c.fill();\n    c.strokeStyle='#f5c9a0';c.lineWidth=3.5;c.lineCap='round';c.beginPath();c.moveTo(x+7,y-22);\n    if(wind)c.lineTo(x+13,y-38);else if(thrown)c.lineTo(x+4,y-6);else c.lineTo(x+12,y-12);c.stroke();\n    c.fillStyle='#f5c9a0';c.beginPath();c.arc(x,y-33,7,0,7);c.fill();\n    c.fillStyle='#1e3a8a';c.beginPath();c.arc(x,y-35,7.5,Math.PI,0);c.fill();c.fillRect(x-3,y-36,12,3);\n  }\n  function batter(c){\n    const x=134,y=502;\n    c.fillStyle='#f1f5f9';c.fillRect(x-11,y-36,9,34);c.fillRect(x+3,y-36,9,34);\n    c.fillStyle='#111827';c.fillRect(x-14,y-5,13,7);c.fillRect(x+2,y-5,13,7);\n    c.fillStyle='#7c3aed';c.beginPath();c.ellipse(x,y-52,16,21,0,0,7);c.fill();\n    c.fillStyle='#fff';c.font='700 14px Fredoka, sans-serif';c.textAlign='center';c.textBaseline='middle';c.fillText('7',x-2,y-50);\n    c.fillStyle='#f5c9a0';c.beginPath();c.arc(x+3,y-81,11,0,7);c.fill();\n    c.fillStyle='#7c3aed';c.beginPath();c.arc(x+2,y-84,12,Math.PI,0);c.fill();c.fillRect(x+2,y-86,17,4);\n    const s=g.swing,e=s<.5?2*s*s:1-Math.pow(-2*s+2,2)/2;\n    const a=-2.3+e*2.9,hx=x+13,hy=y-58;\n    c.save();c.translate(hx,hy);c.rotate(a);\n    c.fillStyle='#b45309';c.beginPath();c.moveTo(0,-2.5);c.lineTo(70,-5.5);c.arc(70,0,5.5,-Math.PI/2,Math.PI/2);c.lineTo(0,2.5);c.closePath();c.fill();\n    c.fillStyle='#78350f';c.fillRect(-4,-3,12,6);\n    c.restore();\n    c.strokeStyle='#f5c9a0';c.lineWidth=6;c.lineCap='round';c.beginPath();c.moveTo(x+8,y-64);c.lineTo(hx,hy);c.stroke();\n  }\n  g.draw=c=>{\n    const sky=c.createLinearGradient(0,0,0,44);sky.addColorStop(0,'#0ea5e9');sky.addColorStop(1,'#7dd3fc');\n    c.fillStyle=sky;c.fillRect(0,0,W,44);\n    c.fillStyle='#334155';c.fillRect(0,36,W,70);\n    const party=g.fw>0;\n    for(const p of g.crowd){const bob=Math.abs(Math.sin(g.t*(party?14:3)+p.ph))*(party?6:1.5);c.fillStyle=p.c;c.beginPath();c.arc(p.x,p.y-bob,4.2,0,7);c.fill();}\n    c.fillStyle='#14532d';c.fillRect(0,104,W,18);c.fillStyle='#facc15';c.fillRect(0,104,W,3);\n    c.fillStyle='#fff';c.font='700 11px Fredoka, sans-serif';c.textAlign='center';c.textBaseline='middle';c.fillText('★  SPELLING ARCADE PARK  ★',180,114);\n    for(let i=0;i<10;i++){c.fillStyle=i%2?'#4ade80':'#22c55e';c.fillRect(0,122+i*42,W,42);}\n    c.fillStyle='#d4a373';c.beginPath();c.moveTo(180,232);c.lineTo(338,372);c.lineTo(180,520);c.lineTo(22,372);c.closePath();c.fill();\n    c.fillStyle='#4ade80';c.beginPath();c.moveTo(180,272);c.lineTo(292,372);c.lineTo(180,472);c.lineTo(68,372);c.closePath();c.fill();\n    c.strokeStyle='#fff';c.lineWidth=2;c.beginPath();c.moveTo(180,482);c.lineTo(0,318);c.moveTo(180,482);c.lineTo(360,318);c.stroke();\n    const base=(x,y)=>{c.fillStyle='#fff';c.beginPath();c.moveTo(x,y-7);c.lineTo(x+9,y);c.lineTo(x,y+7);c.lineTo(x-9,y);c.closePath();c.fill();};\n    base(180,262);base(304,372);base(56,372);\n    c.fillStyle='#c08552';c.beginPath();c.ellipse(MX,MY+6,30,12,0,0,7);c.fill();\n    c.fillStyle='#fff';c.fillRect(MX-8,MY+4,16,3);\n    pitcher(c);\n    c.fillStyle='#d4a373';c.beginPath();c.ellipse(180,490,70,28,0,0,7);c.fill();\n    c.fillStyle='#fff';c.beginPath();c.moveTo(166,478);c.lineTo(194,478);c.lineTo(194,486);c.lineTo(180,494);c.lineTo(166,486);c.closePath();c.fill();\n    const pulse=.5+.5*Math.sin(g.t*6);\n    c.strokeStyle=`rgba(253,224,71,${.4+.4*pulse})`;c.lineWidth=4;c.beginPath();c.ellipse(180,SWEET,24,10,0,0,7);c.stroke();\n    if(g.state==='pitch'){const b=g.ball;c.fillStyle='rgba(0,0,0,.18)';c.beginPath();c.ellipse(b.x,Math.min(b.y+b.r+8,515),b.r,b.r*.35,0,0,7);c.fill();}\n    batter(c);\n    if(g.state==='pitch')ball(c,g.ball.x,g.ball.y,g.ball.r);\n    if(g.fly)ball(c,g.fly.x,g.fly.y,g.fly.r);\n    drawParts(c,g.parts);drawPops(c,g.pops);\n    if(g.started&&g.state==='wait'&&g.pitch<g.total&&g.timer<.9&&g.timer>0)label(c,'Get ready…',180,200,24,'#fff');\n  };\n  return g;\n}\n\n/* ===== GAME 2: Unicorn Rainbow Dash ===== */\nfunction createUnicorn(){\n  const GY=452;\n  const g={over:false,score:0,t:0,speed:180,u:{x:84,y:GY,vy:0,j:0},hearts:3,inv:0,magic:0,obs:[],items:[],oT:1.6,iT:.6,parts:[],pops:[],trail:[],stars:0,shake:0,h1:0,h2:0,\n    clouds:Array.from({length:5},(_,i)=>({x:i*90+Math.random()*40,y:40+Math.random()*120,s:.6+Math.random()*.6}))};\n  g.intro='<b>Tap to jump</b> (tap twice for a double jump!). Hop over cactus and rocks, stay under the storm clouds, and grab ⭐ stars. Catch a 🌈 for rainbow magic!';\n  g.hud=()=>`${'❤️'.repeat(Math.max(0,g.hearts))}${'🤍'.repeat(Math.max(0,3-g.hearts))} · ⭐ ${g.stars} · ${Math.floor(g.score)}`;\n  g.endTitle='What a magical run!';\n  g.tap=()=>{const u=g.u;if(u.j<2){u.vy=u.j?-470:-540;u.j++;sfx('jump');burst(g.parts,u.x,u.y,['#f9a8d4','#c4b5fd','#fde68a'],10,120);}};\n  g.update=dt=>{\n    g.t+=dt;g.speed=Math.min(400,180+g.t*5)*DF();const mv=g.speed*dt;g.score+=mv/12;\n    const u=g.u;u.vy+=1500*dt;u.y+=u.vy*dt;if(u.y>=GY){u.y=GY;u.vy=0;u.j=0;}\n    g.inv=Math.max(0,g.inv-dt);g.magic=Math.max(0,g.magic-dt);g.shake=Math.max(0,g.shake-dt);\n    for(const cl of g.clouds){cl.x-=mv*.15*cl.s;if(cl.x<-90){cl.x=W+60;cl.y=30+Math.random()*130;}}\n    g.h1+=mv*.25;g.h2+=mv*.5;\n    for(const p of g.trail)p.x-=mv;\n    g.trail.push({x:u.x-24,y:u.y-30});\n    while(g.trail.length>45||(g.trail.length&&g.trail[0].x<-10))g.trail.shift();\n    g.oT-=dt;\n    if(g.oT<=0){\n      if(Math.random()<.62)g.obs.push({x:W+30,y:GY-16,k:Math.random()<.5?'🌵':'🪨',r:16});\n      else g.obs.push({x:W+30,y:GY-122-Math.random()*36,k:'⛈️',r:20});\n      g.oT=Math.max(.7,1.6-g.t*.012)+Math.random()*.9;\n    }\n    g.iT-=dt;\n    if(g.iT<=0){\n      if(Math.random()<.09&&g.magic<=0)g.items.push({x:W+30,y:GY-150,k:'🌈',r:22,ph:0});\n      else g.items.push({x:W+30,y:GY-30-Math.random()*170,k:'⭐',r:16,ph:Math.random()*6});\n      g.iT=.5+Math.random()*.8;\n    }\n    for(const o of g.obs)o.x-=mv;\n    for(const it of g.items)it.x-=mv;\n    g.obs=g.obs.filter(o=>o.x>-40);\n    g.items=g.items.filter(i=>i.x>-40&&!i.got);\n    const hx=u.x+4,hy=u.y-28;\n    for(const o of g.obs){\n      if(o.hit)continue;\n      const dx=o.x-hx,dy=o.y-hy;\n      if(dx*dx+dy*dy<(o.r+19)*(o.r+19)){\n        if(g.magic>0){o.hit=true;g.score+=5;burst(g.parts,o.x,o.y,['#f0abfc','#fde047','#a5f3fc'],14,160);addPop(g.pops,'+5 ✨',o.x,o.y-30,'#f0abfc',22);sfx('star');}\n        else if(g.inv<=0){o.hit=true;g.hearts--;g.inv=1.3;g.shake=.3;sfx('bonk');addPop(g.pops,'Oops!',hx,hy-44,'#fca5a5',26);if(g.hearts<=0)g.over=true;}\n      }\n    }\n    for(const it of g.items){\n      const dx=it.x-hx,dy=it.y-hy;\n      if(dx*dx+dy*dy<(it.r+24)*(it.r+24)){\n        it.got=true;\n        if(it.k==='🌈'){g.magic=5;g.score+=25;addPop(g.pops,'RAINBOW MAGIC!',180,190,'#f0abfc',32);sfx('win');}\n        else{g.stars++;g.score+=10;addPop(g.pops,'+10',it.x,it.y-10,'#fde047',22);sfx('star');}\n        burst(g.parts,it.x,it.y,['#fde047','#f9a8d4','#a5f3fc'],12,140);\n      }\n    }\n    stepParts(g.parts,dt,200);stepPops(g.pops,dt);\n  };\n  function hills(c,off,base,amp,freq,col){c.fillStyle=col;c.beginPath();c.moveTo(-10,H+10);for(let x=-10;x<=W+10;x+=10)c.lineTo(x,base-amp*(.6+.4*Math.sin((x+off)*freq)));c.lineTo(W+10,H+10);c.closePath();c.fill();}\n  g.draw=c=>{\n    c.save();\n    if(g.shake>0&&!S.set.calm)c.translate((Math.random()-.5)*8,(Math.random()-.5)*8);\n    const gr=c.createLinearGradient(0,0,0,H);gr.addColorStop(0,'#c4b5fd');gr.addColorStop(.6,'#fbcfe8');gr.addColorStop(1,'#fde68a');\n    c.fillStyle=gr;c.fillRect(-10,-10,W+20,H+20);\n    c.fillStyle='rgba(255,255,255,.7)';c.beginPath();c.arc(290,90,34,0,7);c.fill();\n    for(const cl of g.clouds)drawCloud(c,cl.x,cl.y,cl.s);\n    hills(c,g.h1,370,46,.012,'#a78bfa');hills(c,g.h2,415,30,.02,'#f0abfc');\n    c.fillStyle='#86efac';c.fillRect(-10,GY+2,W+20,H);c.fillStyle='#4ade80';c.fillRect(-10,GY+2,W+20,8);\n    for(let i=0;i<12;i++){const fx=((i*47-g.h2*2)%(W+40)+(W+40))%(W+40)-20;c.fillStyle=['#f472b6','#fde047','#fff'][i%3];c.beginPath();c.arc(fx,GY+26+(i%3)*14,3.2,0,7);c.fill();}\n    const cols=['#ef4444','#f97316','#facc15','#22c55e','#3b82f6','#8b5cf6'];\n    if(g.trail.length>1){\n      c.lineCap='round';c.lineJoin='round';c.globalAlpha=.85;\n      cols.forEach((col,k)=>{c.strokeStyle=col;c.lineWidth=4;c.beginPath();g.trail.forEach((p,i)=>{const yy=p.y-10+k*4;if(i)c.lineTo(p.x,yy);else c.moveTo(p.x,yy);});c.stroke();});\n      c.globalAlpha=1;\n    }\n    for(const it of g.items)emo(c,it.k,it.x,it.y+Math.sin(g.t*4+it.ph)*5,it.k==='🌈'?40:30);\n    for(const o of g.obs){c.globalAlpha=o.hit?.35:1;emo(c,o.k,o.x,o.y,o.k==='⛈️'?46:38);}\n    c.globalAlpha=1;\n    const u=g.u;\n    if(!(g.inv>0&&Math.floor(g.inv*12)%2)){\n      if(g.magic>0){c.fillStyle=`hsla(${(g.t*300)%360},90%,85%,.55)`;c.beginPath();c.arc(u.x,u.y-28,38+Math.sin(g.t*10)*3,0,7);c.fill();}\n      const bob=u.y>=GY?-Math.abs(Math.sin(g.t*14))*4:0;\n      emo(c,LOOKS.unicorn?'🐉':'🦄',u.x,u.y-30+bob,58,true);\n    }\n    drawParts(c,g.parts);drawPops(c,g.pops);\n    if(g.magic>0)label(c,'✨ Rainbow magic: '+Math.ceil(g.magic)+' ✨',180,40,18,'#fff');\n    c.restore();\n  };\n  return g;\n}\n\n/* ===== GAME 3: Balloon Spell Pop ===== */\nfunction wordPool(){\n  const p=allWords().map(norm).filter(w=>/^[a-z]+$/.test(w)&&w.length<=12);\n  return p.length?p:STARTERS.easy.slice();\n}\nfunction createBalloon(){\n  const pool=wordPool(),AB='abcdefghijklmnopqrstuvwxyz';\n  const COLS=['#ef4444','#f97316','#eab308','#22c55e','#06b6d4','#3b82f6','#8b5cf6','#ec4899'];\n  const BT={easy:75,normal:60,hard:50}[S.set.diff]||60;\n  const g={over:false,score:0,time:BT,tmax:BT,word:'',idx:0,bl:[],sT:0,parts:[],pops:[],done:0,t:0,wait:0,\n    clouds:Array.from({length:4},(_,i)=>({x:i*100+Math.random()*30,y:140+Math.random()*300,s:.5+Math.random()*.5}))};\n  g.intro='Spell the word at the top by <b>popping balloons in order</b>, one letter at a time. Each word you finish gives bonus points and extra time.<br><br>You have '+BT+' seconds!';\n  g.hud=()=>`🎈 ${g.done} words · ⏱ ${Math.ceil(g.time)}s · ⭐ ${g.score}`;\n  g.endTitle='Time\\'s up! Great popping!';\n  function nextWord(){let w,n=0;do{w=pick(pool);n++;}while(pool.length>1&&w===g.word&&n<10);g.word=w;g.idx=0;speak(w);}\n  const need=()=>g.word[g.idx];\n  function spawn(l){g.bl.push({x:rnd(36,W-36),y:H+40,vy:-(55+Math.random()*35+Math.min(40,g.done*4))*DF(),r:28,l,c:pick(COLS),ph:Math.random()*6,wig:0});}\n  g.begin=()=>{nextWord();for(let i=0;i<3;i++){spawn(i===0?need():pick(AB));g.bl[g.bl.length-1].y=H-40-i*120;}};\n  g.tap=(x,y)=>{\n    if(g.wait>0)return;\n    let hit=null;\n    let hd=1e9;for(let i=g.bl.length-1;i>=0;i--){const b=g.bl[i];if(b.popped)continue;const d=Math.hypot(x-b.x,y-b.y)/b.r;if(d<(b.r+10)/b.r&&d<hd){hd=d;hit=b;}} // closest balloon wins when they overlap\n    if(!hit)return;\n    if(hit.l===need()){\n      hit.popped=true;burst(g.parts,hit.x,hit.y,[hit.c,'#fff'],16,200);sfx('pop');g.idx++;g.score+=1;\n      if(g.idx>=g.word.length){g.done++;g.score+=g.word.length;addTime(g,4);addPop(g.pops,`${g.word.toUpperCase()}! +${g.word.length}`,180,200,'#fde047',34);sfx('win');g.wait=1.1;}\n    }else{hit.wig=.4;sfx('nope');addPop(g.pops,'Find '+need().toUpperCase(),hit.x,hit.y-44,'#fff',20);}\n  };\n  g.update=dt=>{\n    g.t+=dt;g.time-=dt;\n    if(g.time<=0){g.time=0;g.over=true;return;}\n    if(g.wait>0){g.wait-=dt;if(g.wait<=0)nextWord();}\n    g.sT-=dt;\n    if(g.sT<=0){const n=need();spawn(n&&g.wait<=0&&Math.random()<.4?n:pick(AB));g.sT=.55+Math.random()*.35;}\n    const n=need();\n    if(n&&g.wait<=0&&!g.bl.some(b=>b.l===n&&!b.popped&&b.y>150))spawn(n);\n    for(const b of g.bl){b.y+=b.vy*dt;b.x+=Math.sin(g.t*2+b.ph)*12*dt;b.wig=Math.max(0,b.wig-dt);}\n    g.bl=g.bl.filter(b=>b.y>-80&&!b.popped);\n    for(const cl of g.clouds){cl.x-=10*dt*cl.s;if(cl.x<-80)cl.x=W+40;}\n    stepParts(g.parts,dt,300);stepPops(g.pops,dt);\n  };\n  function balloon(c,b){\n    const x=b.x+(b.wig>0?Math.sin(b.wig*40)*5:0),y=b.y,ry=b.r*1.15;\n    c.strokeStyle='rgba(71,85,105,.6)';c.lineWidth=1.5;c.beginPath();c.moveTo(x,y+ry+4);c.quadraticCurveTo(x+8*Math.sin(g.t*3+b.ph),y+ry+26,x,y+ry+46);c.stroke();\n    c.fillStyle=b.c;c.beginPath();c.ellipse(x,y,b.r,ry,0,0,7);c.fill();\n    c.beginPath();c.moveTo(x-5,y+ry+6);c.lineTo(x+5,y+ry+6);c.lineTo(x,y+ry-2);c.closePath();c.fill();\n    c.fillStyle='rgba(255,255,255,.45)';c.beginPath();c.ellipse(x-b.r*.38,y-b.r*.45,b.r*.2,b.r*.34,-.5,0,7);c.fill();\n    c.font='700 28px Fredoka, sans-serif';c.textAlign='center';c.textBaseline='middle';c.lineWidth=4;c.strokeStyle='rgba(0,0,0,.25)';\n    c.strokeText(b.l.toUpperCase(),x,y+1);c.fillStyle='#fff';c.fillText(b.l.toUpperCase(),x,y+1);\n  }\n  g.draw=c=>{\n    const gr=c.createLinearGradient(0,0,0,H);gr.addColorStop(0,'#7dd3fc');gr.addColorStop(1,'#f0f9ff');\n    c.fillStyle=gr;c.fillRect(0,0,W,H);\n    for(const cl of g.clouds)drawCloud(c,cl.x,cl.y,cl.s);\n    for(const b of g.bl)balloon(c,b);\n    c.fillStyle='rgba(255,255,255,.95)';rr(c,10,10,W-20,84,18);c.fill();\n    c.fillStyle='#6b7280';c.font='600 13px Fredoka, sans-serif';c.textAlign='center';c.textBaseline='middle';\n    c.fillText(g.started?'SPELL THIS WORD':'GET READY',180,26);\n    const wd=g.word||'?',L=wd.length,bw=Math.min(34,(W-50)/L),x0=(W-bw*L)/2+bw/2;\n    for(let i=0;i<L;i++){\n      const x=x0+i*bw,ch=wd[i].toUpperCase();\n      c.font=`700 ${Math.floor(bw*.95)}px Fredoka, sans-serif`;\n      if(i<g.idx){c.fillStyle='#7c3aed';c.fillText(ch,x,58);}\n      else{\n        if(i===g.idx){c.fillStyle='#fde047';rr(c,x-bw/2+2,72,bw-4,6,3);c.fill();}\n        c.fillStyle='#d1d5db';c.fillText(ch,x,58);\n      }\n    }\n    const tf=Math.max(0,Math.min(1,g.time/g.tmax));\n    c.fillStyle='rgba(255,255,255,.7)';rr(c,20,100,W-40,10,5);c.fill();\n    c.fillStyle=tf>.3?'#22c55e':'#ef4444';rr(c,20,100,(W-40)*tf,10,5);c.fill();\n    drawParts(c,g.parts);drawPops(c,g.pops);\n  };\n  return g;\n}\n\n/* ===== GAME 4: Memory Match ===== */\nfunction createMemory(){\n  const EM=['🦄','⚾','🌈','🍦','🐶','🚀','🍕','🎈'].slice(0,S.set.diff==='easy'?6:8);\n  const cards=shuffle(EM.concat(EM)).map(e=>({e,up:false,m:false,f:0}));\n  const g={over:false,score:0,moves:0,pairs:0,open:[],lock:0,end:0,t:0,parts:[],pops:[],cards};\n  const GX=16,GY0=70,GAP=10,CW=(W-2*GX-3*GAP)/4,CH=100;\n  const pos=i=>({x:GX+(i%4)*(CW+GAP),y:GY0+Math.floor(i/4)*(CH+GAP)});\n  g.intro='Tap two cards to flip them. If they match, they stay up! Find all <b>'+EM.length+' pairs</b> in as few moves as you can.';\n  g.hud=()=>`🧠 Moves ${g.moves} · Pairs ${g.pairs}/${EM.length}`;\n  g.endTitle='You found them all!';\n  g.tap=(x,y)=>{\n    if(g.lock>0||g.end>0)return;\n    for(let i=0;i<cards.length;i++){\n      const p=pos(i),cd=cards[i];\n      if(x>=p.x&&x<=p.x+CW&&y>=p.y&&y<=p.y+CH){\n        if(cd.up||cd.m)return;\n        cd.up=true;sfx('flip');g.open.push(cd);\n        if(g.open.length===2){\n          g.moves++;const a=g.open[0],b=g.open[1];\n          if(a.e===b.e){\n            a.m=b.m=true;g.pairs++;g.open=[];sfx('correct');\n            burst(g.parts,p.x+CW/2,p.y+CH/2,['#fde047','#f9a8d4','#a5f3fc'],18,180);\n            if(g.pairs===EM.length){g.score=Math.max(10,140-g.moves*5);g.end=1.3;addPop(g.pops,'All matched!',180,280,'#fde047',38);}\n          }else g.lock=.9;\n        }\n        return;\n      }\n    }\n  };\n  g.update=dt=>{\n    g.t+=dt;\n    for(const cd of cards){const tg=(cd.up||cd.m)?1:0;cd.f+=(tg-cd.f)*Math.min(1,dt*12);}\n    if(g.lock>0){g.lock-=dt;if(g.lock<=0){g.open.forEach(cd=>cd.up=false);g.open=[];}}\n    if(g.end>0){g.end-=dt;if(g.end<=0)g.over=true;}\n    stepParts(g.parts,dt,250);stepPops(g.pops,dt);\n  };\n  g.draw=c=>{\n    const gr=c.createLinearGradient(0,0,0,H);gr.addColorStop(0,'#4c1d95');gr.addColorStop(1,'#a855f7');\n    c.fillStyle=gr;c.fillRect(0,0,W,H);\n    label(c,'Find the pairs!',180,36,24,'#fde047');\n    cards.forEach((cd,i)=>{\n      const p=pos(i),s=Math.abs(1-2*cd.f),w=CW*Math.max(.04,s),cx=p.x+CW/2,face=cd.f>.5;\n      c.fillStyle=face?(cd.m?'#dcfce7':'#ffffff'):'#f472b6';\n      rr(c,cx-w/2,p.y,w,CH,12);c.fill();\n      if(cd.m&&face){c.strokeStyle='#22c55e';c.lineWidth=3;rr(c,cx-w/2,p.y,w,CH,12);c.stroke();}\n      if(s>.15){\n        c.save();c.translate(cx,p.y+CH/2);c.scale(s,1);\n        if(face)emo(c,cd.e,0,0,44);\n        else{c.fillStyle='rgba(255,255,255,.35)';c.beginPath();c.arc(0,0,22,0,7);c.fill();emo(c,'⭐',0,0,26);}\n        c.restore();\n      }\n    });\n    drawParts(c,g.parts);drawPops(c,g.pops);\n  };\n  return g;\n}\n\n/* ===== GAME 5: Ice Cream Tower ===== */\nfunction createIceCream(){\n  const FL=['#f9a8d4','#92400e','#86efac','#fef3c7','#93c5fd','#fdba74','#c4b5fd'];\n  const R=27,SP=30,CR=432,CX=180,SLIDE_Y=112;\n  const g={over:false,score:0,stack:[],fall:null,misses:0,cam:0,t:0,ph:0,parts:[],pops:[],col:pick(FL),wait:0};\n  g.intro='A scoop slides across the top. <b>Tap to drop it</b> onto your cone and build the tallest ice cream tower! Land it right in the middle for a <b>Perfect</b> bonus.<br><br>Drop 3 on the floor and the game ends.';\n  g.hud=()=>`🍦 ${g.stack.length} scoops · ${'❤️'.repeat(3-g.misses)}${'🤍'.repeat(g.misses)} · ⭐ ${g.score}`;\n  g.endTitle='What a yummy tower!';\n  const nextY=n=>CR-12-n*SP;\n  const topX=()=>g.stack.length?g.stack[g.stack.length-1].x:CX;\n  const slideX=()=>CX+Math.sin(g.ph)*128;\n  g.tap=()=>{\n    if(g.fall||g.wait>0)return;\n    g.fall={x:slideX(),y:SLIDE_Y-g.cam,vy:0,c:g.col,checked:false,miss:false};\n    g.col=pick(FL.filter(f=>f!==g.col));sfx('swoosh');\n  };\n  g.update=dt=>{\n    g.t+=dt;g.wait=Math.max(0,g.wait-dt);\n    g.ph+=dt*Math.min(4.2,1.5+g.stack.length*.09)*DF();\n    const target=Math.max(0,300-nextY(g.stack.length));\n    g.cam+=(target-g.cam)*Math.min(1,dt*4);\n    const f=g.fall;\n    if(f){\n      f.vy+=1700*dt;f.y+=f.vy*dt;\n      const ly=nextY(g.stack.length);\n      if(!f.checked&&f.y>=ly){\n        f.checked=true;const dx=f.x-topX(),ad=Math.abs(dx);\n        if(ad<R*1.15*TOL()){\n          const perfect=ad<7*TOL();\n          g.stack.push({x:perfect?topX():f.x,c:f.c,seed:Math.random()*1000});\n          g.score+=perfect?3:1;\n          const sy=ly+g.cam;\n          if(perfect){addPop(g.pops,'Perfect! +3',180,sy-50,'#fde047',30);sfx('correct');burst(g.parts,topX(),sy,['#fde047','#f9a8d4','#fff'],18,180);}\n          else{sfx('pop');burst(g.parts,f.x,sy,[f.c,'#fff'],8,100);}\n          if(g.stack.length%10===0){addPop(g.pops,g.stack.length+' scoops! 🎉',180,200,'#a5f3fc',32);sfx('win');}\n          g.fall=null;\n        }else f.miss=true;\n      }\n      if(g.fall&&f.y+g.cam>H+40){\n        g.fall=null;g.misses++;sfx('bonk');addPop(g.pops,'Splat!',f.x,H-60,'#fca5a5',30);g.wait=.4;\n        if(g.misses>=3)g.over=true;\n      }\n    }\n    stepParts(g.parts,dt,300);stepPops(g.pops,dt);\n  };\n  function scoop(c,x,y,col,seed){\n    c.fillStyle=col;c.beginPath();c.arc(x,y,R,0,7);c.fill();\n    for(let i=-2;i<=2;i++){c.beginPath();c.arc(x+i*11,y+R*.72,7,0,7);c.fill();}\n    c.fillStyle='rgba(255,255,255,.45)';c.beginPath();c.ellipse(x-9,y-11,8,5,-.6,0,7);c.fill();\n    const sc=['#ef4444','#3b82f6','#22c55e','#facc15','#fff','#a855f7'];\n    for(let i=0;i<6;i++){const a=seed+i*2.3,rr2=(Math.sin(seed*3+i)*.5+.5)*R*.6;c.save();c.translate(x+Math.cos(a)*rr2,y-4+Math.sin(a)*rr2*.6);c.rotate(a);c.fillStyle=sc[i];c.fillRect(-3.5,-1.2,7,2.4);c.restore();}\n  }\n  g.draw=c=>{\n    const gr=c.createLinearGradient(0,0,0,H);gr.addColorStop(0,'#fdf2f8');gr.addColorStop(1,'#fef3c7');\n    c.fillStyle=gr;c.fillRect(0,0,W,H);\n    for(let i=0;i<8;i++){c.fillStyle=i%2?'#fff':'#f472b6';c.beginPath();c.moveTo(i*45,0);c.lineTo(i*45+45,0);c.lineTo(i*45+45,26);c.arc(i*45+22.5,26,22.5,0,Math.PI);c.closePath();c.fill();}\n    c.save();c.translate(0,g.cam);\n    c.fillStyle='#e9d5ff';c.fillRect(0,CR+86,W,400);c.fillStyle='#c084fc';c.fillRect(0,CR+86,W,6);\n    c.fillStyle='#d97706';c.beginPath();c.moveTo(CX-30,CR);c.lineTo(CX+30,CR);c.lineTo(CX,CR+84);c.closePath();c.fill();\n    c.save();c.beginPath();c.moveTo(CX-30,CR);c.lineTo(CX+30,CR);c.lineTo(CX,CR+84);c.closePath();c.clip();\n    c.strokeStyle='#92400e';c.lineWidth=2;for(let i=-6;i<6;i++){c.beginPath();c.moveTo(CX+i*12,CR);c.lineTo(CX+i*12+60,CR+90);c.stroke();c.beginPath();c.moveTo(CX+i*12,CR);c.lineTo(CX+i*12-60,CR+90);c.stroke();}\n    c.restore();\n    c.fillStyle='#b45309';rr(c,CX-33,CR-6,66,12,6);c.fill();\n    g.stack.forEach((s,i)=>scoop(c,s.x,nextY(i),s.c,s.seed));\n    if(g.stack.length){const top=g.stack[g.stack.length-1];emo(c,'🍒',top.x+4,nextY(g.stack.length-1)-R-6,26);}\n    if(g.fall)scoop(c,g.fall.x,g.fall.y,g.fall.c,7);\n    c.restore();\n    if(!g.fall&&g.started){\n      const x=slideX();\n      c.strokeStyle='rgba(124,58,237,.25)';c.setLineDash([6,8]);c.lineWidth=2;c.beginPath();c.moveTo(x,SLIDE_Y+R);c.lineTo(x,H);c.stroke();c.setLineDash([]);\n      scoop(c,x,SLIDE_Y,g.col,3);\n    }\n    drawParts(c,g.parts);drawPops(c,g.pops);\n  };\n  return g;\n}\n\n/* ===== GAME 6: Space Star Catcher ===== */\nfunction createSpace(){\n  const RY=470;\n  const g={over:false,score:0,t:0,x:180,tx:180,hearts:3,inv:0,objs:[],sT:.6,parts:[],pops:[],shake:0,\n    sky:Array.from({length:70},()=>({x:Math.random()*W,y:Math.random()*H,s:Math.random()*2+.4}))};\n  g.intro='<b>Slide your finger</b> left and right to fly the rocket. Catch ⭐ stars, 🌟 big stars and 👽 friendly aliens. Dodge the ☄️ comets!';\n  g.hud=()=>`${'❤️'.repeat(Math.max(0,g.hearts))}${'🤍'.repeat(Math.max(0,3-g.hearts))} · ⭐ ${g.score}`;\n  g.endTitle='Mission complete, astronaut!';\n  g.move=x=>{g.tx=Math.max(26,Math.min(W-26,x));};\n  g.tap=x=>g.move(x);\n  g.update=dt=>{\n    g.t+=dt;g.inv=Math.max(0,g.inv-dt);g.shake=Math.max(0,g.shake-dt);\n    g.x+=(g.tx-g.x)*Math.min(1,dt*12);\n    const boost=1+g.t/45;\n    for(const s of g.sky){s.y+=s.s*50*dt*boost;if(s.y>H){s.y=-2;s.x=Math.random()*W;}}\n    g.sT-=dt;\n    if(g.sT<=0){\n      const r=Math.random(),hz=Math.min(.5,(.22+g.t*.004)*DF());\n      const k=r<hz?'☄️':r<hz+.06?'👽':r<hz+.11?'🌟':'⭐';\n      g.objs.push({x:rnd(24,W-24),y:-30,vy:(rnd(150,210)+g.t*3)*DF(),k,ph:Math.random()*6});\n      g.sT=Math.max(.26,.7-g.t*.006)*rnd(.7,1.2);\n    }\n    for(const o of g.objs){\n      o.y+=o.vy*dt;\n      const dx=o.x-g.x,dy=o.y-RY;\n      if(!o.got&&dx*dx+dy*dy<40*40){\n        if(o.k==='☄️'){if(g.inv<=0){o.got=true;g.hearts--;g.inv=1.2;g.shake=.3;sfx('bonk');addPop(g.pops,'Ouch!',g.x,RY-50,'#fca5a5',26);burst(g.parts,o.x,o.y,['#f97316','#fde047'],16,180);if(g.hearts<=0)g.over=true;}}\n        else{o.got=true;const pts=o.k==='🌟'?5:o.k==='👽'?3:1;g.score+=pts;addPop(g.pops,'+'+pts,o.x,o.y-20,o.k==='👽'?'#86efac':'#fde047',pts>1?28:22);sfx(pts>1?'win':'star');burst(g.parts,o.x,o.y,['#fde047','#fff','#a5f3fc'],10,140);}\n      }\n    }\n    g.objs=g.objs.filter(o=>o.y<H+40&&!o.got);\n    stepParts(g.parts,dt,0);stepPops(g.pops,dt);\n  };\n  g.draw=c=>{\n    c.save();if(g.shake>0&&!S.set.calm)c.translate((Math.random()-.5)*8,(Math.random()-.5)*8);\n    const gr=c.createLinearGradient(0,0,0,H);gr.addColorStop(0,'#0f172a');gr.addColorStop(1,'#4c1d95');\n    c.fillStyle=gr;c.fillRect(-10,-10,W+20,H+20);\n    for(const s of g.sky){c.globalAlpha=.4+s.s*.25;c.fillStyle='#fff';c.fillRect(s.x,s.y,s.s,s.s*(1+g.t/60));}\n    c.globalAlpha=1;\n    c.fillStyle='#f472b6';c.beginPath();c.arc(292,110,30,0,7);c.fill();\n    c.strokeStyle='#fde68a';c.lineWidth=5;c.beginPath();c.ellipse(292,110,50,12,-.3,0,7);c.stroke();\n    c.fillStyle='rgba(255,255,255,.25)';c.beginPath();c.arc(282,100,9,0,7);c.fill();\n    for(const o of g.objs){c.save();c.translate(o.x,o.y);if(o.k==='⭐'||o.k==='🌟')c.rotate(Math.sin(g.t*3+o.ph)*.3);emo(c,o.k,0,0,o.k==='☄️'?40:o.k==='🌟'?38:30);c.restore();}\n    if(!(g.inv>0&&Math.floor(g.inv*12)%2)){\n      const fl=10+Math.random()*10;\n      c.fillStyle='#f97316';c.beginPath();c.moveTo(g.x-9,RY+22);c.lineTo(g.x+9,RY+22);c.lineTo(g.x,RY+22+fl+8);c.closePath();c.fill();\n      c.fillStyle='#fde047';c.beginPath();c.moveTo(g.x-5,RY+22);c.lineTo(g.x+5,RY+22);c.lineTo(g.x,RY+22+fl);c.closePath();c.fill();\n      c.save();c.translate(g.x,RY);if(!LOOKS.space)c.rotate(-Math.PI/4);emo(c,LOOKS.space?'🛸':'🚀',0,0,50);c.restore();\n    }\n    drawParts(c,g.parts);drawPops(c,g.pops);c.restore();\n  };\n  return g;\n}\n\n/* ===== GAME 7: Garden Bonk (whack-a-gopher) ===== */\nfunction createBonk(){\n  const g={over:false,score:0,time:45,t:0,parts:[],pops:[],ham:null,\n    holes:Array.from({length:9},(_,i)=>({x:70+(i%3)*110,y:230+Math.floor(i/3)*115,k:null,up:0,state:'down',timer:rnd(.3,1.6),stay:0,hit:false}))};\n  g.intro='Bonk the 🐹 gophers when they pop up! Golden 🌟 stars are worth extra. <b>Don\\'t bonk the 🐰 bunnies!</b><br><br>You have 45 seconds.';\n  g.hud=()=>`⏱ ${Math.ceil(g.time)}s · ⭐ ${g.score}`;\n  g.endTitle='Garden saved!';\n  g.tap=(x,y)=>{\n    g.ham={x,y,t:.2};\n    for(const h of g.holes){\n      if(h.k&&!h.hit&&h.up>.35&&Math.abs(x-h.x)<48&&y>h.y-95&&y<h.y+25){\n        h.hit=true;h.state='up';h.timer=.35;\n        if(h.k==='🐰'){g.score=Math.max(0,g.score-2);addPop(g.pops,'Not the bunny! -2',h.x,h.y-80,'#fca5a5',20);sfx('nope');}\n        else if(h.k==='🌟'){g.score+=3;addPop(g.pops,'+3',h.x,h.y-80,'#fde047',30);sfx('win');burst(g.parts,h.x,h.y-40,['#fde047','#fff'],16,180);}\n        else{g.score+=1;addPop(g.pops,'Bonk! +1',h.x,h.y-80,'#fff',24);sfx('hit');burst(g.parts,h.x,h.y-40,['#fde047','#fff','#a3e635'],10,140);}\n        return;\n      }\n    }\n    sfx('swoosh');\n  };\n  g.update=dt=>{\n    g.t+=dt;g.time-=dt;if(g.time<=0){g.time=0;g.over=true;return;}\n    if(g.ham){g.ham.t-=dt;if(g.ham.t<=0)g.ham=null;}\n    for(const h of g.holes){\n      if(h.state==='down'){h.timer-=dt;if(h.timer<=0){const r=Math.random();h.k=r<.18?'🐰':r<.26?'🌟':'🐹';h.state='rising';h.hit=false;h.stay=Math.max(.5,1.3-g.t*.015)/DF();}}\n      else if(h.state==='rising'){h.up=Math.min(1,h.up+dt*6);if(h.up>=1){h.state='up';h.timer=h.stay;}}\n      else if(h.state==='up'){h.timer-=dt;if(h.timer<=0)h.state='falling';}\n      else if(h.state==='falling'){h.up=Math.max(0,h.up-dt*6);if(h.up<=0){h.state='down';h.k=null;h.timer=rnd(.4,1.6)*Math.max(.5,1-g.t/90);}}\n    }\n    stepParts(g.parts,dt,300);stepPops(g.pops,dt);\n  };\n  g.draw=c=>{\n    const gr=c.createLinearGradient(0,0,0,H);gr.addColorStop(0,'#bbf7d0');gr.addColorStop(1,'#4ade80');\n    c.fillStyle=gr;c.fillRect(0,0,W,H);\n    c.fillStyle='#fef3c7';for(let i=0;i<12;i++){c.fillRect(8+i*30,96,14,60);c.beginPath();c.moveTo(8+i*30,96);c.lineTo(15+i*30,86);c.lineTo(22+i*30,96);c.fill();}\n    c.fillRect(0,110,W,8);c.fillRect(0,138,W,8);\n    emo(c,'🌻',30,170,30);emo(c,'🌷',330,172,28);emo(c,'🥕',180,170,26);\n    const tf=Math.max(0,Math.min(1,g.time/45));\n    c.fillStyle='rgba(255,255,255,.7)';rr(c,20,20,W-40,12,6);c.fill();\n    c.fillStyle=tf>.3?'#16a34a':'#ef4444';rr(c,20,20,(W-40)*tf,12,6);c.fill();\n    label(c,'Bonk the gophers!',180,58,24,'#fff');\n    for(const h of g.holes){\n      c.fillStyle='#3f2a14';c.beginPath();c.ellipse(h.x,h.y,42,15,0,0,7);c.fill();\n      if(h.k&&h.up>0){\n        c.save();c.beginPath();c.rect(h.x-60,h.y-140,120,140);c.clip();\n        const yy=h.y+34-h.up*68;\n        emo(c,h.k,h.x,yy,54);\n        if(h.hit&&h.k!=='🐰')emo(c,'💫',h.x,yy-36,26);\n        c.restore();\n      }\n      c.fillStyle='#92400e';c.beginPath();c.ellipse(h.x,h.y+2,46,17,0,0,Math.PI);c.fill();\n      c.fillStyle='#a16207';c.beginPath();c.ellipse(h.x,h.y+1,46,6,0,0,Math.PI);c.fill();\n    }\n    if(g.ham){c.save();c.translate(g.ham.x+14,g.ham.y-14);c.rotate(-.9+(.2-g.ham.t)*6);emo(c,'🔨',0,0,44);c.restore();}\n    drawParts(c,g.parts);drawPops(c,g.pops);\n  };\n  return g;\n}\n\n/* ===== GAME 8: Race Car Rally (racing) ===== */\nfunction createRace(){\n  const LANES=[105,180,255],CARY=440,FIN=9000,SC=.6;\n  const g={over:false,score:0,t:0,lane:1,x:180,dist:0,speed:0,boost:0,slow:0,spin:0,coins:0,objs:[],sT:.9,parts:[],pops:[],shake:0,\n    rivals:[{lane:0,dist:60,v:262,c:'#3b82f6',n:2},{lane:2,dist:-30,v:270,c:'#22c55e',n:5},{lane:1,dist:120,v:255,c:'#f59e0b',n:8}].map(r=>Object.assign(r,{v:r.v*DF(),x:LANES[r.lane],lt:rnd(1.5,3)}))};\n  const MAX=310*DF();\n  g.intro='Race to the finish line! <b>Tap the left or right side</b> of the screen to change lanes. Grab 🪙 coins, hit ⚡ boosts, and dodge 🚧 cones and oil slicks. Beat the other cars!';\n  const place=()=>1+g.rivals.filter(r=>r.dist>g.dist).length;\n  g.hud=()=>`🏁 ${Math.min(100,Math.floor(g.dist/FIN*100))}% · Place ${g.place||place()} of 4 · ⭐ ${g.score}`;\n  g.tap=x=>{const nl=Math.max(0,Math.min(2,g.lane+(x<180?-1:1)));if(nl!==g.lane){g.lane=nl;sfx('swoosh');}};\n  g.update=dt=>{\n    g.t+=dt;g.boost=Math.max(0,g.boost-dt);g.slow=Math.max(0,g.slow-dt);g.spin=Math.max(0,g.spin-dt);g.shake=Math.max(0,g.shake-dt);\n    const target=MAX*(g.boost>0?1.45:1)*(g.slow>0?.45:1)*(g.dist>=FIN?0:1);\n    g.speed+=(target-g.speed)*Math.min(1,dt*(g.speed<target?1.6:3));\n    g.x+=(LANES[g.lane]-g.x)*Math.min(1,dt*12);\n    g.dist+=g.speed*dt;\n    for(const r of g.rivals){\n      r.dist+=r.v*dt*(.94+.12*Math.sin(g.t*.7+r.n));\n      r.lt-=dt;if(r.lt<=0){r.lane=Math.max(0,Math.min(2,r.lane+(Math.random()<.5?-1:1)));r.lt=rnd(1.5,3.5);}\n      r.x+=(LANES[r.lane]-r.x)*Math.min(1,dt*5);\n    }\n    g.sT-=dt;\n    if(g.sT<=0&&g.dist<FIN-900){\n      const r=Math.random(),k=r<.42?'cone':r<.56?'oil':r<.9?'coin':'boost';\n      g.objs.push({k,lane:Math.floor(Math.random()*3),d:g.dist+760});\n      if(k==='coin'&&Math.random()<.6)for(let i=1;i<3;i++)g.objs.push({k:'coin',lane:g.objs[g.objs.length-1].lane,d:g.dist+760+i*70});\n      g.sT=Math.max(.35,.75-g.t*.006)/DF()*rnd(.7,1.3);\n    }\n    for(const o of g.objs){\n      if(o.hit)continue;\n      if(Math.abs(o.d-g.dist)<38&&Math.abs(LANES[o.lane]-g.x)<36){\n        o.hit=true;const sy=CARY;\n        if(o.k==='cone'){g.slow=1.1;g.shake=.3;sfx('bonk');addPop(g.pops,'Bump!',g.x,sy-60,'#fca5a5',26);burst(g.parts,g.x,sy-30,['#f97316','#fff'],12,160);}\n        else if(o.k==='oil'){g.slow=.8;g.spin=.8;sfx('nope');addPop(g.pops,'Slippery!',g.x,sy-60,'#e5e7eb',24);}\n        else if(o.k==='coin'){g.coins++;g.score+=2;sfx('coin');addPop(g.pops,'+2',g.x,sy-60,'#fde047',22);}\n        else{g.boost=1.6;g.score+=3;sfx('win');addPop(g.pops,'BOOST! ⚡',g.x,sy-70,'#a5f3fc',30);}\n      }\n    }\n    g.objs=g.objs.filter(o=>!o.hit&&o.d>g.dist-200);\n    if(g.dist>=FIN&&!g.done){\n      g.done=true;const pl=place();g.place=pl;\n      g.score+=[0,50,30,20,10][pl];\n      g.endTitle=['','🥇 You won the race!','🥈 Second place!','🥉 Third place!','You finished the race!'][pl];\n      addPop(g.pops,['','1st PLACE!','2nd place!','3rd place!','Finished!'][pl],180,220,'#fde047',40);sfx('hr');\n      burst(g.parts,180,200,['#fde047','#f472b6','#60a5fa','#34d399','#fff'],40,240);\n      g.endT=1.4;\n    }\n    if(g.endT!=null){g.endT-=dt;if(g.endT<=0)g.over=true;}\n    stepParts(g.parts,dt,200);stepPops(g.pops,dt);\n  };\n  function car(c,x,y,col,num,rot){\n    c.save();c.translate(x,y);if(rot)c.rotate(rot);\n    c.fillStyle='rgba(0,0,0,.2)';rr(c,-17,-26,38,60,10);c.fill();\n    c.fillStyle='#111827';c.fillRect(-21,-22,6,14);c.fillRect(15,-22,6,14);c.fillRect(-21,12,6,14);c.fillRect(15,12,6,14);\n    c.fillStyle=col;rr(c,-17,-30,34,60,10);c.fill();\n    c.fillStyle='rgba(255,255,255,.85)';rr(c,-12,-20,24,12,4);c.fill();\n    c.fillStyle='rgba(15,23,42,.55)';rr(c,-12,8,24,9,3);c.fill();\n    c.fillStyle='#fff';c.beginPath();c.arc(0,-1,7,0,7);c.fill();\n    c.fillStyle='#111827';c.font='700 10px Fredoka, sans-serif';c.textAlign='center';c.textBaseline='middle';c.fillText(num,0,0);\n    c.restore();\n  }\n  g.draw=c=>{\n    c.save();if(g.shake>0&&!S.set.calm)c.translate((Math.random()-.5)*7,(Math.random()-.5)*7);\n    c.fillStyle='#4ade80';c.fillRect(-10,-10,W+20,H+20);\n    const off=(g.dist*SC)%40;\n    for(let y=-40+off;y<H+40;y+=40){c.fillStyle=((Math.floor((y-off)/40)+Math.floor(g.dist*SC/40))%2)?'#22c55e':'#4ade80';c.fillRect(0,y,60,40);c.fillRect(300,y,60,40);}\n    for(let i=0;i<6;i++){const ty=((i*110+g.dist*SC)%(H+80))-40;emo(c,i%2?'🌳':'🌲',28,ty,30);emo(c,i%2?'🌲':'🌳',332,(ty+55)%(H+80)-20,30);}\n    c.fillStyle='#4b5563';c.fillRect(60,0,240,H);\n    const cOff=(g.dist*SC)%30;\n    for(let y=-30+cOff;y<H+30;y+=30){const red=(Math.floor((y-cOff)/30)+Math.floor(g.dist*SC/30))%2;c.fillStyle=red?'#ef4444':'#fff';c.fillRect(56,y,8,30);c.fillRect(296,y,8,30);}\n    c.fillStyle='rgba(255,255,255,.75)';\n    const dOff=(g.dist*SC)%60;\n    for(let y=-60+dOff;y<H+60;y+=60){c.fillRect(140,y,4,30);c.fillRect(216,y,4,30);}\n    const fy=CARY-(FIN-g.dist)*SC;\n    if(fy>-30&&fy<H+30){for(let i=0;i<12;i++)for(let j=0;j<2;j++){c.fillStyle=(i+j)%2?'#111':'#fff';c.fillRect(60+i*20,fy+j*10,20,10);}label(c,'FINISH',180,fy-18,20,'#fde047');}\n    for(const o of g.objs){\n      const y=CARY-(o.d-g.dist)*SC,x=LANES[o.lane];if(y<-40||y>H+40)continue;\n      if(o.k==='oil'){c.fillStyle='#111827';c.beginPath();c.ellipse(x,y,26,12,0,0,7);c.fill();c.fillStyle='rgba(168,85,247,.5)';c.beginPath();c.ellipse(x-6,y-3,10,4,0,0,7);c.fill();}\n      else emo(c,o.k==='cone'?'🚧':o.k==='coin'?'🪙':'⚡',x,y,o.k==='coin'?26:32);\n    }\n    for(const r of g.rivals){const y=CARY-(r.dist-g.dist)*SC;if(y>-50&&y<H+50)car(c,r.x,y,r.c,r.n,0);}\n    if(g.boost>0){for(let i=0;i<3;i++){c.fillStyle=['#fde047','#f97316','#ef4444'][i];c.beginPath();c.moveTo(g.x-8+i*8,CARY+30);c.lineTo(g.x-4+i*8,CARY+44+Math.random()*16);c.lineTo(g.x+i*8,CARY+30);c.fill();}}\n    car(c,g.x,CARY,'#dc2626',7,g.spin>0?Math.sin(g.spin*20)*.5:(LANES[g.lane]-g.x)*-.01);\n    // progress bar\n    c.fillStyle='rgba(255,255,255,.85)';rr(c,14,12,W-28,22,11);c.fill();\n    const bx=t=>26+(W-52)*Math.max(0,Math.min(1,t/FIN));\n    for(const r of g.rivals){c.fillStyle=r.c;c.beginPath();c.arc(bx(r.dist),23,6,0,7);c.fill();}\n    c.fillStyle='#dc2626';c.beginPath();c.arc(bx(g.dist),23,8,0,7);c.fill();\n    emo(c,'🏁',W-26,23,16);\n    drawParts(c,g.parts);drawPops(c,g.pops);\n    c.restore();\n  };\n  return g;\n}\n\n/* ===== GAME 9: Penalty Kick Shootout (soccer) ===== */\nfunction createSoccer(){\n  const GL=62,GR=298,GT=150,GB=268,BALL0={x:180,y:470};\n  const g={over:false,score:0,t:0,kick:0,total:10,goals:0,state:'aim',timer:0,aimT:Math.random()*6,aimX:180,kx:180,ktx:180,dive:0,ball:null,parts:[],pops:[],crowd:[]};\n  for(let i=0;i<80;i++)g.crowd.push({x:Math.random()*W,y:40+Math.random()*60,c:['#f87171','#60a5fa','#fbbf24','#34d399','#a78bfa','#fff'][i%6],ph:Math.random()*6});\n  g.intro='The 🎯 target slides across the goal. <b>Tap to shoot</b> when it\\'s away from the goalie! 10 kicks. Goal = 3 points, top corner = 1 bonus point.';\n  g.hud=()=>`⚽ Kick ${Math.min(g.kick+(g.state==='aim'?1:0),g.total)}/${g.total} · 🥅 ${plural(g.goals,'goal')} · ⭐ ${g.score}`;\n  g.endTitle='Great shooting!';\n  const reach=()=>30/TOL();\n  // The result is decided when the ball is kicked, then the dive is drawn to match it:\n  // a save ends with the ball in the goalie's glove, a goal ends with the glove clearly short.\n  g.tap=()=>{\n    if(g.state!=='aim')return;\n    g.state='shot';g.kick++;sfx('hit');\n    const dur=.5/DF(),react=.18/DF(),tx=g.aimX,ty=rnd(GT+22,GB-26);\n    const dir=Math.sign(tx-g.kx)||1,move=Math.min(Math.abs(tx-g.kx),165*DF()*(dur-react));\n    const kEnd=g.kx+dir*move,saved=Math.abs(kEnd-tx)<reach();\n    const sx=kEnd+dir*12,sy=GB-58;                      // diving shoulder\n    let gx=tx,gy=ty;                                     // glove target\n    if(!saved){const dx=tx-sx,dy=ty-sy,len=Math.hypot(dx,dy)||1,armLen=Math.min(len-26,30);gx=sx+dx/len*armLen;gy=sy+dy/len*armLen;}\n    g.ball={t:0,dur,tx,ty,dir,saved};g.react=react;g.k0=g.kx;g.kEnd=kEnd;g.glove={x:gx,y:gy};\n  };\n  g.update=dt=>{\n    g.t+=dt;stepParts(g.parts,dt,250);stepPops(g.pops,dt);\n    if(g.state==='aim'){\n      g.aimT+=dt*(1.6+g.kick*.08)*DF();\n      g.aimX=180+Math.sin(g.aimT)*112;\n      g.ktx=180+Math.sin(g.t*1.2)*55;\n      g.kx+=(g.ktx-g.kx)*Math.min(1,dt*4);g.dive=Math.max(0,g.dive-dt*3);\n    }else if(g.state==='shot'){\n      const b=g.ball;b.t+=dt;\n      if(b.t>g.react){const q=Math.min(1,(b.t-g.react)/(b.dur-g.react));g.kx=g.k0+(g.kEnd-g.k0)*q;g.dive=q;}\n      if(b.t>=b.dur){\n        const saved=b.saved;g.kx=g.kEnd;g.dive=1;\n        if(saved){addPop(g.pops,'SAVED!',180,220,'#fca5a5',38);sfx('bonk');b.bx=b.tx;b.by=b.ty;b.vx=-b.dir*rnd(60,110);b.vy=-60;}\n        else{\n          g.goals++;let pts=3;const corner=Math.abs(b.tx-180)>92;if(corner)pts++;\n          g.score+=pts;addPop(g.pops,corner?'TOP CORNER! +4':'GOAL! +3',180,220,'#fde047',corner?34:40);sfx('hr');\n          burst(g.parts,b.tx,b.ty,['#fde047','#fff','#60a5fa','#f472b6'],30,220);g.party=1.2;\n        }\n        g.state='result';g.timer=1.3;g.saved=saved;\n      }\n    }else if(g.state==='result'){\n      g.timer-=dt;g.party=Math.max(0,(g.party||0)-dt);\n      const b=g.ball;if(b&&b.saved&&g.timer<1.1){b.bx+=b.vx*dt;b.by+=b.vy*dt;b.vy+=420*dt;}\n      if(g.timer<=0){if(g.kick>=g.total){g.over=true;return;}g.state='aim';g.ball=null;g.dive=0;g.glove=null;}\n    }\n  };\n  function keeper(c){\n    const x=g.kx,y=GB-6,d=g.dive,b=g.ball,dir=b?b.dir:0;\n    c.save();c.translate(x,y);c.rotate(dir*d*.18);         // small lean only\n    c.fillStyle='#1f2937';c.fillRect(-9,-22,7,22);c.fillRect(2,-22,7,22);\n    c.fillStyle='#facc15';rr(c,-14,-58,28,38,8);c.fill();\n    c.fillStyle='#f5c9a0';c.beginPath();c.arc(0,-70,10,0,7);c.fill();\n    c.fillStyle='#111827';c.beginPath();c.arc(0,-74,10,Math.PI,0);c.fill();\n    c.restore();\n    // Arms in screen space, so the glove is drawn exactly where the save is decided.\n    const arm=(sx,sy,gx,gy)=>{c.strokeStyle='#facc15';c.lineWidth=8;c.lineCap='round';c.beginPath();c.moveTo(sx,sy);c.lineTo(gx,gy);c.stroke();\n      c.fillStyle='#22c55e';c.beginPath();c.arc(gx,gy,7,0,7);c.fill();c.strokeStyle='#14532d';c.lineWidth=1.5;c.stroke();};\n    const restL={x:x-30,y:y-64},restR={x:x+30,y:y-64};\n    if(b&&g.glove&&dir){\n      const sx=x+dir*12,sy=y-52,q=d*d*(3-2*d),rest=dir>0?restR:restL;\n      arm(x-dir*12,sy,x-dir*28,y-60);                       // other arm stays up\n      arm(sx,sy,rest.x+(g.glove.x-rest.x)*q,rest.y+(g.glove.y-rest.y)*q);\n    }else{arm(x-12,y-52,restL.x,restL.y);arm(x+12,y-52,restR.x,restR.y);}\n  }\n  g.draw=c=>{\n    c.fillStyle='#1e3a8a';c.fillRect(0,0,W,110);\n    const party=(g.party||0)>0;\n    for(const p of g.crowd){const bob=Math.abs(Math.sin(g.t*(party?14:3)+p.ph))*(party?6:1.5);c.fillStyle=p.c;c.beginPath();c.arc(p.x,p.y-bob,4.2,0,7);c.fill();}\n    c.fillStyle='#e2e8f0';c.fillRect(0,104,W,10);c.fillStyle='#ef4444';c.font='700 9px Fredoka, sans-serif';c.textAlign='center';c.textBaseline='middle';c.fillText('★ SPELLING ARCADE CUP ★',180,109);\n    for(let i=0;i<11;i++){c.fillStyle=i%2?'#4ade80':'#22c55e';c.fillRect(0,114+i*40,W,40);}\n    c.strokeStyle='rgba(255,255,255,.85)';c.lineWidth=3;c.strokeRect(30,GB,300,120);c.beginPath();c.moveTo(0,GB);c.lineTo(W,GB);c.stroke();\n    c.fillStyle='#fff';c.beginPath();c.arc(180,BALL0.y,4,0,7);c.fill();\n    c.fillStyle='rgba(255,255,255,.18)';c.fillRect(GL,GT,GR-GL,GB-GT);\n    c.strokeStyle='rgba(255,255,255,.55)';c.lineWidth=1;\n    for(let x=GL;x<=GR;x+=14){c.beginPath();c.moveTo(x,GT);c.lineTo(x,GB);c.stroke();}\n    for(let y=GT;y<=GB;y+=14){c.beginPath();c.moveTo(GL,y);c.lineTo(GR,y);c.stroke();}\n    c.fillStyle='#fff';c.fillRect(GL-6,GT-6,GR-GL+12,7);c.fillRect(GL-6,GT-6,7,GB-GT+6);c.fillRect(GR-1,GT-6,7,GB-GT+6);\n    const b0=g.ball,p0=b0?Math.min(1,b0.t/b0.dur):0;\n    const ballPos=()=>{const e=1-Math.pow(1-p0,2);return {x:BALL0.x+(b0.tx-BALL0.x)*e,y:BALL0.y+(b0.ty-BALL0.y)*e-Math.sin(p0*Math.PI)*30,s:34-16*p0};};\n    // A goal passes the keeper into the net (drawn behind him); a save ends in his glove (drawn on top).\n    if(b0&&!b0.saved&&p0>.6){const q=ballPos();emo(c,SOCCERBALL,q.x,q.y,q.s);}\n    keeper(c);\n    if(g.state==='aim'){\n      const ay=(GT+GB)/2;c.strokeStyle='#ef4444';c.lineWidth=4;c.beginPath();c.arc(g.aimX,ay,16,0,7);c.stroke();c.beginPath();c.arc(g.aimX,ay,6,0,7);c.stroke();\n      c.beginPath();c.moveTo(g.aimX-24,ay);c.lineTo(g.aimX+24,ay);c.moveTo(g.aimX,ay-24);c.lineTo(g.aimX,ay+24);c.lineWidth=2;c.stroke();\n      emo(c,SOCCERBALL,BALL0.x,BALL0.y,34);\n      c.fillStyle='#f5c9a0';\n    }\n    if(b0){\n      if(b0.saved&&g.state==='result')emo(c,SOCCERBALL,b0.bx,b0.by,18);\n      else if(b0.saved||p0<=.6){const q=ballPos();emo(c,SOCCERBALL,q.x,q.y,q.s);}\n    }\n    drawParts(c,g.parts);drawPops(c,g.pops);\n  };\n  return g;\n}\n\n/* ===== GAME 10: Hoop Shot (basketball) ===== */\nfunction createHoops(){\n  const HY=150,BALLX=120,BALLY=480,RIMX=180,ARC=150;\n  // Where the ball is at time p (0..1) of the shot: a real arc that drops into the rim at RIMX.\n  const shotPt=p=>({x:BALLX+(RIMX-BALLX)*p,y:BALLY+(HY-BALLY)*p-Math.sin(p*Math.PI)*ARC});\n  const g={over:false,score:0,t:0,time:45,hx:180,hp:Math.random()*6,ball:null,made:0,streak:0,parts:[],pops:[],shots:0};\n  g.intro='The hoop slides back and forth. Follow the dashed aiming arc: <b>tap to shoot</b> when it turns green, so the hoop is there when the ball arrives! Swish = 3 points. Make 3 in a row to catch fire 🔥 for double points. 45 seconds!';\n  g.hud=()=>`🏀 ${plural(g.made,'basket')} · ⏱ ${Math.ceil(g.time)}s · ⭐ ${g.score}${g.streak>=3?' 🔥':''}`;\n  g.endTitle='Buzzer! Great game!';\n  const hoopSpeed=()=>(1.3+Math.min(1.6,g.made*.08))*DF();\n  g.tap=()=>{if(g.ball)return;g.ball={t:0,dur:.62,phase:'up'};g.shots++;sfx('swoosh');};\n  g.update=dt=>{\n    g.t+=dt;g.time-=dt;if(g.time<=0&&!g.ball){g.time=0;g.over=true;return;}if(g.time<0)g.time=0;\n    g.hp+=dt*hoopSpeed();g.hx=180+Math.sin(g.hp)*115;\n    const b=g.ball;\n    if(b){\n      b.t+=dt;\n      if(b.phase==='up'&&b.t>=b.dur){\n        const d=Math.abs(g.hx-RIMX),T=TOL();\n        if(d<12*T){b.phase='in';b.swish=true;}\n        else if(d<28*T){b.phase='in';b.swish=false;}\n        else{b.phase='miss';b.vx=(RIMX>g.hx?1:-1)*rnd(120,200);b.vy=-120;b.x=RIMX;b.y=HY;}\n        b.t2=0;\n        if(b.phase==='in'){\n          g.made++;g.streak++;const fire=g.streak>=3;let pts=(b.swish?3:2)*(fire?2:1);g.score+=pts;\n          addPop(g.pops,(b.swish?'SWISH! ':'Basket! ')+'+'+pts,180,HY+70,b.swish?'#fde047':'#86efac',b.swish?34:30);\n          if(g.streak===3)addPop(g.pops,'ON FIRE! 🔥',180,HY+115,'#fb923c',30);\n          sfx(b.swish?'hr':'hit');burst(g.parts,g.hx,HY+20,['#fb923c','#fde047','#fff'],18,170);\n        }else{g.streak=0;addPop(g.pops,'Clank!',g.hx,HY-10,'#e5e7eb',24);sfx('bonk');}\n      }\n      if(b.phase==='in'){b.t2+=dt;if(b.t2>.45)g.ball=null;}\n      else if(b.phase==='miss'){b.t2+=dt;b.x+=b.vx*dt;b.y+=b.vy*dt;b.vy+=900*dt;if(b.y>H+40)g.ball=null;}\n    }\n    stepParts(g.parts,dt,250);stepPops(g.pops,dt);\n  };\n  g.draw=c=>{\n    const gr=c.createLinearGradient(0,0,0,300);gr.addColorStop(0,'#312e81');gr.addColorStop(1,'#4c1d95');\n    c.fillStyle=gr;c.fillRect(0,0,W,300);\n    for(let i=0;i<5;i++){c.fillStyle='rgba(255,255,255,.08)';c.beginPath();c.moveTo(40+i*70,0);c.lineTo(20+i*70,300);c.lineTo(60+i*70,300);c.fill();}\n    c.fillStyle='#111827';rr(c,110,16,140,34,8);c.fill();\n    c.fillStyle='#ef4444';c.font='700 22px Fredoka, sans-serif';c.textAlign='center';c.textBaseline='middle';\n    c.fillText(String(g.score).padStart(3,'0'),150,33);c.fillStyle='#fde047';c.fillText(':'+String(Math.ceil(g.time)).padStart(2,'0'),212,33);\n    for(let i=0;i<13;i++){c.fillStyle=i%2?'#d97706':'#f59e0b';c.fillRect(0,300+i*20,W,20);}\n    c.strokeStyle='rgba(255,255,255,.7)';c.lineWidth=3;c.beginPath();c.ellipse(180,380,120,40,0,Math.PI,0);c.stroke();c.beginPath();c.moveTo(0,300);c.lineTo(W,300);c.stroke();\n    const x=g.hx;\n    c.fillStyle='#6b7280';c.fillRect(x-3,HY-60,6,20);\n    c.fillStyle='#fff';rr(c,x-44,HY-70,88,58,4);c.fill();c.strokeStyle='#ef4444';c.lineWidth=3;c.strokeRect(x-16,HY-46,32,26);\n    c.strokeStyle='#e5e7eb';c.lineWidth=1.5;\n    for(let i=-3;i<=3;i++){c.beginPath();c.moveTo(x+i*7,HY+4);c.lineTo(x+i*4.5,HY+38);c.stroke();}\n    c.beginPath();c.moveTo(x-20,HY+16);c.lineTo(x+20,HY+16);c.moveTo(x-17,HY+28);c.lineTo(x+17,HY+28);c.stroke();\n    const b=g.ball;\n    const drawBall=(bx,by,s)=>{if(LOOKS.hoops){c.save();c.shadowColor='#fde047';c.shadowBlur=30;c.fillStyle='rgba(253,224,71,.7)';c.beginPath();c.arc(bx,by,s*.72,0,7);c.fill();c.restore();}emo(c,'🏀',bx,by,s);}; // Prize Counter look: glowing basketball\n    if(b&&b.phase==='in'){const p=Math.min(1,b.t2/.45);drawBall(x,HY+p*50,30);}\n    c.strokeStyle='#f97316';c.lineWidth=4;c.beginPath();c.ellipse(x,HY+4,24,7,0,0,7);c.stroke();\n    if(b&&b.phase==='up'){const p=Math.min(1,b.t/b.dur),q=shotPt(p);drawBall(q.x,q.y,46-16*p);}\n    if(b&&b.phase==='miss')drawBall(b.x,b.y,30);\n    if(!b){\n      // Aiming guide: the ball's path as a see-through dashed arc. It turns green when the\n      // hoop will be under the rim target by the time the ball gets there.\n      const future=180+Math.sin(g.hp+.62*hoopSpeed())*115,d=Math.abs(future-RIMX),T=TOL();\n      const col=d<12*T?'rgba(74,222,128,.9)':d<28*T?'rgba(253,224,71,.85)':'rgba(255,255,255,.55)';\n      c.save();c.setLineDash([9,9]);c.lineDashOffset=-g.t*30;c.lineWidth=4;c.lineCap='round';c.strokeStyle=col;\n      c.beginPath();for(let i=0;i<=40;i++){const q=shotPt(.06+i/40*.94);if(i)c.lineTo(q.x,q.y);else c.moveTo(q.x,q.y);}c.stroke();\n      c.setLineDash([5,6]);c.lineWidth=2.5;c.beginPath();c.ellipse(RIMX,HY+4,24,7,0,0,7);c.stroke();\n      c.restore();\n      drawBall(BALLX,BALLY,46);c.fillStyle='rgba(255,255,255,.6)';c.font='600 14px Fredoka, sans-serif';c.textAlign='center';\n      c.fillText(d<12*T?'shoot now!':'tap to shoot',BALLX,BALLY+38);\n    }\n    if(g.streak>=3){c.globalAlpha=.25+.15*Math.sin(g.t*10);c.fillStyle='#f97316';c.fillRect(0,0,W,6);c.fillRect(0,H-6,W,6);c.globalAlpha=1;}\n    drawParts(c,g.parts);drawPops(c,g.pops);\n  };\n  return g;\n}\n\n/* ===== shared helpers for spelling games ===== */\nfunction pickWord(pool,prev){let w,n=0;do{w=pick(pool);n++;}while(pool.length>1&&w===prev&&n<12);return w;}\nfunction slotsPanel(c,y,word,show,colorFor){\n  const L=word.length,bw=Math.min(36,(W-40)/L),x0=(W-bw*L)/2+bw/2;\n  c.font=`700 ${Math.floor(bw*.92)}px Fredoka, sans-serif`;c.textAlign='center';c.textBaseline='middle';\n  for(let i=0;i<L;i++){\n    const x=x0+i*bw;\n    c.fillStyle='rgba(255,255,255,.55)';rr(c,x-bw/2+2,y+18,bw-4,5,2);c.fill();\n    const ch=show(i);if(ch){c.fillStyle=colorFor?colorFor(i):'#fff';c.fillText(ch.toUpperCase(),x,y);}\n  }\n}\nfunction roundBtn(c,x,y,r,em,on){c.fillStyle=on?'rgba(255,255,255,.95)':'rgba(255,255,255,.75)';c.beginPath();c.arc(x,y,r,0,7);c.fill();emo(c,em,x,y+1,r*1.05);}\nconst hitCircle=(x,y,cx,cy,r)=>(x-cx)*(x-cx)+(y-cy)*(y-cy)<(r+6)*(r+6);\n\n/* ===== GAME 11: Letter Catcher ===== */\nfunction createCatcher(){\n  const pool=wordPool(),BY=478,AB='abcdefghijklmnopqrstuvwxyz';\n  const T={easy:75,normal:60,hard:50}[S.set.diff]||60;\n  const COLS=['#ef4444','#f97316','#eab308','#22c55e','#06b6d4','#3b82f6','#8b5cf6','#ec4899'];\n  const g={over:false,score:0,t:0,time:T,tmax:T,word:'',idx:0,bx:180,tx:180,hearts:3,inv:0,items:[],sT:0,parts:[],pops:[],done:0,wait:0};\n  g.intro=`Slide your finger to move the 🧺 basket. Catch the letters <b>in order</b> to spell the word at the top. Catching a wrong letter costs 2 seconds, so dodge those!<br><br>You have ${T} seconds!`;\n  g.hud=()=>`🧺 ${plural(g.done,'word')} · ⏱ ${Math.ceil(g.time)}s · ⭐ ${g.score}`;\n  g.endTitle='Great catching!';\n  const need=()=>g.word[g.idx];\n  function next(){g.word=pickWord(pool,g.word);g.idx=0;g.items=g.items.filter(i=>i.y>BY-120);speak(g.word);}\n  function spawn(l){g.items.push({x:rnd(30,W-30),y:118,vy:rnd(85,120)*DF(),l,c:pick(COLS),rot:rnd(-.3,.3)});}\n  g.begin=()=>next();\n  g.move=x=>{g.tx=Math.max(40,Math.min(W-40,x));};\n  g.tap=(x,y)=>{if(hitCircle(x,y,W-34,62,18)){speak(g.word);return;}g.move(x);};\n  g.update=dt=>{\n    g.t+=dt;g.time-=dt;if(g.time<=0){g.time=0;g.over=true;return;}\n    g.inv=Math.max(0,g.inv-dt);\n    g.bx+=(g.tx-g.bx)*Math.min(1,dt*14);\n    if(g.wait>0){g.wait-=dt;if(g.wait<=0)next();}\n    g.sT-=dt;\n    if(g.sT<=0){const n=need();spawn(n&&g.wait<=0&&Math.random()<.5?n:pick(AB));g.sT=(.75+Math.random()*.35)/DF();}\n    const n=need();if(n&&g.wait<=0&&!g.items.some(i=>i.l===n&&i.y<BY-60))spawn(n);\n    for(const it of g.items){\n      it.y+=it.vy*dt;\n      if(!it.done&&it.y>=BY-26&&it.y<=BY+10&&Math.abs(it.x-g.bx)<44){\n        it.done=true;\n        if(g.wait<=0&&it.l===need()){\n          g.idx++;g.score+=1;sfx('pop');burst(g.parts,it.x,it.y,[it.c,'#fff'],12,160);\n          if(g.idx>=g.word.length){g.done++;g.score+=g.word.length;addTime(g,3);addPop(g.pops,`${g.word.toUpperCase()}! +${g.word.length}`,180,220,'#fde047',34);sfx('win');g.wait=1;}\n        }else if(g.wait<=0&&g.inv<=0){\n          g.time=Math.max(0,g.time-2);g.inv=.6;sfx('nope');addPop(g.pops,'−2s · Need '+(need()||'').toUpperCase(),g.bx,BY-70,'#fca5a5',22);\n        }\n      }\n    }\n    g.items=g.items.filter(i=>!i.done&&i.y<H+30);\n    stepParts(g.parts,dt,300);stepPops(g.pops,dt);\n  };\n  g.draw=c=>{\n    const gr=c.createLinearGradient(0,0,0,H);gr.addColorStop(0,'#bae6fd');gr.addColorStop(.75,'#e0f2fe');gr.addColorStop(.75,'#86efac');gr.addColorStop(1,'#4ade80');\n    c.fillStyle=gr;c.fillRect(0,0,W,H);\n    drawCloud(c,40,150,.7);drawCloud(c,250,200,.6);\n    c.fillStyle='#6d28d9';rr(c,10,10,W-20,84,18);c.fill();\n    c.fillStyle='#ddd6fe';c.font='600 13px Fredoka, sans-serif';c.textAlign='center';c.textBaseline='middle';c.fillText(g.started?'CATCH THE LETTERS IN ORDER':'GET READY',170,26);\n    if(g.word)slotsPanel(c,58,g.word,i=>g.word[i],i=>i<g.idx?'#fff':i===g.idx?'#fde047':'rgba(255,255,255,.3)');\n    if(g.word){roundBtn(c,W-34,62,18,'🔊');}\n    const tf=Math.max(0,Math.min(1,g.time/g.tmax));\n    c.fillStyle='rgba(255,255,255,.7)';rr(c,20,100,W-40,10,5);c.fill();\n    c.fillStyle=tf>.3?'#22c55e':'#ef4444';rr(c,20,100,(W-40)*tf,10,5);c.fill();\n    for(const it of g.items){\n      c.save();c.translate(it.x,it.y);c.rotate(it.rot+Math.sin(g.t*3+it.x)*.1);\n      c.fillStyle=it.c;c.beginPath();c.arc(0,0,22,0,7);c.fill();\n      c.fillStyle='rgba(255,255,255,.4)';c.beginPath();c.arc(-7,-8,6,0,7);c.fill();\n      c.fillStyle='#fff';c.font='700 26px Fredoka, sans-serif';c.textAlign='center';c.textBaseline='middle';c.fillText(it.l.toUpperCase(),0,1);\n      c.restore();\n    }\n    if(!(g.inv>0&&Math.floor(g.inv*12)%2))emo(c,LOOKS.catcher?'🛒':'🧺',g.bx,BY,70);\n    drawParts(c,g.parts);drawPops(c,g.pops);\n  };\n  return g;\n}\n\n/* ===== GAME 12: Moon Rocket (gentle hangman) ===== */\nfunction createMoonRocket(){\n  const pool=wordPool(),FUEL={easy:8,normal:6,hard:5}[S.set.diff]||6,ROUNDS=5;\n  const ROWS=['abcdefg','hijklmn','opqrstu','vwxyz'],KS=44,KG=6,KY=330;\n  const keyPos=[];ROWS.forEach((r,ri)=>{const w=r.length*KS+(r.length-1)*KG,x0=(W-w)/2;[...r].forEach((ch,ci)=>keyPos.push({ch,x:x0+ci*(KS+KG),y:KY+ri*(KS+KG)}));});\n  const g={over:false,score:0,t:0,round:0,word:'',got:new Set(),tried:new Set(),fuel:FUEL,state:'play',timer:0,ry:0,parts:[],pops:[],launched:0,hint:'',\n    stars:Array.from({length:50},()=>({x:Math.random()*W,y:Math.random()*320,s:Math.random()*1.8+.4}))};\n  g.intro=`Guess the letters in the secret word to fuel your rocket! Tap 🔊 to hear the word${''}. Each wrong letter uses one ⛽ fuel cell. Spell it before the fuel runs out to blast off to the moon!<br><br>${ROUNDS} words.`;\n  g.hud=()=>`🌕 ${Math.max(1,g.round)}/${ROUNDS} · 🚀 ${g.launched} · ⭐ ${g.score}`;\n  g.endTitle='Mission complete!';\n  const solved=()=>[...g.word].every(ch=>g.got.has(ch));\n  function next(){g.round++;g.word=pickWord(pool,g.word);g.got=new Set();g.tried=new Set();g.fuel=FUEL;g.state='play';g.ry=0;g.hint='';speak(g.word);}\n  g.begin=()=>next();\n  g.tap=(x,y)=>{\n    if(g.state!=='play')return;\n    if(hitCircle(x,y,W-36,150,20)){speak(g.word);return;}\n    if(hitCircle(x,y,36,150,20)){const s=builtinSent(g.word);if(s){g.hint=s;speak(`${g.word}. ${s}`,null,{raw:true});}else{g.hint='';addPop(g.pops,'No sentence for this word',180,200,'#e5e7eb',18);}return;}\n    const k=keyPos.find(k=>x>=k.x&&x<=k.x+KS&&y>=k.y&&y<=k.y+KS);if(!k)return;\n    const L=k.ch;if(g.tried.has(L))return;g.tried.add(L);\n    if(g.word.includes(L)){\n      g.got.add(L);sfx('pop');burst(g.parts,k.x+KS/2,k.y+KS/2,['#86efac','#fff'],8,120);\n      if(solved()){g.state='launch';g.timer=2.4;const pts=10+g.fuel*2+g.word.length;g.score+=pts;g.launched++;addPop(g.pops,`BLAST OFF! +${pts}`,180,200,'#fde047',34);sfx('hr');}\n    }else{\n      g.fuel--;sfx('nope');\n      if(g.fuel<=0){g.state='fail';g.timer=2.6;addPop(g.pops,'Out of fuel!',180,200,'#fca5a5',30);sfx('bonk');}\n    }\n  };\n  g.update=dt=>{\n    g.t+=dt;stepParts(g.parts,dt,120);stepPops(g.pops,dt);\n    for(const s of g.stars){s.y+=(g.state==='launch'?240:6)*s.s*dt;if(s.y>320){s.y=0;s.x=Math.random()*W;}}\n    if(g.state==='launch'){g.ry-=260*dt;if(Math.random()<dt*30)burst(g.parts,180,268+g.ry,['#f97316','#fde047','#fff'],3,80);}\n    if(g.state!=='play'){g.timer-=dt;if(g.timer<=0){if(g.round>=ROUNDS){g.over=true;return;}next();}}\n  };\n  function wrap(c,text,x,y,maxW,lh){const words=text.split(' ');let line='',yy=y;for(const w of words){const t=line?line+' '+w:w;if(c.measureText(t).width>maxW&&line){c.fillText(line,x,yy);line=w;yy+=lh;}else line=t;}if(line)c.fillText(line,x,yy);}\n  g.draw=c=>{\n    const gr=c.createLinearGradient(0,0,0,H);gr.addColorStop(0,'#0f172a');gr.addColorStop(1,'#1e1b4b');c.fillStyle=gr;c.fillRect(0,0,W,H);\n    for(const s of g.stars){c.fillStyle=`rgba(255,255,255,${.4+s.s*.25})`;c.fillRect(s.x,s.y,s.s,s.s*(g.state==='launch'?4:1));}\n    emo(c,'🌕',W-48,40+Math.min(0,g.ry*.05),40);\n    if(g.word){\n      const fail=g.state==='fail';\n      slotsPanel(c,92,g.word,i=>(g.got.has(g.word[i])||fail)?g.word[i]:'',i=>fail&&!g.got.has(g.word[i])?'#fca5a5':'#fff');\n    }\n    roundBtn(c,W-36,150,20,'🔊');\n    if(builtinSent(g.word))roundBtn(c,36,150,20,'💬');\n    c.fillStyle='#64748b';rr(c,140,290,80,14,4);c.fill();\n    if(g.state==='launch'){c.fillStyle='#f97316';c.beginPath();c.moveTo(170,270+g.ry);c.lineTo(190,270+g.ry);c.lineTo(180,300+g.ry+Math.random()*14);c.closePath();c.fill();}\n    c.save();c.translate(180,245+g.ry);if(!LOOKS.moonrocket)c.rotate(-Math.PI/4);emo(c,LOOKS.moonrocket?'🛰️':'🚀',0,0,56);c.restore();\n    for(let i=0;i<FUEL;i++){const on=i<g.fuel;c.fillStyle=on?(g.fuel<=2?'#f97316':'#22c55e'):'rgba(255,255,255,.15)';rr(c,250+i*(80/FUEL),286,80/FUEL-3,18,3);c.fill();}\n    c.fillStyle='#e0e7ff';c.font='600 11px Fredoka, sans-serif';c.textAlign='center';c.fillText('⛽ FUEL',290,276);\n    if(g.hint){c.fillStyle='rgba(255,255,255,.92)';rr(c,14,182,W-28,58,12);c.fill();c.fillStyle='#1e1b4b';c.font='600 14px Fredoka, sans-serif';c.textAlign='center';c.textBaseline='middle';\n      const blank=g.hint.replace(new RegExp('(^|[^A-Za-z])('+escRe(g.word)+')(?![A-Za-z])','gi'),(m,p)=>p+'_'.repeat(g.word.length));wrap(c,'💬 '+blank,180,201,W-48,18);}\n    for(const k of keyPos){\n      const t=g.tried.has(k.ch),good=t&&g.word.includes(k.ch);\n      c.fillStyle=good?'#15803d':t?'#475569':'#ede9fe';rr(c,k.x,k.y,KS,KS,10);c.fill();\n      c.fillStyle=good||t?'#fff':'#3b0764';c.font='700 22px Fredoka, sans-serif';c.textAlign='center';c.textBaseline='middle';c.fillText(k.ch.toUpperCase(),k.x+KS/2,k.y+KS/2+1);\n    }\n    drawParts(c,g.parts);drawPops(c,g.pops);\n  };\n  return g;\n}\n\n/* ===== GAME 13: Scramble Rush ===== */\nfunction createScramble(){\n  let pool=wordPool().filter(w=>w.length>=3);if(!pool.length)pool=wordPool();\n  const T={easy:75,normal:60,hard:50}[S.set.diff]||60;\n  const g={over:false,score:0,t:0,time:T,tmax:T,word:'',tiles:[],built:'',done:0,wait:0,parts:[],pops:[],\n    bg:Array.from({length:14},()=>({x:Math.random()*W,y:Math.random()*H,r:rnd(10,30),v:rnd(8,20)}))};\n  g.intro=`Unscramble the mixed-up letters! Tap them <b>in the right order</b> to spell the word. Each word you finish adds time.<br><br>Tap 🔊 to hear the word, or ⏭ to skip one (costs 3 seconds). You have ${T} seconds!`;\n  g.hud=()=>`🔀 ${plural(g.done,'word')} · ⏱ ${Math.ceil(g.time)}s · ⭐ ${g.score}`;\n  g.endTitle='Super unscrambling!';\n  function layout(){\n    const n=g.tiles.length,perRow=Math.min(n,6),rows=Math.ceil(n/6),sz=Math.min(54,(W-30)/perRow-8);\n    g.tiles.forEach((t,i)=>{const r=Math.floor(i/6),inRow=r<rows-1?6:n-6*(rows-1),idx=i-6*r,rowW=inRow*sz+(inRow-1)*8;t.sz=sz;t.x=(W-rowW)/2+idx*(sz+8);t.y=330+r*(sz+12);});\n  }\n  function next(){\n    g.word=pickWord(pool,g.word);g.built='';\n    let letters=[...g.word];for(let k=0;k<12;k++){letters=shuffle(letters);if(letters.join('')!==g.word||new Set(g.word).size<2)break;}\n    g.tiles=letters.map(c=>({c,used:false,wig:0}));layout();speak(g.word);\n  }\n  g.begin=()=>next();\n  g.tap=(x,y)=>{\n    if(g.wait>0)return;\n    if(hitCircle(x,y,60,250,22)){speak(g.word);return;}\n    if(hitCircle(x,y,W-60,250,22)){g.time=Math.max(0,g.time-3);addPop(g.pops,`Skipped: ${g.word.toUpperCase()}`,180,200,'#e5e7eb',22);sfx('swoosh');next();return;}\n    const t=g.tiles.find(t=>!t.used&&x>=t.x&&x<=t.x+t.sz&&y>=t.y&&y<=t.y+t.sz);if(!t)return;\n    if(t.c===g.word[g.built.length]){\n      t.used=true;g.built+=t.c;sfx('pop');burst(g.parts,t.x+t.sz/2,t.y+t.sz/2,['#fde047','#fff'],8,120);\n      if(g.built.length===g.word.length){g.done++;const pts=g.word.length*2;g.score+=pts;addTime(g,3);addPop(g.pops,`${g.word.toUpperCase()}! +${pts}`,180,190,'#fde047',34);sfx('win');g.wait=.9;}\n    }else{t.wig=.4;sfx('nope');}\n  };\n  g.update=dt=>{\n    g.t+=dt;g.time-=dt;if(g.time<=0){g.time=0;g.over=true;return;}\n    if(g.wait>0){g.wait-=dt;if(g.wait<=0)next();}\n    for(const t of g.tiles)t.wig=Math.max(0,t.wig-dt);\n    for(const b of g.bg){b.y-=b.v*dt;if(b.y<-40){b.y=H+40;b.x=Math.random()*W;}}\n    stepParts(g.parts,dt,250);stepPops(g.pops,dt);\n  };\n  g.draw=c=>{\n    const gr=c.createLinearGradient(0,0,0,H);gr.addColorStop(0,'#7c3aed');gr.addColorStop(1,'#db2777');c.fillStyle=gr;c.fillRect(0,0,W,H);\n    for(const b of g.bg){c.fillStyle='rgba(255,255,255,.08)';c.beginPath();c.arc(b.x,b.y,b.r,0,7);c.fill();}\n    const tf=Math.max(0,Math.min(1,g.time/g.tmax));\n    c.fillStyle='rgba(255,255,255,.3)';rr(c,20,16,W-40,12,6);c.fill();c.fillStyle=tf>.3?'#86efac':'#fca5a5';rr(c,20,16,(W-40)*tf,12,6);c.fill();\n    label(c,'Unscramble!',180,62,30,'#fde047');\n    if(g.word){\n      const L=g.word.length,bw=Math.min(40,(W-40)/L),x0=(W-bw*L)/2;\n      for(let i=0;i<L;i++){const x=x0+i*bw;c.fillStyle=i<g.built.length?'#fff':'rgba(255,255,255,.25)';rr(c,x+3,110,bw-6,bw+6,8);c.fill();\n        if(i<g.built.length){c.fillStyle='#6d28d9';c.font=`700 ${Math.floor(bw*.75)}px Fredoka, sans-serif`;c.textAlign='center';c.textBaseline='middle';c.fillText(g.built[i].toUpperCase(),x+bw/2,110+(bw+6)/2+1);}}\n    }\n    roundBtn(c,60,250,22,'🔊');roundBtn(c,W-60,250,22,'⏭️');\n    c.fillStyle='rgba(255,255,255,.85)';c.font='600 12px Fredoka, sans-serif';c.textAlign='center';c.fillText('hear it',60,284);c.fillText('skip (−3s)',W-60,284);\n    for(const t of g.tiles){\n      if(t.used)continue;const wx=t.wig>0?Math.sin(t.wig*40)*4:0;\n      c.fillStyle='#fde68a';rr(c,t.x+wx,t.y,t.sz,t.sz,12);c.fill();c.fillStyle='#f59e0b';rr(c,t.x+wx,t.y+t.sz-5,t.sz,5,3);c.fill();\n      c.fillStyle='#78350f';c.font=`700 ${Math.floor(t.sz*.55)}px Fredoka, sans-serif`;c.textAlign='center';c.textBaseline='middle';c.fillText(t.c.toUpperCase(),t.x+wx+t.sz/2,t.y+t.sz/2);\n    }\n    drawParts(c,g.parts);drawPops(c,g.pops);\n  };\n  return g;\n}\n\n/* ===== GAME 14: Spelling Snake ===== */\nfunction createSnake(){\n  const pool=wordPool(),AB='abcdefghijklmnopqrstuvwxyz',CS=30,COLS=12,ROWS=11,OY=122,PADY=468,PADH=62;\n  const PADS=[{d:{x:-1,y:0},em:'⬅️'},{d:{x:0,y:-1},em:'⬆️'},{d:{x:0,y:1},em:'⬇️'},{d:{x:1,y:0},em:'➡️'}].map((p,i)=>Object.assign(p,{x:10+i*87,w:80}));\n  const T={easy:75,normal:60,hard:50}[S.set.diff]||60;\n  const g={over:false,score:0,t:0,time:T,tmax:T,word:'',idx:0,snake:[{x:5,y:5},{x:4,y:5},{x:3,y:5}],dir:{x:1,y:0},q:[],stepT:0,sw:null,flash:-1,flashT:0,letters:[],grow:0,done:0,wait:0,parts:[],pops:[]};\n  g.intro=`Steer the 🐍 snake with the <b>arrow buttons</b> (or swipe on the board). Eat the letters <b>in order</b> to spell the word at the top!<br><br>Wrong letters cost 2 seconds. You can slide through the walls. ${T} seconds!`;\n  g.hud=()=>`🐍 ${plural(g.done,'word')} · ⏱ ${Math.ceil(g.time)}s · ⭐ ${g.score}`;\n  g.endTitle='Sssuper spelling!';\n  const need=()=>g.word[g.idx];\n  const cellX=x=>x*CS+CS/2,cellY=y=>OY+y*CS+CS/2;\n  function free(){const occ=new Set(g.snake.map(s=>s.x+','+s.y).concat(g.letters.map(l=>l.x+','+l.y)));const h=g.snake[0];\n    for(let k=0;k<200;k++){const x=Math.floor(Math.random()*COLS),y=Math.floor(Math.random()*ROWS);if(!occ.has(x+','+y)&&Math.abs(x-h.x)+Math.abs(y-h.y)>2)return {x,y};}return {x:0,y:0};}\n  function place(){g.letters=[];const n=need();if(!n)return;g.letters.push(Object.assign(free(),{l:n}));\n    const used=new Set([n]);while(g.letters.length<4){const d=pick(AB);if(used.has(d))continue;used.add(d);g.letters.push(Object.assign(free(),{l:d}));}}\n  function next(){g.word=pickWord(pool,g.word);g.idx=0;place();speak(g.word);}\n  g.begin=()=>next();\n  function turn(nd){\n    const last=g.q.length?g.q[g.q.length-1]:g.dir;\n    if((nd.x===last.x&&nd.y===last.y)||(nd.x===-last.x&&nd.y===-last.y))return;\n    if(g.q.length<2)g.q.push(nd);\n  }\n  g.tap=(x,y)=>{\n    if(hitCircle(x,y,W-34,62,18)){speak(g.word);return;}\n    const p=PADS.findIndex(p=>x>=p.x&&x<=p.x+p.w&&y>=PADY&&y<=PADY+PADH);\n    if(p>=0){turn(PADS[p].d);g.flash=p;g.flashT=.15;sfx('flip');return;}\n    if(y>=OY&&y<OY+ROWS*CS)g.sw={x,y};\n  };\n  g.move=(x,y)=>{\n    if(!g.sw)return;const dx=x-g.sw.x,dy=y-g.sw.y;\n    if(Math.max(Math.abs(dx),Math.abs(dy))<22)return;\n    turn(Math.abs(dx)>Math.abs(dy)?{x:Math.sign(dx),y:0}:{x:0,y:Math.sign(dy)});g.sw={x,y};\n  };\n  g.release=()=>{g.sw=null;};\n  function step(){\n    if(g.q.length)g.dir=g.q.shift();const h=g.snake[0];\n    const nh={x:(h.x+g.dir.x+COLS)%COLS,y:(h.y+g.dir.y+ROWS)%ROWS};\n    const hit=g.snake.findIndex((s,i)=>i<g.snake.length-1&&s.x===nh.x&&s.y===nh.y);\n    if(hit>0){g.snake=g.snake.slice(0,Math.max(3,hit));g.time=Math.max(0,g.time-1);sfx('bonk');addPop(g.pops,'Oops! −1s',cellX(nh.x),cellY(nh.y)-20,'#fca5a5',22);}\n    g.snake.unshift(nh);\n    const li=g.letters.findIndex(l=>l.x===nh.x&&l.y===nh.y);\n    if(li>=0){\n      const L=g.letters[li];\n      if(g.wait<=0&&L.l===need()){\n        g.grow+=1;g.idx++;g.score+=1;sfx('pop');burst(g.parts,cellX(nh.x),cellY(nh.y),['#fde047','#86efac','#fff'],12,140);\n        if(g.idx>=g.word.length){g.done++;g.score+=g.word.length;addTime(g,3);addPop(g.pops,`${g.word.toUpperCase()}! +${g.word.length}`,180,240,'#fde047',34);sfx('win');g.letters=[];g.wait=.9;}\n        else place();\n      }else{g.letters.splice(li,1);g.time=Math.max(0,g.time-2);sfx('nope');addPop(g.pops,'−2s · Need '+(need()||'').toUpperCase(),cellX(nh.x),cellY(nh.y)-20,'#fca5a5',20);\n        const used=new Set(g.letters.map(l=>l.l));let d;do{d=pick(AB);}while(used.has(d)||d===need());g.letters.push(Object.assign(free(),{l:d}));}\n    }\n    if(g.grow>0)g.grow--;else g.snake.pop();\n  }\n  g.update=dt=>{\n    g.t+=dt;g.time-=dt;if(g.time<=0){g.time=0;g.over=true;return;}\n    if(g.wait>0){g.wait-=dt;if(g.wait<=0)next();}\n    g.flashT=Math.max(0,g.flashT-dt);\n    g.stepT+=dt;const iv=Math.max(.24,.38-g.done*.006)/DF();\n    while(g.stepT>=iv){g.stepT-=iv;step();}\n    stepParts(g.parts,dt,200);stepPops(g.pops,dt);\n  };\n  g.draw=c=>{\n    c.fillStyle='#14532d';c.fillRect(0,0,W,H);\n    for(let y=0;y<ROWS;y++)for(let x=0;x<COLS;x++){c.fillStyle=(x+y)%2?'#4ade80':'#22c55e';c.fillRect(x*CS,OY+y*CS,CS,CS);}\n    PADS.forEach((p,i)=>{c.fillStyle=g.flashT>0&&g.flash===i?'#fde047':'rgba(255,255,255,.9)';rr(c,p.x,PADY,p.w,PADH,16);c.fill();emo(c,p.em,p.x+p.w/2,PADY+PADH/2+1,34);});\n    c.fillStyle='#6d28d9';rr(c,10,10,W-20,84,18);c.fill();\n    c.fillStyle='#ddd6fe';c.font='600 13px Fredoka, sans-serif';c.textAlign='center';c.textBaseline='middle';c.fillText(g.started?'EAT THE LETTERS IN ORDER':'GET READY',170,26);\n    if(g.word){slotsPanel(c,58,g.word,i=>g.word[i],i=>i<g.idx?'#fff':i===g.idx?'#fde047':'rgba(255,255,255,.3)');roundBtn(c,W-34,62,18,'🔊');}\n    const tf=Math.max(0,Math.min(1,g.time/g.tmax));c.fillStyle='rgba(255,255,255,.6)';rr(c,20,102,W-40,10,5);c.fill();c.fillStyle=tf>.3?'#fde047':'#ef4444';rr(c,20,102,(W-40)*tf,10,5);c.fill();\n    for(const L of g.letters){const x=cellX(L.x),y=cellY(L.y);c.fillStyle='#fff';c.beginPath();c.arc(x,y,13,0,7);c.fill();c.strokeStyle='#7c3aed';c.lineWidth=2.5;c.stroke();c.fillStyle='#4c1d95';c.font='700 18px Fredoka, sans-serif';c.fillText(L.l.toUpperCase(),x,y+1);}\n    g.snake.forEach((s,i)=>{const x=cellX(s.x),y=cellY(s.y);c.fillStyle=LOOKS.snake?(i===0?'#ef4444':`hsl(${(i*38)%360},85%,58%)`):(i===0?'#7c3aed':i%2?'#a78bfa':'#8b5cf6');c.beginPath();c.arc(x,y,i===0?14:12,0,7);c.fill();\n      if(i===0){const ex=g.dir.x*5,ey=g.dir.y*5;c.fillStyle='#fff';c.beginPath();c.arc(x+ex-g.dir.y*5,y+ey-g.dir.x*5,4,0,7);c.arc(x+ex+g.dir.y*5,y+ey+g.dir.x*5,4,0,7);c.fill();c.fillStyle='#111';c.beginPath();c.arc(x+ex*1.3-g.dir.y*5,y+ey*1.3-g.dir.x*5,2,0,7);c.arc(x+ex*1.3+g.dir.y*5,y+ey*1.3+g.dir.x*5,2,0,7);c.fill();}});\n    drawParts(c,g.parts);drawPops(c,g.pops);\n  };\n  return g;\n}\n\n/* ===== GAME 15: Spin & Spell ===== */\nfunction createWheel(){\n  const pool=wordPool(),AB='abcdefghijklmnopqrstuvwxyz',CX=180,CY=350,RAD=138;\n  const T={easy:75,normal:60,hard:50}[S.set.diff]||60;\n  const SEGC=['#f87171','#fb923c','#facc15','#4ade80','#38bdf8','#818cf8','#c084fc','#f472b6'];\n  const g={over:false,score:0,t:0,time:T,tmax:T,word:'',idx:0,ang:0,spd:1.3,dirn:1,segs:[],done:0,wait:0,wob:0,parts:[],pops:[]};\n  g.intro=`The letter wheel spins! <b>Tap when the next letter is under the ▼ arrow</b> to spell the word at the top. A wrong tap costs 2 seconds. ${T} seconds!`;\n  g.hud=()=>`🎡 ${plural(g.done,'word')} · ⏱ ${Math.ceil(g.time)}s · ⭐ ${g.score}`;\n  g.endTitle='What a spinner!';\n  const need=()=>g.word[g.idx];\n  function build(){const u=[...new Set(g.word)];const n=Math.min(12,Math.max(8,u.length+3));const seg=u.slice();while(seg.length<n){const d=pick(AB);if(!seg.includes(d))seg.push(d);}g.segs=shuffle(seg);}\n  function next(){g.word=pickWord(pool,g.word);g.idx=0;build();g.spd=Math.min(2.6,1.2+g.done*.06)*DF();speak(g.word);}\n  const under=()=>{const n=g.segs.length,st=Math.PI*2/n;let a=(-Math.PI/2-g.ang)%(Math.PI*2);if(a<0)a+=Math.PI*2;return Math.round(a/st)%n;};\n  g.begin=()=>next();\n  g.tap=(x,y)=>{\n    if(hitCircle(x,y,W-34,62,18)){speak(g.word);return;}\n    if(g.wait>0||g.wob>0)return; // short pause after a miss so button-mashing can't drain the clock\n    const L=g.segs[under()];\n    if(L===need()){\n      g.idx++;g.score+=1;sfx('pop');g.dirn*=-1;burst(g.parts,CX,CY-RAD,['#fde047','#fff','#f472b6'],14,160);\n      if(g.idx>=g.word.length){g.done++;g.score+=g.word.length;addTime(g,3);addPop(g.pops,`${g.word.toUpperCase()}! +${g.word.length}`,180,230,'#fde047',34);sfx('win');g.wait=.9;}\n    }else{g.time=Math.max(0,g.time-2);g.wob=.35;sfx('nope');addPop(g.pops,`That was ${L.toUpperCase()} · need ${need().toUpperCase()}`,180,CY-RAD-40,'#fca5a5',20);}\n  };\n  g.update=dt=>{\n    g.t+=dt;g.time-=dt;if(g.time<=0){g.time=0;g.over=true;return;}\n    if(g.wait>0){g.wait-=dt;if(g.wait<=0)next();}\n    g.wob=Math.max(0,g.wob-dt);\n    g.ang+=g.spd*g.dirn*dt;\n    stepParts(g.parts,dt,250);stepPops(g.pops,dt);\n  };\n  g.draw=c=>{\n    const gr=c.createLinearGradient(0,0,0,H);gr.addColorStop(0,'#1e3a8a');gr.addColorStop(1,'#7c3aed');c.fillStyle=gr;c.fillRect(0,0,W,H);\n    for(let i=0;i<16;i++){c.fillStyle=`hsla(${(i*40+g.t*60)%360},90%,70%,.7)`;c.beginPath();c.arc(12+i*22.5,118,4,0,7);c.fill();}\n    c.fillStyle='rgba(255,255,255,.95)';rr(c,10,10,W-20,84,18);c.fill();\n    c.fillStyle='#6b7280';c.font='600 13px Fredoka, sans-serif';c.textAlign='center';c.textBaseline='middle';c.fillText(g.started?'TAP WHEN THE NEXT LETTER IS UNDER ▼':'GET READY',170,26);\n    if(g.word){slotsPanel(c,58,g.word,i=>g.word[i],i=>i<g.idx?'#7c3aed':i===g.idx?'#f59e0b':'#d1d5db');roundBtn(c,W-34,62,18,'🔊');}\n    const tf=Math.max(0,Math.min(1,g.time/g.tmax));c.fillStyle='rgba(255,255,255,.3)';rr(c,20,132,W-40,10,5);c.fill();c.fillStyle=tf>.3?'#86efac':'#fca5a5';rr(c,20,132,(W-40)*tf,10,5);c.fill();\n    const n=g.segs.length,st=Math.PI*2/n,cur=under(),wx=g.wob>0?Math.sin(g.wob*50)*5:0;\n    c.save();c.translate(CX+wx,CY);\n    c.fillStyle='#fff';c.beginPath();c.arc(0,0,RAD+8,0,7);c.fill();\n    for(let i=0;i<n;i++){const a=g.ang+i*st;\n      c.fillStyle=SEGC[i%SEGC.length];c.beginPath();c.moveTo(0,0);c.arc(0,0,RAD,a-st/2,a+st/2);c.closePath();c.fill();\n      if(i===cur){c.strokeStyle='#fff';c.lineWidth=5;c.stroke();}\n      c.save();c.rotate(a);c.translate(RAD*.72,0);c.rotate(-a);\n      c.fillStyle='#fff';c.font='700 28px Fredoka, sans-serif';c.textAlign='center';c.textBaseline='middle';c.lineWidth=4;c.strokeStyle='rgba(0,0,0,.25)';c.strokeText(g.segs[i].toUpperCase(),0,1);c.fillText(g.segs[i].toUpperCase(),0,1);\n      c.restore();}\n    c.fillStyle='#fff';c.beginPath();c.arc(0,0,26,0,7);c.fill();emo(c,'⭐',0,1,30);\n    c.restore();\n    c.fillStyle='#fde047';c.beginPath();c.moveTo(CX-16,CY-RAD-26);c.lineTo(CX+16,CY-RAD-26);c.lineTo(CX,CY-RAD+4);c.closePath();c.fill();c.strokeStyle='#92400e';c.lineWidth=2;c.stroke();\n    drawParts(c,g.parts);drawPops(c,g.pops);\n  };\n  return g;\n}\n\n/* ===== GAME 16: Letter Detective ===== */\nfunction createDetective(){\n  let pool=wordPool().filter(w=>w.length>=3);if(!pool.length)pool=wordPool();\n  const VOW='aeiou',AB='abcdefghijklmnopqrstuvwxyz';\n  const CONF={b:'dpv',d:'btg',p:'bqg',m:'nw',n:'mh',c:'ksq',k:'cg',s:'czx',f:'vth',v:'fw',g:'jqd',j:'gy',t:'dfl',r:'lw',l:'ri',w:'vr',y:'ij',h:'kn',x:'ks',z:'sx',q:'kg'};\n  const T={easy:75,normal:60,hard:50}[S.set.diff]||60;\n  const g={over:false,score:0,t:0,time:T,tmax:T,word:'',blanks:[],bi:0,filled:{},choices:[],streak:0,done:0,wait:0,wig:[0,0,0],parts:[],pops:[]};\n  g.intro=`Some letters in the word are missing! 🔍 Listen to the word, then <b>tap the letter that fills the glowing blank</b>. Three right in a row earns bonus points. A wrong guess costs 2 seconds. ${T} seconds!`;\n  g.hud=()=>`🔍 ${plural(g.done,'word')} · ⏱ ${Math.ceil(g.time)}s · ⭐ ${g.score}${g.streak>=3?' 🔥':''}`;\n  g.endTitle='Case closed, detective!';\n  const CHX=[70,180,290],CHY=420,CHR=44;\n  function makeChoices(){\n    const right=g.word[g.blanks[g.bi]];\n    const src=VOW.includes(right)?VOW:(CONF[right]||'')+AB;\n    const opts=[right];for(const ch of shuffle([...src])){if(opts.length>=3)break;if(!opts.includes(ch))opts.push(ch);}\n    while(opts.length<3){const d=pick(AB);if(!opts.includes(d))opts.push(d);}\n    g.choices=shuffle(opts);g.wig=[0,0,0];\n  }\n  function next(){\n    g.word=pickWord(pool,g.word);const L=g.word.length,n=L<=4?1:L<=7?2:3;\n    const idx=[...g.word].map((c,i)=>/[a-z]/.test(c)?i:-1).filter(i=>i>=0);\n    g.blanks=shuffle(idx.slice()).slice(0,Math.min(n,idx.length)).sort((a,b)=>a-b);g.bi=0;g.filled={};makeChoices();speak(g.word);\n  }\n  g.begin=()=>next();\n  g.tap=(x,y)=>{\n    if(hitCircle(x,y,W-40,96,22)){speak(g.word);return;}\n    if(g.wait>0||g.cool>0)return;\n    const i=CHX.findIndex(cx=>hitCircle(x,y,cx,CHY,CHR));if(i<0)return;\n    const ch=g.choices[i],right=g.word[g.blanks[g.bi]];\n    if(ch===right){\n      g.filled[g.blanks[g.bi]]=ch;g.bi++;g.streak++;const pts=1+(g.streak>=3?1:0);g.score+=pts;sfx('pop');burst(g.parts,CHX[i],CHY,['#fde047','#fff'],12,150);\n      if(g.streak===3)addPop(g.pops,'Streak! 🔥 double points',180,330,'#fb923c',22);\n      if(g.bi>=g.blanks.length){g.done++;g.score+=g.word.length;addTime(g,3);addPop(g.pops,`${g.word.toUpperCase()}! +${g.word.length}`,180,250,'#fde047',34);sfx('win');g.wait=1;}\n      else makeChoices();\n    }else{g.streak=0;g.wig[i]=.4;g.cool=.4;g.time=Math.max(0,g.time-2);sfx('nope');addPop(g.pops,'−2s',CHX[i],CHY-60,'#fca5a5',22);}\n  };\n  g.update=dt=>{\n    g.t+=dt;g.cool=Math.max(0,(g.cool||0)-dt);g.time-=dt;if(g.time<=0){g.time=0;g.over=true;return;}\n    if(g.wait>0){g.wait-=dt;if(g.wait<=0)next();}\n    g.wig=g.wig.map(v=>Math.max(0,v-dt));\n    stepParts(g.parts,dt,250);stepPops(g.pops,dt);\n  };\n  g.draw=c=>{\n    const gr=c.createLinearGradient(0,0,0,H);gr.addColorStop(0,'#0f766e');gr.addColorStop(1,'#134e4a');c.fillStyle=gr;c.fillRect(0,0,W,H);\n    for(let i=0;i<6;i++){c.fillStyle='rgba(255,255,255,.05)';c.fillRect(0,i*90+20,W,40);}\n    const tf=Math.max(0,Math.min(1,g.time/g.tmax));c.fillStyle='rgba(255,255,255,.25)';rr(c,20,16,W-40,12,6);c.fill();c.fillStyle=tf>.3?'#fde047':'#fca5a5';rr(c,20,16,(W-40)*tf,12,6);c.fill();\n    emo(c,'🕵️',44,96,44);label(c,'Find the missing letters!',190,56,20,'#fff');\n    roundBtn(c,W-40,96,22,'🔊');\n    if(g.word){\n      const L=g.word.length,bw=Math.min(40,(W-30)/L),x0=(W-bw*L)/2;\n      for(let i=0;i<L;i++){const x=x0+i*bw,isB=g.blanks.includes(i),cur=isB&&g.blanks[g.bi]===i&&g.wait<=0,shown=!isB||g.filled[i];\n        c.fillStyle=cur?`rgba(253,224,71,${.55+.35*Math.sin(g.t*6)})`:(isB&&!g.filled[i])?'rgba(255,255,255,.18)':isB?'#dcfce7':'rgba(255,255,255,.92)';rr(c,x+2,170,bw-4,bw+10,8);c.fill();\n        if(shown){c.fillStyle=isB?'#15803d':'#134e4a';c.font=`700 ${Math.floor(bw*.72)}px Fredoka, sans-serif`;c.textAlign='center';c.textBaseline='middle';c.fillText((g.filled[i]||g.word[i]).toUpperCase(),x+bw/2,170+(bw+10)/2+1);}\n        else{c.fillStyle='#fff';c.font=`700 ${Math.floor(bw*.6)}px Fredoka, sans-serif`;c.textAlign='center';c.textBaseline='middle';c.fillText('?',x+bw/2,170+(bw+10)/2+1);}\n      }\n    }\n    emo(c,'🔍',180,300,46);\n    if(g.wait<=0)g.choices.forEach((ch,i)=>{const wx=g.wig[i]>0?Math.sin(g.wig[i]*40)*5:0,x=CHX[i]+wx;\n      c.fillStyle='#fff';c.beginPath();c.arc(x,CHY,CHR,0,7);c.fill();c.strokeStyle='#fde047';c.lineWidth=5;c.stroke();\n      c.fillStyle='#134e4a';c.font='700 42px Fredoka, sans-serif';c.textAlign='center';c.textBaseline='middle';c.fillText(ch.toUpperCase(),x,CHY+2);});\n    drawParts(c,g.parts);drawPops(c,g.pops);\n  };\n  return g;\n}\n\n/* ===== GAME 17: Field Goal Frenzy (American football) ===== */\nfunction createFieldGoal(){\n  const BX=180,BY=468,DIST=[20,25,25,30,30,35,40,40,45,50];\n  const g={over:false,score:0,t:0,kick:0,total:DIST.length,good:0,state:'aim',ang:0,angT:Math.random()*6,pow:0,powT:0,wind:0,timer:0,ball:null,parts:[],pops:[],crowd:[],flash:0};\n  for(let i=0;i<90;i++)g.crowd.push({x:Math.random()*W,y:44+Math.random()*48,c:['#f87171','#60a5fa','#fbbf24','#34d399','#a78bfa','#fff','#fb923c'][i%7],ph:Math.random()*6});\n  g.intro='Kick it through the yellow posts!<br><b>Tap once</b> to lock your aim when the dashed line turns green. It already counts the 💨 wind!<br><b>Tap again</b> to kick when the power bar passes the line.<br>10 kicks that get longer. Field goal = 3 points, 40+ yards = bonus!';\n  g.hud=()=>`🏈 Kick ${Math.min(g.kick+1,g.total)}/${g.total} · ✅ ${g.good} good · ⭐ ${g.score}`;\n  g.endTitle='What a kicker!';\n  const yards=()=>DIST[Math.min(g.kick,g.total-1)];\n  // Goalpost size and place for the current distance (farther = smaller and higher).\n  function post(){\n    const d=yards(),f=(d-20)/30,s=1.05-f*.5,baseY=236-f*62;\n    return {d,s,baseY,barY:baseY-34*s,topY:baseY-112*s,hw:46*s*TOL()};\n  }\n  const need=()=>.3+(yards()-20)/30*.45;               // power needed to clear the bar\n  function newKick(){\n    g.state='aim';g.ball=null;g.angT=Math.random()*6;g.pow=0;g.powT=0;\n    const d=yards();g.wind=d<=20?0:Math.round(rnd(-1,1)*(4+d/5));   // mph, minus = blowing left\n  }\n  newKick();\n  // Where the ball ends up sideways at the posts for an aim angle (wind included).\n  function landX(ang){const P=post();return BX+Math.tan(ang)*(BY-P.barY)*.95+g.wind*2.1*P.s*(P.d/30);}\n  g.tap=()=>{\n    if(g.state==='aim'){g.state='power';sfx('tick');return;}\n    if(g.state!=='power')return;\n    const P=post(),x=landX(g.ang),off=Math.abs(x-BX),p=g.pow,nd=need();\n    let res;\n    if(p<nd)res='short';\n    else if(off<P.hw-6)res='good';\n    else if(off<P.hw+6)res='doink';\n    else res='wide';\n    const high=res==='short'?P.barY+18:P.barY-30*P.s-(p-nd)*90*P.s;\n    g.ball={t:0,dur:1.15,x0:BX,y0:BY,x1:x,y1:high,res,s:P.s,spin:0};\n    g.state='flight';g.kick++;sfx('hit');\n  };\n  g.update=dt=>{\n    g.t+=dt;stepParts(g.parts,dt,240);stepPops(g.pops,dt);g.flash=Math.max(0,g.flash-dt);\n    if(g.state==='aim'){g.angT+=dt*1.7*DF();g.ang=Math.sin(g.angT)*.42;}\n    else if(g.state==='power'){g.powT+=dt*.85*DF();const k=g.powT%2;g.pow=k<1?k:2-k;}\n    else if(g.state==='flight'){\n      const b=g.ball;b.t+=dt;b.spin+=dt*9;\n      if(b.t>=b.dur){\n        const P=post(),d=P.d;\n        if(b.res==='good'){\n          const pts=3+(d>=50?2:d>=40?1:0);g.score+=pts;g.good++;\n          addPop(g.pops,(d>=50?'LONG BOMB! ':'IT\\'S GOOD! ')+'+'+pts,180,260,'#fde047',d>=50?30:36);\n          sfx('hr');burst(g.parts,b.x1,b.y1,['#fde047','#fff','#f97316','#60a5fa'],30,220);g.flash=1;\n        }else if(b.res==='doink'){addPop(g.pops,'DOINK! Off the post',180,260,'#e5e7eb',28);sfx('bonk');}\n        else if(b.res==='short'){addPop(g.pops,'Short! More power',180,260,'#fca5a5',30);sfx('miss');}\n        else{addPop(g.pops,(b.x1<BX?'Wide left!':'Wide right!'),180,260,'#fca5a5',32);sfx('miss');}\n        g.state='result';g.timer=1.5;\n      }\n    }else if(g.state==='result'){\n      g.timer-=dt;const b=g.ball;\n      if(b&&b.res!=='good'){b.y1+=dt*120;}               // a missed ball drops\n      if(g.timer<=0){if(g.kick>=g.total){g.over=true;return;}newKick();}\n    }\n  };\n  function goalpost(c,P){\n    c.strokeStyle='#facc15';c.lineCap='round';\n    c.lineWidth=Math.max(3,7*P.s);c.beginPath();c.moveTo(BX,P.baseY+30*P.s);c.lineTo(BX,P.barY);c.stroke();\n    c.lineWidth=Math.max(3,6*P.s);c.beginPath();c.moveTo(BX-P.hw,P.barY);c.lineTo(BX+P.hw,P.barY);\n    c.moveTo(BX-P.hw,P.barY);c.lineTo(BX-P.hw,P.topY);c.moveTo(BX+P.hw,P.barY);c.lineTo(BX+P.hw,P.topY);c.stroke();\n    c.fillStyle='#ef4444';for(const sx of [-1,1]){c.beginPath();c.moveTo(BX+sx*P.hw,P.topY);c.lineTo(BX+sx*P.hw+sx*10*P.s,P.topY+5*P.s);c.lineTo(BX+sx*P.hw,P.topY+10*P.s);c.fill();}\n  }\n  g.draw=c=>{\n    const P=post();\n    const sky=c.createLinearGradient(0,0,0,120);sky.addColorStop(0,'#1e3a8a');sky.addColorStop(1,'#3b82f6');c.fillStyle=sky;c.fillRect(0,0,W,120);\n    const party=g.flash>0;\n    for(const p of g.crowd){const bob=Math.abs(Math.sin(g.t*(party?14:3)+p.ph))*(party?6:1.4);c.fillStyle=p.c;c.beginPath();c.arc(p.x,p.y-bob,4,0,7);c.fill();}\n    c.fillStyle='#e2e8f0';c.fillRect(0,100,W,12);c.fillStyle='#1e3a8a';c.font='700 9px Fredoka, sans-serif';c.textAlign='center';c.textBaseline='middle';c.fillText('🏈 SPELLING ARCADE BOWL 🏈',180,106);\n    // field in perspective\n    const top=112;\n    for(let i=0;i<12;i++){const y0=top+Math.pow(i/12,1.6)*(H-top),y1=top+Math.pow((i+1)/12,1.6)*(H-top);c.fillStyle=i%2?'#16a34a':'#22c55e';c.fillRect(0,y0,W,y1-y0+1);}\n    c.strokeStyle='rgba(255,255,255,.75)';c.lineWidth=2;\n    for(let i=0;i<=12;i++){const y=top+Math.pow(i/12,1.6)*(H-top);c.beginPath();c.moveTo(0,y);c.lineTo(W,y);c.stroke();}\n    c.lineWidth=3;c.beginPath();c.moveTo(150,top);c.lineTo(20,H);c.moveTo(210,top);c.lineTo(340,H);c.stroke();\n    goalpost(c,P);\n    // wind flag\n    c.fillStyle='rgba(15,23,42,.6)';rr(c,8,124,112,30,10);c.fill();\n    c.fillStyle='#fff';c.font='700 14px Fredoka, sans-serif';c.textAlign='left';\n    c.fillText(g.wind===0?'💨 No wind':`💨 ${g.wind<0?'←':'→'} ${Math.abs(g.wind)} mph`,16,139);\n    c.fillStyle='rgba(15,23,42,.6)';rr(c,W-104,124,96,30,10);c.fill();c.fillStyle='#fde047';c.textAlign='center';c.fillText(`${P.d} yards`,W-56,139);\n    // kicker's tee and aiming guide\n    if(g.state==='aim'||g.state==='power'){\n      const lx=landX(g.ang),hit=Math.abs(lx-BX)<P.hw-6;\n      c.save();c.setLineDash([8,8]);c.lineDashOffset=-g.t*30;c.lineWidth=4;c.lineCap='round';\n      c.strokeStyle=hit?'rgba(74,222,128,.9)':'rgba(255,255,255,.6)';\n      c.beginPath();for(let i=0;i<=30;i++){const q=i/30,x=BX+(lx-BX)*q*q*.4+(lx-BX)*q*.6,y=BY+(P.barY-BY)*q-Math.sin(q*Math.PI)*60;if(i)c.lineTo(x,y);else c.moveTo(x,y);}c.stroke();\n      c.restore();\n      c.fillStyle=hit?'#4ade80':'#fff';c.beginPath();c.arc(lx,P.barY-14*P.s,5,0,7);c.fill();\n    }\n    if(g.state==='power'){\n      const x=W-36,y=230,h=200,nd=need();\n      c.fillStyle='rgba(15,23,42,.65)';rr(c,x-14,y-10,28,h+20,10);c.fill();\n      const col=g.pow>=nd?'#4ade80':'#f97316';c.fillStyle=col;rr(c,x-8,y+h*(1-g.pow),16,h*g.pow,6);c.fill();\n      c.strokeStyle='#fde047';c.lineWidth=3;c.beginPath();c.moveTo(x-18,y+h*(1-nd));c.lineTo(x+18,y+h*(1-nd));c.stroke();\n      c.fillStyle='#fff';c.font='700 12px Fredoka, sans-serif';c.textAlign='center';c.fillText('POWER',x,y-20);\n    }\n    c.fillStyle='#f97316';c.beginPath();c.moveTo(BX-9,BY+20);c.lineTo(BX+9,BY+20);c.lineTo(BX,BY+6);c.fill();\n    emo(c,'🧍',BX-46,BY-6,52);\n    const b=g.ball;\n    if(b){const q=Math.min(1,b.t/b.dur),e=1-Math.pow(1-q,1.6);\n      const x=b.x0+(b.x1-b.x0)*e,y=b.y0+(b.y1-b.y0)*e-Math.sin(q*Math.PI)*90,sz=34-(34-18*b.s)*q;\n      c.save();c.translate(x,y);c.rotate(b.spin);emo(c,'🏈',0,0,sz);c.restore();}\n    else emo(c,'🏈',BX,BY,34);\n    if(g.state==='aim'){c.fillStyle='rgba(255,255,255,.85)';c.font='700 15px Fredoka, sans-serif';c.textAlign='center';c.fillText('Tap to lock your aim',180,BY+50);}\n    if(g.state==='power'){c.fillStyle='rgba(255,255,255,.85)';c.font='700 15px Fredoka, sans-serif';c.textAlign='center';c.fillText('Tap to kick! Pass the yellow line',180,BY+50);}\n    drawParts(c,g.parts);drawPops(c,g.pops);\n  };\n  return g;\n}\n\n/* ===== shared helpers for the newer games ===== */\nfunction dashLine(c,pts,color,w,offset){\n  c.save();c.setLineDash([8,8]);c.lineDashOffset=offset||0;c.lineWidth=w||4;c.lineCap='round';c.strokeStyle=color;\n  c.beginPath();pts.forEach((p,i)=>i?c.lineTo(p[0],p[1]):c.moveTo(p[0],p[1]));c.stroke();c.restore();\n}\nfunction hintText(c,text,y){c.fillStyle='rgba(255,255,255,.9)';c.font='700 15px Fredoka, sans-serif';c.textAlign='center';c.textBaseline='middle';c.fillText(text,180,y);}\nfunction wordHeader(c,g,title){\n  c.fillStyle='#6d28d9';rr(c,10,10,W-20,84,18);c.fill();\n  c.fillStyle='#ddd6fe';c.font='600 13px Fredoka, sans-serif';c.textAlign='center';c.textBaseline='middle';c.fillText(g.started?title:'GET READY',170,26);\n  if(g.word){slotsPanel(c,58,g.word,i=>g.word[i],i=>i<g.idx?'#fff':i===g.idx?'#fde047':'rgba(255,255,255,.3)');roundBtn(c,W-34,62,18,'🔊');}\n}\nfunction timeBar(c,g,y){const tf=Math.max(0,Math.min(1,g.time/g.tmax));c.fillStyle='rgba(255,255,255,.7)';rr(c,20,y,W-40,10,5);c.fill();c.fillStyle=tf>.3?'#22c55e':'#ef4444';rr(c,20,y,(W-40)*tf,10,5);c.fill();}\nconst LETTER_COLS=['#ef4444','#f97316','#eab308','#22c55e','#06b6d4','#3b82f6','#8b5cf6','#ec4899'];\nconst ABC='abcdefghijklmnopqrstuvwxyz';\nfunction decoys(word,n){const out=[];for(let i=0;i<n;i++){let l;do{l=pick(ABC);}while(word.includes(l)&&Math.random()<.7);out.push(l);}return out;}\n\n/* ===== GAME 18: Hockey Shootout ===== */\nfunction createHockey(){\n  const GX=180,GY=132,GW=124,PX=180,PY=468,TRAVEL=.42;\n  const g={over:false,score:0,t:0,shot:0,total:10,goals:0,state:'aim',aimT:Math.random()*6,gp:Math.random()*6,gs:1.7,timer:0,puck:null,parts:[],pops:[],flash:0};\n  g.intro='Slap shot! The 🎯 target slides across the net and the goalie slides too. <b>Tap to shoot</b> when the dashed line turns green: the goalie won\\'t be there when the puck arrives.<br>10 shots. Goal = 2 points, corner goal = 3!';\n  g.hud=()=>`🏒 Shot ${Math.min(g.shot+1,g.total)}/${g.total} · 🥅 ${g.goals} · ⭐ ${g.score}`;\n  g.endTitle='What a sniper!';\n  const span=GW/2-16;\n  const goalieAt=ahead=>GX+Math.sin(g.gp+ahead*g.gs*DF())*span;\n  const aimX=()=>GX+Math.sin(g.aimT)*(GW/2-8);\n  const reach=()=>26/TOL();\n  const open=()=>Math.abs(goalieAt(TRAVEL/DF())-aimX())>=reach();\n  g.tap=()=>{\n    if(g.state!=='aim')return;\n    const ax=aimX(),saved=!open(),corner=Math.abs(ax-GX)>GW/2-22;\n    g.puck={t:0,dur:TRAVEL/DF(),x1:ax,y1:GY-8,saved,corner};g.state='shot';g.shot++;sfx('hit');\n  };\n  g.update=dt=>{\n    g.t+=dt;stepParts(g.parts,dt,200);stepPops(g.pops,dt);g.flash=Math.max(0,g.flash-dt);\n    if(g.state!=='result')g.gp+=dt*g.gs*DF();\n    if(g.state==='aim')g.aimT+=dt*1.5*DF();\n    else if(g.state==='shot'){\n      const p=g.puck;p.t+=dt;\n      if(p.t>=p.dur){\n        if(p.saved){addPop(g.pops,'SAVED!',180,230,'#fca5a5',38);sfx('bonk');p.vx=(p.x1<goalieAt(0)?-1:1)*rnd(120,200);p.vy=140;p.bx=p.x1;p.by=GY+10;}\n        else{const pts=p.corner?3:2;g.goals++;g.score+=pts;addPop(g.pops,p.corner?'TOP CORNER! +3':'GOAL! +2',180,230,'#fde047',36);sfx('hr');burst(g.parts,p.x1,GY-14,['#ef4444','#fff','#60a5fa','#fde047'],26,200);g.flash=1;}\n        g.state='result';g.timer=1.4;\n      }\n    }else if(g.state==='result'){\n      g.timer-=dt;const p=g.puck;if(p.saved){p.bx+=p.vx*dt;p.by+=p.vy*dt;}\n      if(g.timer<=0){if(g.shot>=g.total){g.over=true;return;}g.state='aim';g.puck=null;g.gs=rnd(1.2,2.4);g.gp=Math.random()*6;}\n    }\n  };\n  g.draw=c=>{\n    const ice=c.createLinearGradient(0,0,0,H);ice.addColorStop(0,'#e0f2fe');ice.addColorStop(1,'#f8fafc');c.fillStyle=ice;c.fillRect(0,0,W,H);\n    c.fillStyle='#1e3a8a';c.fillRect(0,0,W,58);c.fillStyle='#fff';c.font='700 13px Fredoka, sans-serif';c.textAlign='center';c.textBaseline='middle';c.fillText('🏒 SPELLING ARCADE ARENA 🏒',180,30);\n    c.strokeStyle='#ef4444';c.lineWidth=4;c.beginPath();c.moveTo(0,GY+4);c.lineTo(W,GY+4);c.stroke();\n    c.strokeStyle='#3b82f6';c.lineWidth=8;c.beginPath();c.moveTo(0,330);c.lineTo(W,330);c.stroke();\n    c.fillStyle='rgba(96,165,250,.35)';c.beginPath();c.arc(GX,GY+4,58,0,Math.PI);c.fill();\n    c.strokeStyle='#ef4444';c.lineWidth=2;c.beginPath();c.arc(GX,PY-10,46,0,7);c.stroke();\n    // net\n    c.fillStyle='rgba(255,255,255,.95)';c.fillRect(GX-GW/2,GY-40,GW,40);\n    c.strokeStyle='#cbd5e1';c.lineWidth=1;for(let x=GX-GW/2;x<=GX+GW/2;x+=10){c.beginPath();c.moveTo(x,GY-40);c.lineTo(x,GY);c.stroke();}\n    for(let y=GY-40;y<=GY;y+=10){c.beginPath();c.moveTo(GX-GW/2,y);c.lineTo(GX+GW/2,y);c.stroke();}\n    c.strokeStyle='#dc2626';c.lineWidth=5;c.beginPath();c.moveTo(GX-GW/2,GY+2);c.lineTo(GX-GW/2,GY-42);c.lineTo(GX+GW/2,GY-42);c.lineTo(GX+GW/2,GY+2);c.stroke();\n    if(g.flash>0){c.fillStyle=`rgba(239,68,68,${g.flash*.5})`;c.beginPath();c.arc(GX,GY-60,18,0,7);c.fill();}\n    // goalie\n    const gx=g.state==='result'?goalieAt(0):goalieAt(0);\n    c.fillStyle='#1d4ed8';rr(c,gx-24,GY-26,48,30,8);c.fill();\n    c.fillStyle='#f8fafc';rr(c,gx-28,GY-6,16,22,5);c.fill();rr(c,gx+12,GY-6,16,22,5);c.fill();\n    c.fillStyle='#e5e7eb';c.beginPath();c.arc(gx,GY-34,11,0,7);c.fill();c.strokeStyle='#64748b';c.lineWidth=2;for(let i=-6;i<=6;i+=4){c.beginPath();c.moveTo(gx+i,GY-42);c.lineTo(gx+i,GY-26);c.stroke();}\n    c.fillStyle='#92400e';c.fillRect(gx+22,GY-2,6,26);\n    // aim guide\n    if(g.state==='aim'){\n      const ax=aimX(),ok=open();\n      dashLine(c,[[PX,PY-8],[ax,GY-14]],ok?'rgba(22,163,74,.9)':'rgba(30,41,59,.4)',4,-g.t*30);\n      c.strokeStyle=ok?'#16a34a':'#475569';c.lineWidth=3;c.beginPath();c.arc(ax,GY-16,9,0,7);c.stroke();c.beginPath();c.moveTo(ax-14,GY-16);c.lineTo(ax+14,GY-16);c.moveTo(ax,GY-30);c.lineTo(ax,GY-2);c.stroke();\n      hintText(c,ok?'Shoot now!':'Tap to shoot',PY+44);c.fillStyle=ok?'#15803d':'#334155';c.fillText(ok?'Shoot now!':'Tap to shoot',180,PY+44);\n    }\n    // puck\n    const p=g.puck;let px=PX,py=PY;\n    if(p&&g.state==='shot'){const q=Math.min(1,p.t/p.dur);px=PX+(p.x1-PX)*q;py=PY+(p.y1-PY)*q;}\n    else if(p&&g.state==='result'){if(p.saved){px=p.bx;py=p.by;}else{px=p.x1;py=GY-20;}}\n    c.fillStyle='#111827';c.beginPath();c.ellipse(px,py,12,6,0,0,7);c.fill();c.fillStyle='#374151';c.beginPath();c.ellipse(px,py-2,12,5,0,0,7);c.fill();\n    emo(c,'🏒',PX+40,PY+4,52,true);\n    drawParts(c,g.parts);drawPops(c,g.pops);\n  };\n  return g;\n}\n\n/* ===== GAME 19: Bowling Buddies ===== */\nfunction createBowling(){\n  const LX=104,LW=152,FY=470,BR=13,PR=8;\n  const SPOTS=[[180,176],[169,156],[191,156],[158,136],[180,136],[202,136],[147,116],[169,116],[191,116],[213,116]];\n  const g={over:false,score:0,t:0,frame:0,frames:5,roll:0,state:'aim',aimT:Math.random()*6,spinT:0,spin:0,bx:180,ball:null,pins:[],down:0,timer:0,parts:[],pops:[],strikes:0};\n  g.intro='Bowl a strike! <b>Tap once</b> to pick where to roll from. <b>Tap again</b> to set the spin, and the dashed line shows where the ball will curve.<br>5 frames, 2 rolls each. Strike = +10 bonus, spare = +5.';\n  g.hud=()=>`🎳 Frame ${Math.min(g.frame+1,g.frames)}/${g.frames} · Roll ${g.roll+1} · ⭐ ${g.score}`;\n  g.endTitle='Bowling champ!';\n  function rack(){g.pins=SPOTS.map(([x,y])=>({x,y,vx:0,vy:0,up:true,gone:false,rot:0}));}\n  rack();\n  const standing=()=>g.pins.filter(p=>p.up).length;\n  const aimX=()=>180+Math.sin(g.aimT)*(LW/2-BR-6);\n  const path=(x0,spin)=>{const pts=[];for(let i=0;i<=24;i++){const s=i/24;pts.push([x0+spin*58*s*s,FY-(FY-70)*s]);}return pts;};\n  g.tap=()=>{\n    if(g.state==='aim'){g.bx=aimX();g.state='spin';g.spinT=0;sfx('tick');return;}\n    if(g.state==='spin'){g.ball={s:0,x:g.bx,y:FY,x0:g.bx,spin:g.spin,dur:1.5/DF(),gutter:false};g.state='roll';g.before=standing();sfx('swoosh');}\n  };\n  function knock(p,fx,fy,sp){const d=Math.hypot(p.x-fx,p.y-fy)||1;p.up=false;p.vx=(p.x-fx)/d*sp+rnd(-30,30);p.vy=(p.y-fy)/d*sp-rnd(20,60);p.spin=rnd(-8,8);sfx('pop');}\n  g.update=dt=>{\n    g.t+=dt;stepParts(g.parts,dt,0);stepPops(g.pops,dt);\n    if(g.state==='aim')g.aimT+=dt*1.6*DF();\n    else if(g.state==='spin'){g.spinT+=dt*1.3*DF();g.spin=Math.sin(g.spinT*Math.PI);}\n    else if(g.state==='roll'){\n      const b=g.ball;b.s+=dt/b.dur;\n      if(!b.gutter){b.x=b.x0+b.spin*58*b.s*b.s;if(b.x<LX+BR-4||b.x>LX+LW-BR+4){b.gutter=true;b.x=b.x<180?LX-8:LX+LW+8;}}\n      b.y=FY-(FY-70)*b.s;\n      if(!b.gutter)for(const p of g.pins)if(p.up&&Math.hypot(p.x-b.x,p.y-b.y)<BR+PR)knock(p,b.x,b.y+6,260);\n      if(b.s>=1.15){g.state='settle';g.timer=1.1;}\n    }\n    if(g.state==='roll'||g.state==='settle'){\n      for(const p of g.pins){if(p.up||p.gone)continue;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.exp(-1.8*dt);p.vy*=Math.exp(-1.8*dt);p.rot+=(p.spin||0)*dt;\n        for(const q of g.pins)if(q.up&&Math.hypot(q.x-p.x,q.y-p.y)<PR*2-1&&Math.hypot(p.vx,p.vy)>40)knock(q,p.x,p.y,Math.hypot(p.vx,p.vy)*.8);\n        if(p.x<LX-10||p.x>LX+LW+10||p.y<40)p.gone=true;}\n    }\n    if(g.state==='settle'){\n      g.timer-=dt;\n      if(g.timer<=0){\n        const left=standing(),hit=g.before-left;g.score+=hit;\n        if(g.roll===0&&left===0){g.score+=10;g.strikes++;addPop(g.pops,'STRIKE! +20',180,280,'#fde047',40);sfx('hr');burst(g.parts,180,140,['#fde047','#f472b6','#60a5fa','#fff'],34,220);endFrame();return;}\n        if(g.roll===1&&left===0){g.score+=5;addPop(g.pops,`SPARE! +${hit+5}`,180,280,'#86efac',36);sfx('win');endFrame();return;}\n        addPop(g.pops,g.ball.gutter&&!hit?'Gutter ball!':`${hit} pin${hit===1?'':'s'}!`,180,280,hit?'#fff':'#fca5a5',32);\n        if(g.roll===0){g.roll=1;g.pins.forEach(p=>{if(!p.up)p.gone=true;});g.state='aim';g.ball=null;}else endFrame();\n      }\n    }\n    if(g.state==='next'){g.timer-=dt;if(g.timer<=0){if(g.frame>=g.frames){g.over=true;return;}rack();g.roll=0;g.state='aim';g.ball=null;}}\n  };\n  function endFrame(){g.frame++;g.state='next';g.timer=1.2;}\n  g.draw=c=>{\n    c.fillStyle='#1e1b4b';c.fillRect(0,0,W,H);\n    c.fillStyle='#312e81';c.fillRect(0,0,W,60);c.fillStyle='#fde047';c.font='700 14px Fredoka, sans-serif';c.textAlign='center';c.textBaseline='middle';c.fillText('🎳 STAR LANES 🎳',180,30);\n    c.fillStyle='#4b5563';c.fillRect(LX-18,60,18,H);c.fillRect(LX+LW,60,18,H);\n    const lane=c.createLinearGradient(LX,0,LX+LW,0);lane.addColorStop(0,'#d6a46c');lane.addColorStop(.5,'#f0c98e');lane.addColorStop(1,'#d6a46c');c.fillStyle=lane;c.fillRect(LX,60,LW,H);\n    c.strokeStyle='rgba(120,72,30,.25)';c.lineWidth=1;for(let x=LX+10;x<LX+LW;x+=12){c.beginPath();c.moveTo(x,60);c.lineTo(x,H);c.stroke();}\n    c.fillStyle='rgba(120,72,30,.5)';for(let i=-2;i<=2;i++){c.beginPath();c.moveTo(180+i*24,330);c.lineTo(180+i*24-6,344);c.lineTo(180+i*24+6,344);c.fill();}\n    c.fillStyle='#ef4444';c.fillRect(LX,FY+18,LW,3);\n    for(const p of g.pins){if(p.gone)continue;c.save();c.translate(p.x,p.y);c.rotate(p.up?0:p.rot);\n      c.fillStyle='#fff';c.beginPath();c.ellipse(0,0,PR,PR+2,0,0,7);c.fill();c.fillStyle='#ef4444';c.fillRect(-PR+1,-3,PR*2-2,3);c.strokeStyle='#cbd5e1';c.lineWidth=1;c.stroke();c.restore();}\n    if(g.state==='aim'||g.state==='spin'){\n      const x0=g.state==='aim'?aimX():g.bx,sp=g.state==='spin'?g.spin:0;\n      dashLine(c,path(x0,sp),'rgba(255,255,255,.75)',3,-g.t*30);\n      c.fillStyle=LOOKS.bowling?'#172554':'#7c3aed';c.beginPath();c.arc(x0,FY,BR,0,7);c.fill();c.fillStyle=LOOKS.bowling?'#fde047':'#1e1b4b';[[-4,-4],[3,-5],[0,2]].forEach(([dx,dy])=>{c.beginPath();c.arc(x0+dx,FY+dy,2,0,7);c.fill();});if(LOOKS.bowling){c.fillStyle='#c4b5fd';[[-7,4],[6,3],[-1,-8]].forEach(([dx,dy])=>{c.beginPath();c.arc(x0+dx,FY+dy,1.2,0,7);c.fill();});}\n      if(g.state==='spin'){c.fillStyle='rgba(15,23,42,.7)';rr(c,40,500,280,26,13);c.fill();c.fillStyle='#fde047';c.beginPath();c.arc(180+g.spin*126,513,9,0,7);c.fill();c.fillStyle='#fff';c.font='700 11px Fredoka, sans-serif';c.fillText('⟲ SPIN ⟳',180,513);}\n      else hintText(c,'Tap to pick your spot',512);\n    }\n    if(g.ball&&(g.state==='roll')){const b=g.ball,r=BR*(1-b.s*.35);c.fillStyle=LOOKS.bowling?'#172554':'#7c3aed';c.beginPath();c.arc(b.x,b.y,r,0,7);c.fill();if(LOOKS.bowling){c.fillStyle='#fde047';c.beginPath();c.arc(b.x-r*.3,b.y-r*.3,r*.18,0,7);c.fill();}}\n    drawParts(c,g.parts);drawPops(c,g.pops);\n  };\n  return g;\n}\n\n/* ===== GAME 20: Mini Golf ===== */\nfunction createMiniGolf(){\n  const R=8,HR=11,L=24,T=64,Rt=336,B=524;\n  const HOLES=[\n    {b:[180,470],h:[180,130],par:2,walls:[[110,290,46,16],[204,290,46,16]]},\n    {b:[80,470],h:[80,140],par:3,walls:[[L,300,206,18]]},\n    {b:[180,480],h:[180,120],par:2,walls:[],mover:{y:300,w:110,h:18,range:110,speed:1.4}},\n    {b:[60,484],h:[300,130],par:3,walls:[[L,380,206,16],[130,250,206,16]]},\n    {b:[180,484],h:[180,128],par:3,walls:[[150,330,60,60],[L,210,96,16],[240,210,96,16]],mover:{y:170,w:70,h:14,range:80,speed:2}},\n  ];\n  const g={over:false,score:0,t:0,hole:0,strokes:0,state:'aim',ball:null,drag:null,parts:[],pops:[],timer:0,total:HOLES.length};\n  g.intro='Mini golf! <b>Press and pull back</b>, like a slingshot, then let go to putt. The dotted line shows where the ball will roll.<br>5 holes. Hole in one = 6 points, under par = more points!';\n  g.hud=()=>`⛳ Hole ${Math.min(g.hole+1,g.total)}/${g.total} · Par ${HOLES[Math.min(g.hole,g.total-1)].par} · Strokes ${g.strokes} · ⭐ ${g.score}`;\n  g.endTitle='Nice putting!';\n  const H0=()=>HOLES[Math.min(g.hole,g.total-1)];\n  function load(){const h=H0();g.ball={x:h.b[0],y:h.b[1],vx:0,vy:0};g.strokes=0;g.state='aim';g.mx=0;}\n  load();\n  const moverRect=(h,t)=>{const m=h.mover;if(!m)return null;const cx=180+Math.sin(t*m.speed*DF())*m.range;return [cx-m.w/2,m.y,m.w,m.h];};\n  const rects=t=>{const h=H0(),r=h.walls.slice(),m=moverRect(h,t);if(m)r.push(m);return r;};\n  // one physics step; returns 'in' if the ball drops\n  function step(b,dt,t){\n    b.x+=b.vx*dt;b.y+=b.vy*dt;\n    const sp=Math.hypot(b.vx,b.vy);if(sp>0){const ns=Math.max(0,sp*Math.exp(-1.15*dt)-26*dt);b.vx*=ns/sp;b.vy*=ns/sp;}\n    if(b.x<L+R){b.x=L+R;b.vx=Math.abs(b.vx)*.82;}if(b.x>Rt-R){b.x=Rt-R;b.vx=-Math.abs(b.vx)*.82;}\n    if(b.y<T+R){b.y=T+R;b.vy=Math.abs(b.vy)*.82;}if(b.y>B-R){b.y=B-R;b.vy=-Math.abs(b.vy)*.82;}\n    for(const [x,y,w,h] of rects(t)){\n      const cx=Math.max(x,Math.min(b.x,x+w)),cy=Math.max(y,Math.min(b.y,y+h)),dx=b.x-cx,dy=b.y-cy,d=Math.hypot(dx,dy);\n      if(d<R){const nx=d?dx/d:0,ny=d?dy/d:(b.y<y+h/2?-1:1);b.x=cx+nx*R;b.y=cy+ny*R;const dot=b.vx*nx+b.vy*ny;if(dot<0){b.vx-=1.82*dot*nx;b.vy-=1.82*dot*ny;}}\n    }\n    const hh=H0().h,dh=Math.hypot(b.x-hh[0],b.y-hh[1]),s2=Math.hypot(b.vx,b.vy);\n    if(dh<HR&&s2<420)return 'in';\n    if(dh<HR+4&&s2<520){b.vx+=(hh[0]-b.x)*2*dt*60;b.vy+=(hh[1]-b.y)*2*dt*60;}\n    return '';\n  }\n  const shotVel=()=>{const d=g.drag;if(!d)return null;const dx=d.sx-d.x,dy=d.sy-d.y,len=Math.hypot(dx,dy);if(len<12)return null;const p=Math.min(1,len/160);return {vx:dx/len*p*640,vy:dy/len*p*640,p};};\n  g.tap=(x,y)=>{if(g.state!=='aim')return;g.drag={sx:x,sy:y,x,y};};\n  g.move=(x,y)=>{if(g.drag){g.drag.x=x;g.drag.y=y;}};\n  g.release=()=>{\n    if(g.state!=='aim'||!g.drag)return;const v=shotVel();g.drag=null;if(!v)return;\n    g.ball.vx=v.vx;g.ball.vy=v.vy;g.strokes++;g.state='roll';sfx('hit');\n  };\n  g.update=dt=>{\n    g.t+=dt;stepParts(g.parts,dt,250);stepPops(g.pops,dt);\n    if(g.state==='roll'){\n      const b=g.ball;let res='';const n=3;for(let i=0;i<n&&!res;i++)res=step(b,dt/n,g.t);\n      if(res==='in'){\n        const h=H0(),s=g.strokes,pts=s===1?6:Math.max(1,4+(h.par-s));g.score+=pts;\n        const name=s===1?'HOLE IN ONE!':s<h.par?'Birdie!':s===h.par?'Par!':'In the cup!';\n        addPop(g.pops,`${name} +${pts}`,180,260,s<=h.par?'#fde047':'#fff',s===1?38:32);sfx(s===1?'hr':'win');burst(g.parts,h.h[0],h.h[1],['#fde047','#fff','#22c55e','#60a5fa'],30,200);\n        g.state='sunk';g.timer=1.6;b.x=h.h[0];b.y=h.h[1];b.vx=b.vy=0;\n      }else if(Math.hypot(b.vx,b.vy)<6){b.vx=b.vy=0;\n        if(g.strokes>=7){addPop(g.pops,'On to the next hole!',180,260,'#e2e8f0',28);g.score+=1;g.state='sunk';g.timer=1.4;}else g.state='aim';}\n    }else if(g.state==='sunk'){g.timer-=dt;if(g.timer<=0){g.hole++;if(g.hole>=g.total){g.over=true;return;}load();}}\n  };\n  g.draw=c=>{\n    c.fillStyle='#14532d';c.fillRect(0,0,W,H);\n    c.fillStyle='#86efac';c.fillRect(0,0,W,T-8);c.fillStyle='#14532d';c.font='700 14px Fredoka, sans-serif';c.textAlign='center';c.textBaseline='middle';c.fillText(`⛳ Hole ${g.hole+1} · Par ${H0().par}`,180,28);\n    c.fillStyle='#78350f';rr(c,L-10,T-10,Rt-L+20,B-T+20,14);c.fill();\n    const grn=c.createLinearGradient(0,T,0,B);grn.addColorStop(0,'#4ade80');grn.addColorStop(1,'#22c55e');c.fillStyle=grn;c.fillRect(L,T,Rt-L,B-T);\n    c.fillStyle='rgba(255,255,255,.06)';for(let y=T;y<B;y+=32)c.fillRect(L,y,Rt-L,16);\n    for(const [x,y,w,h] of rects(g.t)){c.fillStyle='#92400e';rr(c,x,y,w,h,5);c.fill();c.fillStyle='#b45309';rr(c,x+2,y+2,w-4,h/2-1,4);c.fill();}\n    const hh=H0().h;c.fillStyle='#052e16';c.beginPath();c.arc(hh[0],hh[1],HR,0,7);c.fill();\n    c.strokeStyle='#e5e7eb';c.lineWidth=2;c.beginPath();c.moveTo(hh[0],hh[1]);c.lineTo(hh[0],hh[1]-44);c.stroke();\n    c.fillStyle='#ef4444';c.beginPath();c.moveTo(hh[0],hh[1]-44);c.lineTo(hh[0]+22,hh[1]-37);c.lineTo(hh[0],hh[1]-30);c.fill();\n    const b=g.ball;\n    if(g.state==='aim'){\n      const v=shotVel();\n      if(v){\n        const sim={x:b.x,y:b.y,vx:v.vx,vy:v.vy},pts=[[b.x,b.y]];let t=g.t;\n        for(let i=0;i<150;i++){for(let k=0;k<3;k++){if(step(sim,1/180,t)){i=999;break;}t+=1/180;}if(i%3===0)pts.push([sim.x,sim.y]);if(Math.hypot(sim.vx,sim.vy)<6)break;}\n        pts.push([sim.x,sim.y]);\n        c.fillStyle='rgba(255,255,255,.85)';pts.forEach(([x,y],i)=>{if(i%2===0){c.beginPath();c.arc(x,y,2.6,0,7);c.fill();}});\n        const d=g.drag;c.strokeStyle=`rgba(255,${Math.round(255-v.p*180)},0,.9)`;c.lineWidth=5;c.lineCap='round';c.beginPath();c.moveTo(b.x,b.y);c.lineTo(b.x-(d.sx-d.x)*.5,b.y-(d.sy-d.y)*.5);c.stroke();\n        c.fillStyle='rgba(15,23,42,.65)';rr(c,120,B+2,120,14,7);c.fill();c.fillStyle='#fde047';rr(c,122,B+4,116*v.p,10,5);c.fill();\n      }else{c.fillStyle='rgba(255,255,255,.9)';c.font='700 14px Fredoka, sans-serif';c.textAlign='center';c.fillText('Press, pull back, let go',180,B+10);}\n    }\n    if(g.state!=='sunk'||Math.floor(g.t*6)%2){c.fillStyle='rgba(0,0,0,.25)';c.beginPath();c.arc(b.x+2,b.y+3,R,0,7);c.fill();c.fillStyle='#fff';c.beginPath();c.arc(b.x,b.y,R,0,7);c.fill();}\n    drawParts(c,g.parts);drawPops(c,g.pops);\n  };\n  return g;\n}\n\n/* ===== GAME 21: Tennis Rally ===== */\nfunction createTennis(){\n  const OY=118,HY=446,NY=286;\n  const g={over:false,score:0,t:0,lives:3,returns:0,state:'serve',timer:1,ball:null,px:180,ox:180,parts:[],pops:[],swing:0,best:0};\n  g.intro='Keep the rally going! The ball comes to you, and your player moves by itself. <b>Tap when the ball reaches the ring</b>. The ring turns green at the perfect moment.<br>Perfect hit = 2 points, good hit = 1. You have 3 balls. Reach 50 returns to win the match!';\n  g.hud=()=>`🎾 Rally ${g.returns} · ${'❤️'.repeat(g.lives)} · ⭐ ${g.score}`;\n  g.endTitle='Great rally!';\n  const speed=()=>Math.max(.55,1.25-g.returns*.035)/DF();\n  function serve(){const tx=rnd(90,270);g.ball={from:[g.ox,OY+10],to:[tx,HY],t:0,dur:speed(),dir:1,hit:false};g.state='in';}\n  const WIN=50; // a match ends after 50 returns so one token can't buy an endless rally\n  const tight=()=>Math.max(.6,1-g.returns*.008); // timing gets a little stricter as the rally grows\n  const W1=()=>.07*TOL()*tight(),W2=()=>.16*TOL()*tight();\n  g.tap=()=>{\n    if(g.swing>0)return;g.swing=.25;sfx('swoosh');\n    if(g.state!=='in'||g.ball.dir!==1||g.ball.hit)return;\n    const b=g.ball,e=b.t-b.dur;\n    if(e<-W2()){g.ball.hit=true;g.ball.whiff=true;return;}\n    if(Math.abs(e)<=W1()){g.score+=2;addPop(g.pops,'PERFECT!',g.px,HY-70,'#fde047',32);burst(g.parts,b.to[0],HY,['#fde047','#fff'],14,180);}\n    else{g.score+=1;addPop(g.pops,'Nice!',g.px,HY-70,'#86efac',28);}\n    sfx('hit');g.returns++;g.ox=rnd(90,270);\n    if(g.returns>=WIN){g.score+=25;g.best=g.returns;g.endTitle='Champion! 🏆';addPop(g.pops,'MATCH WON! +25',180,300,'#fde047',34);sfx('hr');g.state='out';g.lives=0;g.timer=1.6;g.ball=null;return;}\n    g.ball={from:[b.to[0],HY],to:[g.ox,OY+10],t:0,dur:speed()*.9,dir:-1};\n  };\n  g.update=dt=>{\n    g.t+=dt;stepParts(g.parts,dt,300);stepPops(g.pops,dt);g.swing=Math.max(0,g.swing-dt);\n    if(g.state==='serve'){g.timer-=dt;if(g.timer<=0)serve();return;}\n    if(g.state==='out'){g.timer-=dt;if(g.timer<=0){if(g.lives<=0){g.over=true;return;}g.state='serve';g.timer=.6;}return;}\n    const b=g.ball;b.t+=dt;\n    if(b.dir===1)g.px+=(b.to[0]-g.px)*Math.min(1,dt*5);\n    if(b.dir===-1){g.ox+=(b.to[0]-g.ox)*Math.min(1,dt*5);if(b.t>=b.dur){sfx('tick');const tx=rnd(80,280);g.ball={from:[b.to[0],OY+10],to:[tx,HY],t:0,dur:speed(),dir:1,hit:false};}}\n    else if(b.t-b.dur>W2()||(b.whiff&&b.t>b.dur+.1)){g.lives--;sfx('miss');addPop(g.pops,b.whiff?'Too early!':'Missed it!',180,330,'#fca5a5',32);g.best=Math.max(g.best,g.returns);g.state='out';g.timer=1.2;}\n  };\n  function ballPos(){const b=g.ball,q=Math.min(1.3,b.t/b.dur);const x=b.from[0]+(b.to[0]-b.from[0])*q,y=b.from[1]+(b.to[1]-b.from[1])*q,h=Math.sin(Math.min(1,q)*Math.PI)*60*(b.dir===1?1:.8);return {x,y,h};}\n  function player(c,x,y,top,sw){\n    c.fillStyle=top?'#ef4444':'#7c3aed';rr(c,x-12,y-22,24,28,8);c.fill();\n    c.fillStyle='#f5c9a0';c.beginPath();c.arc(x,y-30,9,0,7);c.fill();\n    c.fillStyle=top?'#1f2937':'#92400e';c.beginPath();c.arc(x,y-33,9,Math.PI,0);c.fill();\n    const a=top?.6:(-.9+sw*6);c.save();c.translate(x+14,y-12);c.rotate(a);c.strokeStyle='#334155';c.lineWidth=3;c.beginPath();c.moveTo(0,0);c.lineTo(0,-20);c.stroke();\n    c.strokeStyle='#0ea5e9';c.lineWidth=3;c.beginPath();c.ellipse(0,-30,8,11,0,0,7);c.stroke();c.restore();\n  }\n  g.draw=c=>{\n    c.fillStyle='#0f766e';c.fillRect(0,0,W,H);\n    c.fillStyle='#2563eb';c.fillRect(44,70,272,440);\n    c.strokeStyle='#fff';c.lineWidth=3;c.strokeRect(44,70,272,440);c.strokeRect(74,70,212,440);\n    c.beginPath();c.moveTo(74,180);c.lineTo(286,180);c.moveTo(74,400);c.lineTo(286,400);c.moveTo(180,180);c.lineTo(180,400);c.stroke();\n    c.fillStyle='#e5e7eb';c.fillRect(30,NY-3,300,6);c.fillStyle='rgba(255,255,255,.5)';for(let x=34;x<326;x+=8)c.fillRect(x,NY-12,1,12);c.fillStyle='#1f2937';c.fillRect(30,NY-14,300,3);\n    player(c,g.ox,OY,true,0);\n    // hit ring guide\n    if(g.state==='in'&&g.ball.dir===1){\n      const b=g.ball,e=b.t-b.dur,near=Math.abs(e)<=W1(),ok=Math.abs(e)<=W2();\n      c.strokeStyle=near?'rgba(74,222,128,.95)':ok?'rgba(253,224,71,.9)':'rgba(255,255,255,.55)';c.lineWidth=near?6:4;c.setLineDash(near?[]:[6,6]);\n      c.beginPath();c.arc(b.to[0],HY,22,0,7);c.stroke();c.setLineDash([]);\n    }\n    if(g.ball&&g.state==='in'){const p=ballPos();c.fillStyle='rgba(0,0,0,.25)';c.beginPath();c.ellipse(p.x,p.y,7,3,0,0,7);c.fill();\n      c.fillStyle='#d9f99d';c.beginPath();c.arc(p.x,p.y-p.h,8,0,7);c.fill();c.strokeStyle='#65a30d';c.lineWidth=1.5;c.beginPath();c.arc(p.x-4,p.y-p.h,6,-1,1);c.stroke();}\n    player(c,g.px,HY+28,false,g.swing);\n    if(g.state==='serve'&&g.returns===0&&g.lives===3)hintText(c,'Get ready…',330);\n    drawParts(c,g.parts);drawPops(c,g.pops);\n  };\n  return g;\n}\n\n/* ===== GAME 22: Letter Fishing ===== */\nfunction createFishing(){\n  const pool=wordPool(),T={easy:80,normal:70,hard:60}[S.set.diff]||70,LANES=6,LY=196,LG=54,BOATY=136;\n  const g={over:false,score:0,t:0,time:T,tmax:T,word:'',idx:0,fish:[],hook:null,parts:[],pops:[],done:0,wait:0};\n  g.intro=`Listen to the word, then <b>tap the fish</b> with the next letter to reel it in. Spell the whole word in order!<br>Catching the wrong fish costs 2 seconds. You have ${T} seconds.`;\n  g.hud=()=>`🎣 ${plural(g.done,'word')} · ⏱ ${Math.ceil(g.time)}s · ⭐ ${g.score}`;\n  g.endTitle='Great fishing!';\n  const need=()=>g.word[g.idx];\n  function addFish(l,lane){const dir=Math.random()<.5?1:-1;g.fish.push({l,lane,y:LY+lane*LG,x:dir>0?-30:W+30,dir,v:rnd(38,70)*DF(),c:pick(LETTER_COLS),wob:Math.random()*6});}\n  function next(){g.word=pickWord(pool,g.word);g.idx=0;speak(g.word);}\n  g.begin=()=>{next();for(let i=0;i<LANES;i++){addFish(i%2?need():pick(ABC),i);const f=g.fish[g.fish.length-1];f.x=rnd(40,W-40);}};\n  g.tap=(x,y)=>{\n    if(hitCircle(x,y,W-34,62,18)){speak(g.word);return;}\n    if(g.hook||g.wait>0)return;\n    let best=null,bd=1e9;for(const f of g.fish){const d=Math.hypot(f.x-x,f.y-y);if(d<34&&d<bd){bd=d;best=f;}}\n    if(!best)return;g.hook={f:best,t:0,phase:'down'};best.caught=true;sfx('swoosh');\n  };\n  g.update=dt=>{\n    g.t+=dt;g.time-=dt;if(g.time<=0){g.time=0;g.over=true;return;}\n    stepParts(g.parts,dt,250);stepPops(g.pops,dt);\n    if(g.wait>0){g.wait-=dt;if(g.wait<=0)next();}\n    for(const f of g.fish){if(f.caught)continue;f.x+=f.dir*f.v*dt;f.wob+=dt*4;}\n    g.fish=g.fish.filter(f=>f.caught||(f.x>-50&&f.x<W+50));\n    for(let i=0;i<LANES;i++)if(!g.fish.some(f=>f.lane===i&&!f.caught&&(f.dir>0?f.x<W*.7:f.x>W*.3))){const n=need();addFish(n&&g.wait<=0&&!g.fish.some(f=>f.l===n&&!f.caught)?n:(Math.random()<.35&&n?n:pick(ABC)),i);}\n    const h=g.hook;\n    if(h){h.t+=dt;\n      if(h.phase==='down'&&h.t>.3){h.phase='up';h.t=0;\n        if(g.wait<=0&&h.f.l===need()){h.good=true;g.idx++;g.score+=1;sfx('pop');burst(g.parts,h.f.x,h.f.y,[h.f.c,'#fff','#7dd3fc'],12,150);\n          if(g.idx>=g.word.length){g.done++;g.score+=g.word.length;addTime(g,3);addPop(g.pops,`${g.word.toUpperCase()}! +${g.word.length}`,180,170,'#fde047',34);sfx('win');g.wait=1;}}\n        else{h.good=false;g.time=Math.max(0,g.time-2);sfx('nope');addPop(g.pops,'−2s · Need '+(need()||'').toUpperCase(),180,170,'#fca5a5',22);}}\n      else if(h.phase==='up'&&h.t>.35){g.fish=g.fish.filter(f=>f!==h.f);if(!h.good){h.f.caught=false;h.f.dir*=-1;h.f.v*=1.6;g.fish.push(h.f);}g.hook=null;}\n    }\n  };\n  g.draw=c=>{\n    const sky=c.createLinearGradient(0,0,0,170);sky.addColorStop(0,'#bae6fd');sky.addColorStop(1,'#e0f2fe');c.fillStyle=sky;c.fillRect(0,0,W,170);\n    const wa=c.createLinearGradient(0,160,0,H);wa.addColorStop(0,'#38bdf8');wa.addColorStop(1,'#0c4a6e');c.fillStyle=wa;c.fillRect(0,160,W,H-160);\n    c.strokeStyle='rgba(255,255,255,.35)';c.lineWidth=2;for(let i=0;i<5;i++){c.beginPath();for(let x=0;x<=W;x+=10)c.lineTo(x,162+Math.sin(x/22+g.t*2+i)*2+i*.3);c.stroke();}\n    c.fillStyle='#16a34a';c.beginPath();c.ellipse(20,H-10,60,40,0,0,7);c.fill();c.beginPath();c.ellipse(W-10,H-6,50,34,0,0,7);c.fill();\n    wordHeader(c,g,'CATCH THE LETTERS IN ORDER');timeBar(c,g,100);\n    emo(c,LOOKS.fishing?'⛵':'🛶',180,BOATY+10,54);emo(c,'🧒',176,BOATY-14,30);\n    for(const f of g.fish){\n      if(g.hook&&g.hook.f===f)continue;\n      c.save();c.translate(f.x,f.y+Math.sin(f.wob)*3);c.scale(f.dir,1);\n      c.fillStyle=f.c;c.beginPath();c.ellipse(0,0,26,17,0,0,7);c.fill();c.beginPath();c.moveTo(-22,0);c.lineTo(-38,-13);c.lineTo(-38,13);c.fill();\n      c.fillStyle='#fff';c.beginPath();c.arc(14,-5,4.5,0,7);c.fill();c.fillStyle='#111';c.beginPath();c.arc(15,-5,2.2,0,7);c.fill();c.restore();\n      c.fillStyle='#fff';c.font='700 20px Fredoka, sans-serif';c.textAlign='center';c.textBaseline='middle';c.fillText(f.l.toUpperCase(),f.x-f.dir*3,f.y+Math.sin(f.wob)*3+1);\n    }\n    const h=g.hook;\n    if(h){const q=h.phase==='down'?h.t/.3:1-h.t/.35,ty=BOATY+(h.f.y-BOATY)*q,tx=180+(h.f.x-180)*q;\n      c.strokeStyle='#f8fafc';c.lineWidth=2;c.beginPath();c.moveTo(196,BOATY-30);c.lineTo(tx,ty);c.stroke();\n      if(h.phase==='up'){c.save();c.translate(tx,ty+18);c.rotate(Math.PI/2);c.fillStyle=h.f.c;c.beginPath();c.ellipse(0,0,24,15,0,0,7);c.fill();c.restore();\n        c.fillStyle='#fff';c.font='700 18px Fredoka, sans-serif';c.textAlign='center';c.textBaseline='middle';c.fillText(h.f.l.toUpperCase(),tx,ty+18);}\n    }\n    drawParts(c,g.parts);drawPops(c,g.pops);\n  };\n  return g;\n}\n\n/* ===== GAME 23: Spelling Bee Hive ===== */\nfunction createBeeHive(){\n  const pool=wordPool(),T={easy:80,normal:70,hard:60}[S.set.diff]||70,HXR=31;\n  const g={over:false,score:0,t:0,time:T,tmax:T,word:'',idx:0,cells:[],bee:{x:180,y:150},path:[],parts:[],pops:[],done:0,wait:0};\n  g.intro=`Listen to the word, then <b>tap the honeycomb letters in order</b> to spell it. The 🐝 bee flies along your path!<br>Wrong letters cost 2 seconds. You have ${T} seconds.`;\n  g.hud=()=>`🐝 ${plural(g.done,'word')} · ⏱ ${Math.ceil(g.time)}s · ⭐ ${g.score}`;\n  g.endTitle='Busy bee!';\n  const need=()=>g.word[g.idx];\n  const SLOTS=[];{const dx=HXR*1.78,dy=HXR*1.55;const rows=[5,4,5,4];rows.forEach((n,ri)=>{const w=(n-1)*dx,x0=180-w/2;for(let i=0;i<n;i++)SLOTS.push([x0+i*dx,214+ri*dy]);});}\n  function build(){\n    const letters=[...g.word],extra=Math.max(0,Math.min(SLOTS.length,letters.length+5)-letters.length);\n    const all=shuffle(letters.concat(decoys(g.word,extra))),spots=shuffle(SLOTS.slice()).slice(0,all.length);\n    g.cells=all.map((l,i)=>({l,x:spots[i][0],y:spots[i][1],used:false,shake:0}));g.path=[];g.bee={x:180,y:150};\n  }\n  function next(){g.word=pickWord(pool,g.word);g.idx=0;build();speak(g.word);}\n  g.begin=()=>next();\n  g.tap=(x,y)=>{\n    if(hitCircle(x,y,W-34,62,18)){speak(g.word);return;}\n    if(g.wait>0||g.cool>0)return;\n    const cell=g.cells.find(cl=>!cl.used&&Math.hypot(cl.x-x,cl.y-y)<HXR*.95);if(!cell)return;\n    if(cell.l===need()){cell.used=true;g.idx++;g.score+=1;g.path.push([cell.x,cell.y]);sfx('pop');burst(g.parts,cell.x,cell.y,['#fde047','#f59e0b','#fff'],10,140);\n      if(g.idx>=g.word.length){g.done++;g.score+=g.word.length;addTime(g,3);addPop(g.pops,`${g.word.toUpperCase()}! +${g.word.length}`,180,170,'#fde047',34);sfx('win');g.wait=1.2;}}\n    else{cell.shake=.4;g.cool=.4;g.time=Math.max(0,g.time-2);sfx('nope');addPop(g.pops,'−2s · Need '+(need()||'').toUpperCase(),180,170,'#fca5a5',22);}\n  };\n  function hex(c,x,y,r){c.beginPath();for(let i=0;i<6;i++){const a=Math.PI/6+i*Math.PI/3;c.lineTo(x+Math.cos(a)*r,y+Math.sin(a)*r);}c.closePath();}\n  g.update=dt=>{\n    g.t+=dt;g.cool=Math.max(0,(g.cool||0)-dt);g.time-=dt;if(g.time<=0){g.time=0;g.over=true;return;}\n    stepParts(g.parts,dt,200);stepPops(g.pops,dt);\n    if(g.wait>0){g.wait-=dt;if(g.wait<=0)next();}\n    for(const cl of g.cells)cl.shake=Math.max(0,cl.shake-dt);\n    const tgt=g.path.length?g.path[g.path.length-1]:[180,150];\n    g.bee.x+=(tgt[0]-g.bee.x)*Math.min(1,dt*7);g.bee.y+=(tgt[1]-14-g.bee.y)*Math.min(1,dt*7);\n  };\n  g.draw=c=>{\n    const bg=c.createLinearGradient(0,0,0,H);bg.addColorStop(0,'#fef9c3');bg.addColorStop(1,'#fde68a');c.fillStyle=bg;c.fillRect(0,0,W,H);\n    for(let i=0;i<7;i++)emo(c,'🌼',20+i*55,H-16+Math.sin(i)*4,26);\n    wordHeader(c,g,'TAP THE LETTERS IN ORDER');timeBar(c,g,100);\n    for(const cl of g.cells){\n      const sx=cl.shake?Math.sin(cl.shake*60)*5:0;\n      c.fillStyle=cl.used?'#f59e0b':cl.shake?'#fecaca':'#fef3c7';hex(c,cl.x+sx,cl.y,HXR-2);c.fill();\n      c.strokeStyle='#b45309';c.lineWidth=3;c.stroke();\n      c.fillStyle=cl.used?'#fff':'#78350f';c.font='700 24px Fredoka, sans-serif';c.textAlign='center';c.textBaseline='middle';c.fillText(cl.l.toUpperCase(),cl.x+sx,cl.y+1);\n    }\n    if(g.path.length>1)dashLine(c,g.path,'rgba(120,53,15,.6)',3,-g.t*20);\n    emo(c,LOOKS.beehive?'🦋':'🐝',g.bee.x,g.bee.y+Math.sin(g.t*8)*3,34);\n    drawParts(c,g.parts);drawPops(c,g.pops);\n  };\n  return g;\n}\n\n/* ===== GAME 24: Letter Train ===== */\nfunction createTrain(){\n  const pool=wordPool(),ROUNDS=6,TY=176,CW=34,CH=30;\n  const g={over:false,score:0,t:0,round:0,word:'',idx:0,cars:[],clock:0,clockMax:1,state:'load',leave:0,parts:[],pops:[]};\n  g.intro='All aboard! Listen to the word, then <b>tap the train cars in order</b> to hook them to the engine. Finish before the clock runs out and the train leaves!<br>6 words. Faster = more points.';\n  g.hud=()=>`🚂 Word ${Math.min(g.round,ROUNDS)}/${ROUNDS} · ⭐ ${g.score}`;\n  g.endTitle='Next stop: Spelling Star!';\n  const need=()=>g.word[g.idx];\n  function next(){\n    g.round++;g.word=pickWord(pool,g.word);g.idx=0;g.state='load';g.leave=0;\n    const letters=shuffle([...g.word].concat(decoys(g.word,Math.min(3,Math.max(2,8-g.word.length)))));\n    const per=Math.ceil(letters.length/2);\n    g.cars=letters.map((l,i)=>{const row=i<per?0:1,col=row?i-per:i,n=row?letters.length-per:per,gap=Math.min(48,(W-40)/n);\n      return {l,c:pick(LETTER_COLS),x:180-(n-1)*gap/2+col*gap,y:row?432:352,on:false,shake:0};});\n    g.clockMax=g.clock=(7+g.word.length*2.4)/DF();speak(g.word);\n  }\n  g.begin=()=>next();\n  const slotX=i=>98+i*(CW+4);\n  g.tap=(x,y)=>{\n    if(hitCircle(x,y,W-34,62,18)){speak(g.word);return;}\n    if(g.state!=='load')return;\n    const car=g.cars.find(cr=>!cr.on&&Math.abs(cr.x-x)<CW/2+4&&Math.abs(cr.y-y)<CH/2+6);if(!car)return;\n    if(car.l===need()){car.on=true;car.slot=g.idx;g.idx++;g.score+=1;sfx('pop');\n      if(g.idx>=g.word.length){const bonus=Math.ceil(g.clock/g.clockMax*5);g.score+=g.word.length+bonus;addPop(g.pops,`${g.word.toUpperCase()}! +${g.word.length+bonus}`,180,270,'#fde047',34);sfx('win');g.state='go';g.leave=0;}}\n    else{car.shake=.4;g.clock=Math.max(0,g.clock-1);sfx('nope');addPop(g.pops,'Need '+(need()||'').toUpperCase(),180,270,'#fca5a5',24);}\n  };\n  g.update=dt=>{\n    g.t+=dt;stepParts(g.parts,dt,150);stepPops(g.pops,dt);\n    for(const cr of g.cars){cr.shake=Math.max(0,cr.shake-dt);if(cr.on){const tx=slotX(cr.slot)+(g.state!=='load'?g.leave*420:0);cr.x+=(tx-cr.x)*Math.min(1,dt*10);cr.y+=(TY-cr.y)*Math.min(1,dt*10);}}\n    if(g.state==='load'){g.clock-=dt;if(g.clock<=0){g.state='missed';g.leave=0;addPop(g.pops,`Train left! It was ${g.word.toUpperCase()}`,180,270,'#fca5a5',22);sfx('miss');speak(g.word);}}\n    else{g.leave+=dt*.8;if(Math.random()<dt*10)g.parts.push({x:50+g.leave*420,y:TY-46,vx:rnd(-20,20),vy:-40,life:1,c:'rgba(226,232,240,.8)',r:rnd(6,10)});\n      if(g.leave>1.3){if(g.round>=ROUNDS){g.over=true;return;}next();}}\n  };\n  g.draw=c=>{\n    const sky=c.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#bfdbfe');sky.addColorStop(.55,'#e0f2fe');sky.addColorStop(.55,'#bbf7d0');sky.addColorStop(1,'#86efac');c.fillStyle=sky;c.fillRect(0,0,W,H);\n    drawCloud(c,60,150,.6);drawCloud(c,260,130,.5);\n    wordHeader(c,g,'HOOK THE CARS IN ORDER');\n    const tf=Math.max(0,g.clock/g.clockMax);c.fillStyle='rgba(255,255,255,.7)';rr(c,20,100,W-40,10,5);c.fill();c.fillStyle=tf>.3?'#22c55e':'#ef4444';rr(c,20,100,(W-40)*(g.state==='load'?tf:0),10,5);c.fill();\n    const rail=y=>{c.fillStyle='#78350f';for(let x=4;x<W;x+=18)c.fillRect(x,y+CH/2-2,10,8);c.fillStyle='#64748b';c.fillRect(0,y+CH/2,W,3);};\n    rail(TY);rail(352);rail(432);\n    c.fillStyle='#475569';c.font='600 12px Fredoka, sans-serif';c.textAlign='center';c.fillText('🚉 TRAIN YARD',180,326);\n    const ex=50+(g.state!=='load'?g.leave*420:0);\n    emo(c,LOOKS.train?'🚅':'🚂',ex,TY-6,58,true);\n    for(const cr of g.cars){const sx=cr.shake?Math.sin(cr.shake*60)*5:0;\n      c.fillStyle=cr.c;rr(c,cr.x-CW/2+sx,cr.y-CH/2,CW,CH,6);c.fill();c.fillStyle='#1f2937';c.beginPath();c.arc(cr.x-9+sx,cr.y+CH/2,5,0,7);c.arc(cr.x+9+sx,cr.y+CH/2,5,0,7);c.fill();\n      c.fillStyle='#fff';c.font='700 20px Fredoka, sans-serif';c.textAlign='center';c.textBaseline='middle';c.fillText(cr.l.toUpperCase(),cr.x+sx,cr.y);}\n    drawParts(c,g.parts);drawPops(c,g.pops);\n  };\n  return g;\n}\n\n/* ===== GAME 25: Word Bowling ===== */\nfunction createWordBowl(){\n  const pool=wordPool(),ROUNDS=6,BALLY=480;\n  const g={over:false,score:0,t:0,round:0,word:'',idx:0,pins:[],ball:{x:180,y:480,t:1,target:null},miss:0,state:'play',timer:0,parts:[],pops:[]};\n  g.intro='Each pin has a letter. Listen to the word, then <b>tap the pins in spelling order</b> to roll the ball at them!<br>Spell a word with no misses for a STRIKE bonus. 6 words.';\n  g.hud=()=>`🎳 Word ${Math.min(g.round,ROUNDS)}/${ROUNDS} · ⭐ ${g.score}`;\n  g.endTitle='Letter-perfect bowling!';\n  const need=()=>g.word[g.idx];\n  function next(){\n    g.round++;g.word=pickWord(pool,g.word);g.idx=0;g.miss=0;g.state='play';\n    const letters=shuffle([...g.word].concat(decoys(g.word,Math.min(15,g.word.length+3)-g.word.length)));\n    const rows=[];let left=letters.length;for(let n=1;left>0;n++){rows.push(Math.min(n,left));left-=n;}\n    rows.reverse();let k=0;g.pins=[];\n    rows.forEach((n,ri)=>{const y=170+ri*50,gap=50;for(let i=0;i<n;i++){g.pins.push({l:letters[k++],x:180-(n-1)*gap/2+i*gap,y,up:true,wob:0,vx:0,vy:0,rot:0});}});\n    g.ball={x:180,y:BALLY,tx:180,ty:BALLY,t:1,target:null};speak(g.word);\n  }\n  g.begin=()=>next();\n  g.tap=(x,y)=>{\n    if(hitCircle(x,y,W-34,62,18)){speak(g.word);return;}\n    if(g.state!=='play'||g.ball.target)return;\n    const p=g.pins.find(p=>p.up&&Math.hypot(p.x-x,p.y-y)<26);if(!p)return;\n    g.ball={x:180,y:BALLY,sx:180,sy:BALLY,t:0,target:p};sfx('swoosh');\n  };\n  g.update=dt=>{\n    g.t+=dt;stepParts(g.parts,dt,300);stepPops(g.pops,dt);\n    for(const p of g.pins){p.wob=Math.max(0,p.wob-dt);if(!p.up){p.x+=p.vx*dt;p.y+=p.vy*dt;p.rot+=dt*10;}}\n    const b=g.ball;\n    if(b&&b.target){b.t+=dt/(.45/DF());const p=b.target;b.x=b.sx+(p.x-b.sx)*Math.min(1,b.t);b.y=b.sy+(p.y-b.sy)*Math.min(1,b.t);\n      if(b.t>=1){\n        if(p.l===need()){p.up=false;p.vx=rnd(-160,160);p.vy=-rnd(120,220);g.idx++;g.score+=1;sfx('pop');burst(g.parts,p.x,p.y,['#fff','#ef4444','#fde047'],12,170);\n          if(g.idx>=g.word.length){const strike=g.miss===0;const pts=g.word.length+(strike?5:0);g.score+=pts;addPop(g.pops,strike?`STRIKE! ${g.word.toUpperCase()} +${pts}`:`${g.word.toUpperCase()}! +${pts}`,180,300,'#fde047',30);sfx(strike?'hr':'win');g.state='done';g.timer=1.4;}}\n        else{p.wob=.5;g.miss++;sfx('bonk');addPop(g.pops,'Need '+(need()||'').toUpperCase(),p.x,p.y-30,'#fca5a5',22);}\n        g.ball={x:180,y:BALLY,t:1,target:null};\n      }}\n    if(g.state==='done'){g.timer-=dt;if(g.timer<=0){if(g.round>=ROUNDS){g.over=true;return;}next();}}\n  };\n  g.draw=c=>{\n    c.fillStyle='#1e1b4b';c.fillRect(0,0,W,H);\n    const lane=c.createLinearGradient(40,0,320,0);lane.addColorStop(0,'#d6a46c');lane.addColorStop(.5,'#f0c98e');lane.addColorStop(1,'#d6a46c');c.fillStyle=lane;c.fillRect(30,120,300,H-120);\n    c.fillStyle='#4b5563';c.fillRect(18,120,12,H);c.fillRect(330,120,12,H);\n    wordHeader(c,g,'KNOCK DOWN THE LETTERS IN ORDER');\n    for(const p of g.pins){if(!p.up&&(p.y<60||p.x<0||p.x>W))continue;\n      const sx=p.wob?Math.sin(p.wob*50)*4:0;c.save();c.translate(p.x+sx,p.y);c.rotate(p.up?0:p.rot);\n      c.fillStyle=p.up?'#fff':'rgba(255,255,255,.7)';c.beginPath();c.ellipse(0,4,15,19,0,0,7);c.fill();c.beginPath();c.arc(0,-14,9,0,7);c.fill();\n      c.fillStyle='#ef4444';c.fillRect(-9,-8,18,4);\n      c.fillStyle='#1e1b4b';c.font='700 18px Fredoka, sans-serif';c.textAlign='center';c.textBaseline='middle';c.fillText(p.l.toUpperCase(),0,8);c.restore();}\n    const b=g.ball;if(b){c.fillStyle='#7c3aed';c.beginPath();c.arc(b.x,b.y,16-(b.target?Math.min(1,b.t)*5:0),0,7);c.fill();c.fillStyle='#1e1b4b';c.beginPath();c.arc(b.x-4,b.y-4,2.5,0,7);c.arc(b.x+4,b.y-5,2.5,0,7);c.fill();}\n    if(g.state==='play'&&!g.ball.target)hintText(c,'Tap a pin to roll',520);\n    drawParts(c,g.parts);drawPops(c,g.pops);\n  };\n  return g;\n}\n\n/* ===== GAME 26: Dino Dash ===== */\nfunction createDino(){\n  const GY=430,DX=78;\n  const g={over:false,score:0,t:0,dist:0,stars:0,hearts:3,inv:0,y:GY,vy:0,jumps:0,obs:[],items:[],sT:1.2,iT:2,parts:[],pops:[],hills:[0,0]};\n  g.intro='Run, dino, run! <b>Tap to jump</b> over the cactuses. Tap again in the air for a double jump! Grab ⭐ stars for bonus points.<br>You have 3 hearts, and the dino gets faster as you go.';\n  g.hud=()=>`🦖 ${Math.floor(g.dist/30)}m · ⭐ ${g.stars} · ${'❤️'.repeat(g.hearts)} · ${g.score}`;\n  g.endTitle='What a run!';\n  const speed=()=>Math.min(430,(210+g.t*5)*DF());\n  g.tap=()=>{if(g.jumps<2){g.vy=g.jumps?-500:-600;g.jumps++;sfx('jump');}};\n  g.update=dt=>{\n    g.t+=dt;stepParts(g.parts,dt,400);stepPops(g.pops,dt);g.inv=Math.max(0,g.inv-dt);\n    const sp=speed();g.dist+=sp*dt;g.hills[0]=(g.hills[0]+sp*.2*dt)%400;g.hills[1]=(g.hills[1]+sp*.5*dt)%300;\n    g.vy+=1650*dt;g.y+=g.vy*dt;if(g.y>=GY){g.y=GY;g.vy=0;g.jumps=0;}\n    g.sT-=dt;if(g.sT<=0){const big=Math.random()<.35;g.obs.push({x:W+30,w:big?30:22,h:big?52:40,two:Math.random()<.18&&g.t>15});g.sT=rnd(.95,1.8)*(300/sp)*(TOL());}\n    g.iT-=dt;if(g.iT<=0){g.items.push({x:W+20,y:rnd(290,370),ph:rnd(0,6.28)});g.iT=rnd(1.4,2.6);}\n    for(const o of g.obs){o.x-=sp*dt;\n      const ow=o.two?o.w*1.9:o.w;\n      if(!o.hit&&g.inv<=0&&DX+14>o.x-ow/2&&DX-14<o.x+ow/2&&g.y>GY-o.h+6){o.hit=true;g.hearts--;g.inv=1.2;sfx('bonk');addPop(g.pops,'Ouch!',DX+40,GY-80,'#fca5a5',28);if(g.hearts<=0){g.over=true;}}}\n    for(const it of g.items){it.x-=sp*dt;if(!it.got&&Math.hypot(it.x-DX,it.y-(g.y-28))<34){it.got=true;g.stars++;sfx('star');burst(g.parts,it.x,it.y,['#fde047','#fff'],10,140);addPop(g.pops,'+5',it.x,it.y-20,'#fde047',24);}}\n    g.obs=g.obs.filter(o=>o.x>-60);g.items=g.items.filter(i=>i.x>-30&&!i.got);\n    g.score=Math.floor(g.dist/30)+g.stars*5;\n  };\n  g.draw=c=>{\n    const sky=c.createLinearGradient(0,0,0,GY);sky.addColorStop(0,'#fdba74');sky.addColorStop(1,'#fef3c7');c.fillStyle=sky;c.fillRect(0,0,W,H);\n    c.fillStyle='#fde047';c.beginPath();c.arc(290,110,34,0,7);c.fill();\n    c.fillStyle='#f4a261';for(let i=-1;i<3;i++){const x=i*400-g.hills[0];c.beginPath();c.moveTo(x,GY);c.quadraticCurveTo(x+100,230,x+200,GY);c.quadraticCurveTo(x+300,280,x+400,GY);c.fill();}\n    c.fillStyle='#e76f51';for(let i=-1;i<3;i++){const x=i*300-g.hills[1];c.beginPath();c.moveTo(x,GY);c.quadraticCurveTo(x+80,330,x+150,GY);c.fill();}\n    c.fillStyle='#d4a373';c.fillRect(0,GY+8,W,H-GY);c.fillStyle='#a16207';for(let x=-(g.dist%40);x<W;x+=40)c.fillRect(x,GY+24,16,3);\n    for(const it of g.items)emo(c,'⭐',it.x,it.y+Math.sin(g.t*3+it.ph)*6,30);\n    for(const o of g.obs){emo(c,'🌵',o.x,GY+8-o.h/2,o.h*1.15);if(o.two)emo(c,'🌵',o.x+o.w*.9,GY+8-o.h/2,o.h*1.15);}\n    if(!(g.inv>0&&Math.floor(g.inv*12)%2)){const run=g.y>=GY?Math.sin(g.t*20)*3:0;emo(c,LOOKS.dino?'🦘':'🦖',DX,g.y-22+run,56,true);}\n    c.fillStyle='rgba(0,0,0,.15)';c.beginPath();c.ellipse(DX,GY+8,20*(1-(GY-g.y)/400),5,0,0,7);c.fill();\n    if(g.t<3)hintText(c,'Tap to jump!',200);\n    drawParts(c,g.parts);drawPops(c,g.pops);\n  };\n  return g;\n}\n\n/* ===== GAME 27: Puppy Fetch ===== */\n// Puppy Fetch's ball, drawn here: some phones draw the tennis emoji as a racket and ball.\nfunction fetchBall(c,x,y,r){c.save();c.translate(x,y);\n  const gr=c.createRadialGradient(-r*.35,-r*.35,r*.1,0,0,r);gr.addColorStop(0,'#f7ff9e');gr.addColorStop(.6,'#d4e631');gr.addColorStop(1,'#9fb51a');\n  c.fillStyle=gr;c.beginPath();c.arc(0,0,r,0,7);c.fill();\n  c.strokeStyle='#ffffff';c.lineWidth=Math.max(1.5,r*.16);c.lineCap='round';\n  c.beginPath();c.arc(-r*1.35,0,r*.95,-.75,.75);c.stroke();c.beginPath();c.arc(r*1.35,0,r*.95,Math.PI-.75,Math.PI+.75);c.stroke();\n  c.restore();}\nfunction createPuppy(){\n  const GY=452,BX=74,BY=380,GRAV=520;\n  const g={over:false,score:0,t:0,toss:0,total:10,catches:0,state:'aim',drag:null,ball:null,px:260,tx:260,pj:0,timer:0,parts:[],pops:[],hearts:[]};\n  g.intro='Play fetch! <b>Press and pull back</b> like a slingshot, then let go to toss the ball. The dashed arc shows where it will fly. Toss it right to the 🐶 puppy!<br>10 tosses. Catch in the air = 3 points, close landing = 1.';\n  g.hud=()=>`🐶 Toss ${Math.min(g.toss+1,g.total)}/${g.total} · Catches ${g.catches} · ⭐ ${g.score}`;\n  g.endTitle='Good puppy!';\n  const CY=()=>GY-48,catchR=()=>30*TOL();\n  function newSpot(){g.tx=rnd(170,320);}\n  newSpot();\n  const vel=()=>{const d=g.drag;if(!d)return null;const dx=d.sx-d.x,dy=d.sy-d.y,len=Math.hypot(dx,dy);if(len<12)return null;const p=Math.min(1,len/170);return {vx:dx/len*p*560,vy:dy/len*p*560,p};};\n  function traj(v){const pts=[];let x=BX,y=BY,vx=v.vx,vy=v.vy;for(let i=0;i<120;i++){pts.push([x,y]);x+=vx/60;y+=vy/60;vy+=GRAV/60;if(y>GY||x>W+20)break;}pts.push([x,Math.min(y,GY)]);return pts;}\n  g.tap=(x,y)=>{if(g.state!=='aim')return;g.drag={sx:x,sy:y,x,y};};\n  g.move=(x,y)=>{if(g.drag){g.drag.x=x;g.drag.y=y;}};\n  g.release=()=>{if(g.state!=='aim'||!g.drag)return;const v=vel();g.drag=null;if(!v)return;g.ball={x:BX,y:BY,vx:v.vx,vy:v.vy,spin:0};g.state='fly';g.toss++;sfx('swoosh');};\n  g.update=dt=>{\n    g.t+=dt;stepParts(g.parts,dt,200);stepPops(g.pops,dt);\n    g.px+=(g.tx-g.px)*Math.min(1,dt*3);\n    if(g.state==='fly'){\n      const b=g.ball;b.x+=b.vx*dt;b.y+=b.vy*dt;b.vy+=GRAV*dt;b.spin+=dt*10;\n      const dx=b.x-g.px;\n      if(Math.abs(dx)<90&&b.vy>0)g.pj=Math.min(1,g.pj+dt*4);\n      const mouthY=CY()-g.pj*40;\n      if(Math.hypot(dx,b.y-mouthY)<catchR()){g.catches++;g.score+=3;addPop(g.pops,'GREAT CATCH! +3',180,240,'#fde047',34);sfx('hr');burst(g.parts,g.px,mouthY,['#f472b6','#fde047','#fff'],20,180);g.state='done';g.timer=1.4;g.caught=true;}\n      else if(b.y>=GY-6||b.x>W+20){b.y=Math.min(b.y,GY-6);const d=Math.abs(b.x-g.px);\n        if(d<55*TOL()){g.score+=1;addPop(g.pops,'Fetched! +1',180,240,'#86efac',30);sfx('win');g.tx=b.x;}\n        else{addPop(g.pops,b.x<g.px?'Too short!':'Too far!',180,240,'#fca5a5',30);sfx('miss');g.tx=Math.min(W-30,b.x);}\n        g.state='done';g.timer=1.5;g.caught=false;}\n    }else if(g.state==='done'){g.timer-=dt;g.pj=Math.max(0,g.pj-dt*3);if(g.timer<=0){if(g.toss>=g.total){g.over=true;return;}g.state='aim';g.ball=null;newSpot();}}\n    else g.pj=Math.max(0,g.pj-dt*3);\n  };\n  g.draw=c=>{\n    const sky=c.createLinearGradient(0,0,0,GY);sky.addColorStop(0,'#7dd3fc');sky.addColorStop(1,'#e0f2fe');c.fillStyle=sky;c.fillRect(0,0,W,H);\n    drawCloud(c,40,90,.7);drawCloud(c,220,140,.55);\n    c.fillStyle='#4ade80';c.fillRect(0,GY,W,H-GY);c.fillStyle='#22c55e';for(let x=0;x<W;x+=14){c.beginPath();c.moveTo(x,GY);c.lineTo(x+5,GY-8);c.lineTo(x+10,GY);c.fill();}\n    emo(c,'🌳',330,GY-60,100);\n    emo(c,'🧒',BX-26,GY-34,62);\n    // puppy target spot\n    c.strokeStyle='rgba(255,255,255,.7)';c.lineWidth=3;c.setLineDash([5,5]);c.beginPath();c.ellipse(g.tx,GY+6,26,6,0,0,7);c.stroke();c.setLineDash([]);\n    if(g.state==='aim'){\n      const v=vel();\n      if(v){const pts=traj(v),end=pts[pts.length-1],mouth=[g.px,CY()-30];const close=pts.some(([x,y])=>Math.hypot(x-mouth[0],y-mouth[1])<catchR()+6);\n        dashLine(c,pts,close?'rgba(22,163,74,.95)':'rgba(255,255,255,.85)',4,-g.t*30);\n        c.fillStyle=close?'#16a34a':'#fff';c.beginPath();c.arc(end[0],end[1],5,0,7);c.fill();\n        c.fillStyle='rgba(15,23,42,.6)';rr(c,20,GY+40,120,14,7);c.fill();c.fillStyle='#fde047';rr(c,22,GY+42,116*v.p,10,5);c.fill();}\n      else hintText(c,'Press, pull back, let go',GY+58);\n    }\n    const py=CY()+16-g.pj*40;emo(c,LOOKS.puppy?'🐱':'🐶',g.px,py,58,true);\n    if(g.state==='done'&&g.caught)fetchBall(c,g.px+18,py+8,10);\n    const b=g.ball;if(b&&!(g.state==='done'&&g.caught)){c.save();c.translate(b.x,b.y);c.rotate(b.spin);fetchBall(c,0,0,11);c.restore();}\n    if(g.state==='aim'&&!g.ball)fetchBall(c,BX,BY,11);\n    drawParts(c,g.parts);drawPops(c,g.pops);\n  };\n  return g;\n}\n\nconst GAMES={derby:createDerby,unicorn:createUnicorn,balloon:createBalloon,memory:createMemory,icecream:createIceCream,space:createSpace,bonk:createBonk,race:createRace,soccer:createSoccer,hoops:createHoops,catcher:createCatcher,moonrocket:createMoonRocket,scramble:createScramble,snake:createSnake,wheel:createWheel,detective:createDetective,fieldgoal:createFieldGoal,hockey:createHockey,bowling:createBowling,minigolf:createMiniGolf,tennis:createTennis,fishing:createFishing,beehive:createBeeHive,train:createTrain,wordbowl:createWordBowl,dino:createDino,puppy:createPuppy};\nopenGame(INIT.id);\npost({t:'ready'});\n</script>\n</body></html>\n";
